void add_record(int key, long offset) {
    Record* new_record = my_malloc(sizeof(Record));
    new_record->key = key;
    new_record->offset = offset;

    // Lock for concurrent access
    pthread_mutex_lock(&lock);

    // Insert the record into the array
    record_array = realloc(record_array, (record_count + 1) * sizeof(Record*));
    record_array[record_count] = new_record;
    record_count++;

    // Unlock
    pthread_mutex_unlock(&lock);
}

void remove_record(int key) {
    for (int i = 0; i < record_count; i++) {
        if (record_array[i]->key == key) {
            // Lock for concurrent access
            pthread_mutex_lock(&lock);

            // Remove the record from the array and free memory
            record_array[i] = record_array[--record_count];
            my_free(record_array[i]);

            // Unlock
            pthread_mutex_unlock(&lock);
            return;
        }
    }
}

