            files[num_files-1] = fopen(argv[i], "r");
            if (files[num_files-1] == NULL) {
                printf("Error: Unable to open file '%s' for reading.\n", argv[i]);
                return -1;
            }
        }
    }

    // Perform operations based on command line arguments
    if (help) {
        print_help();
    } else if (manpage) {
        generate_manpage();
    } else if (copy_bytes) {
        copy_data(copy_bytes, files, num_files);
    } else if (output_file) {
