    // Close open files
    for (int i = 0; i < num_files; i++) {
        fclose(files[i]);
    }
    free(files);

    return 0;
}

// Function to copy data from multiple files into a new buffer
void copy_data(size_t bytes, FILE **files, int num_files) {
    // Allocate memory for the new buffer
    char *new_buffer = malloc(bytes);
    if (new_buffer == NULL) {
        printf("Error: Unable to allocate memory for the new buffer.\n");
        return;
    }

    // Read and copy data from files into the new buffer
    size_t total_bytes = 0;
    for (int i = 0; i < num_files; i++) {
        fseek(files[i], 0, SEEK_SET);
        char *buffer = malloc(bytes);
        if (buffer == NULL) {
            printf("Error: Unable to allocate memory for the buffer.\n");
            return;
        }
        size_t bytes_read = fread(buffer, 1, bytes, files[i]);
        memcpy(new_buffer + total_bytes, buffer, bytes_read);
        free(buffer);
        total_bytes += bytes_read;
    }

    // Close open files
    for (int i = 0; i < num_files; i++) {
        fclose(files[i]);
    }
    free(files);

    // Write the new buffer to the output file
    fwrite(new_buffer, 1, total_bytes, output_fp);
    free(new_buffer);
}

