#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_CLIENTS 1000
#define INT_MAX 2147483647
#define INT_MIN -2147483648

typedef struct {
    int max_value;
    int* values;
    int size;
} Integers;

Integers get_integers(int fd, int client_id) {
    Integers integers = {INT_MIN, (int*)malloc(sizeof(int)), 0};
    while (1) {
        char buffer[4];
        read(fd, buffer, 4);
        int val = *(int*)buffer;
        if (val < INT_MIN || val > INT_MAX) {
            printf("Invalid integer from client %d: %d\n", client_id, val);
            continue;
        }
        integers.size++;
        integers.values = (int*)realloc(integers.values, sizeof(int) * integers.size);
        integers.values[integers.size - 1] = val;
    }
    return integers;
}

void find_largest_value(Integers* integers) {
    int max_value = INT_MIN;
    for (int i = 0; i < integers->size; i++) {
        if (integers->values[i] > max_value)
            max_value = integers->values[i];
    }
    printf("Largest value: %d\n", max_value);
}

void free_integers(Integers* integers) {
    free(integers->values);
    free(integers);
}

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);

    // Create a socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        printf("Socket creation failed\n");
        return -1;
    }

    // Set up the server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    // Bind the socket to the server address
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        printf("Bind failed\n");
        return -1;
    }

    // Listen for incoming connections
    listen(server_fd, MAX_CLIENTS);
    printf("Server listening on port 8080...\n");

    while (1) {
        // Accept a connection from a client
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            printf("Accept failed\n");
            continue;
        }

        Integers integers = get_integers(client_fd, client_fd);
        find_largest_value(&integers);

        // Close the client socket
        close(client_fd);
    }

    return 0;
}
