import os
import json
import yaml
import configparser
from xml.etree import ElementTree as ET
from typing import List, Dict
from urllib.parse import urlparse
from boto3 import client as s3_client
from requests import Session
from logging import Logger, StreamHandler, FileHandler
from concurrent.futures import ThreadPoolExecutor

class ConfigManager:
    def __init__(self):
        self.config_files = []
        self.api_key = None
        self.s3_bucket = None
        self.log_file = 'config_manager.log'
        self.logger: Logger = Logger('Config Manager')

    def fetch_configs(self) -> List[Dict]:
        api_response = Session().get('https://api.example.com/configs')
        return json.loads(api_response.text)

    def update_config_files(self, configs: List[Dict]):
        with ThreadPoolExecutor() as executor:
            for config in configs:
                if config['format'] == 'json':
                    self.update_json_config(config)
                elif config['format'] == 'yaml':
                    self.update_yaml_config(config)
                elif config['format'] == 'ini':
                    self.update_ini_config(config)
                elif config['format'] == 'xml':
                    self.update_xml_config(config)

    def update_json_config(self, config: Dict):
        with open(f"{config['name']}.json", 'w') as file:
            json.dump(config, file)

    def update_yaml_config(self, config: Dict):
        with open(f"{config['name']}.yaml", 'w') as file:
            yaml.safe_dump(config, file)

    def update_ini_config(self, config: Dict):
        ini_file = configparser.ConfigParser()
        for key, value in config.items():
            ini_file.set('section', key, str(value))
        with open(f"{config['name']}.ini", 'w') as file:
            ini_file.write(file)

    def update_xml_config(self, config: Dict):
        root = ET.Element('root')
        for key, value in config.items():
            child = ET.SubElement(root, f'{key}')
            child.text = str(value)
        tree = ET.ElementTree(root)
        tree.write(f"{config['name']}.xml")

    def upload_to_s3(self, file_path: str):
        s3 = s3_client('s3')
        bucket_name = urlparse(file_path).netloc.split('.')[0]
        s3.put_object(Body=open(file_path, 'rb'), Bucket=bucket_name, Key=os.path.basename(file_path))

    def download_from_s3(self, file_path: str):
        s3 = s3_client('s3')
        bucket_name = urlparse(file_path).netloc.split('.')[0]
        response = s3.get_object(Body=open(file_path, 'wb'), Bucket=bucket_name, Key=os.path.basename(file_path))
        with open(file_path, 'wb') as file:
            file.write(response['Body'].read())

    def process_batch(self):
        try:
            configs = self.fetch_configs()
            self.update_config_files(configs)
            for config in configs:
                self.upload_to_s3(f"{config['name']}.{config['format']}")
        except Exception as e:
            self.logger.error(f'Error processing batch: {e}')
            raise

    def rollback(self, file_path: str):
        try:
            with open(file_path, 'r') as original_file:
                with open('rollback_' + os.path.basename(file_path), 'w') as rollback_file:
                    rollback_file.write(original_file.read())
        except Exception as e:
            self.logger.error(f'Error rolling back {file_path}: {e}')
            raise

    def log_errors(self):
        handler = StreamHandler()
        file_handler = FileHandler(self.log_file)
        self.logger.addHandler(handler)
