    public class PokemonController {

        private final PokemonRepository pokemonRepository;
        private final BattleStatisticsApi battleStatisticsApi;
        private final RegionalPopularityTrendsApi regionalPopularityTrendsApi;
        private final PokemonTypeEvaluator typeEvaluator;

        public PokemonController(PokemonRepository pokemonRepository, 
                                  BattleStatisticsApi battleStatisticsApi, 
                                  RegionalPopularityTrendsApi regionalPopularityTrendsApi, 
                                  PokemonTypeEvaluator typeEvaluator) {
            this.pokemonRepository = pokemonRepository;
            this.battleStatisticsApi = battleStatisticsApi;
            this.regionalPopularityTrendsApi = regionalPopularityTrendsApi;
            this.typeEvaluator = typeEvaluator;
        }

