        public PokemonReport getStrategicReport(@PathVariable String pokemonId) {
            PokemonData pokemonData = pokemonRepository.findById(pokemonId).orElseThrow();
            List<BattleStatistics> battleStats = retrieveBattleStatistics(pokemonData);
            List<RegionalPopularityTrend> trends = retrieveRegionalPopularityTrends(pokemonData);

