                    .setName(pokemonData.getName())
                    .setMoveSet(pokemonData.getMoves())
                    .setWeaknesses(typeEvaluator.evaluateWeaknesses(pokemonData))
                    .setStrengths(typeEvaluator.evaluateStrengths(pokemonData))
                    .setRecommendedStrategies(typeEvaluator.recommendedStrategies(battleStats, trends));

            return report;
        }

