    pthread_cond_init(&cond, NULL);
}

void add_semaphore(int value, int max_value) {
    semaphore_t *semaphore = (semaphore_t *)malloc(sizeof(semaphore_t));
    semaphores = realloc(semaphores, (semaphore_count + 1) * sizeof(semaphore_t));
    semaphores[semaphore_count].value = value;
    semaphores[semaphore_count].max_value = max_value;
    semaphore_count++;
}

void update_semaphore(int index, int new_value) {
    if (index < semaphore_count) {
        semaphores[index].value = new_value;
    }
}

int get_semaphore_value(int index) {
    if (index < semaphore_count) {
        return semaphores[index].value;
    } else {
        return -1; // Semaphore not found
    }
}

void *monitoring_thread_func(void *arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < semaphore_count; i++) {
            if (semaphores[i].value > ALERT_THRESHOLD) {
                printf("Semaphore %d is being used beyond its allocated capacity.\n", i);
                // Send alert to external monitoring system
            }
        }
        pthread_mutex_unlock(&mutex);
        sleep(1); // Monitor every second
    }
}

int main() {
    init_semaphore_pool();

    // Load semaphore settings from JSON configuration file
