#include <forward_list>
#include <string>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <queue>

std::mutex mtx;
std::condition_variable cv;
std::queue<std::string> logQueue;

void asyncLogger() {
    while (true) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, []{ return !logQueue.empty(); });
        if (logQueue.size() > 1024) {
            // Batch logs when the queue size exceeds the limit
            logQueue.pop();
        }
        while (!logQueue.empty()) {
            std::string logEntry = logQueue.front();
            logQueue.pop();
            // Log the entry asynchronously using an external logging service
            // ...
            cv.notify_all();
        }
    }
}

void appendOrInsertAfterWithLogging(std::forward_list<std::string>& elements, const std::string& target, const std::string& insertion, bool logErrors) {
    std::unique_lock<std::mutex> lock(mtx);
    if (elements.empty()) {
        // Handle the edge case where the forward list is empty
        if (!logErrors) {
            // Log an error asynchronously
            logQueue.push("Error: Target string not found in the forward list");
            cv.notify_all();
        }
        return;
    }

    auto it = elements.begin();
    bool found = false;
    while (it != elements.end()) {
        if (*it == target) {
            found = true;
            break;
        }
        ++it;
    }

    if (!found) {
        // Handle the case where the target string is not found
        if (logErrors) {
            logQueue.push("Error: Target string not found in the forward list");
            cv.notify_all();
        }
        return;
    }

    elements.insert_after(it, insertion);
}
