#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class SandeshServer {
public:
    virtual ~SandeshServer() {}
    virtual void sendTelemetryData(const std::string& data) = 0;
};

class MetadataService {
public:
    virtual ~MetadataService() {}
    virtual std::vector<std::string> getVMConfigurations() = 0;
};

class DistributedMonitoringAgent {
private:
    SandeshServer* sandeshServer_;
    MetadataService* metadataService_;
    std::mutex mtx_;
    std::condition_variable cv_;
    bool isRunning_ = true;

public:
    DistributedMonitoringAgent(SandeshServer* sandeshServer, MetadataService* metadataService)
        : sandeshServer_(sandeshServer), metadataService_(metadataService) {}

    void start() {
        std::thread thread([this]() {
            while (isRunning_) {
                // Collect telemetry data from VMs
                auto vmConfigurations = metadataService_->getVMConfigurations();
                for (const auto& configuration : vmConfigurations) {
                    // Send telemetry data to Sandesh server
                    sandeshServer_->sendTelemetryData(configuration);
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        }).detach();
    }

    void stop() {
        isRunning_ = false;
        cv_.notify_all();
        thread.join();
    }

    class TestDoubleMetadataService : public MetadataService {
    private:
        std::vector<std::string> configurations_;
        int failureCount_ = 0;

    public:
        ~TestDoubleMetadataService() {}

        void simulateFailure(int count) override {
            failureCount_ += count;
            if (failureCount_ >= 5) {
                throw std::runtime_error("Transient failure");
            }
        }

        virtual std::vector<std::string> getVMConfigurations() override {
            // Simulate different network conditions
            if (failureCount_ > 0) {
                std::this_thread::sleep_for(std::chrono::milliseconds(500));
                configurations_.clear();
            }
            return configurations_;
        }
    };

    class TestDoubleSandeshServer : public SandeshServer {
    public:
        ~TestDoubleSandeshServer() {}

        void sendTelemetryData(const std::string& data) override {
            // Simulate varying loads by dynamically adjusting frequency
            if (data.size() > 1024) {
                std::this_thread::sleep_for(std::chrono::milliseconds(1000));
            }
        }
    };
};

int main() {
    SandeshServer* sandeshServer = new TestDoubleSandeshServer();
    MetadataService* metadataService = new DistributedMonitoringAgent::TestDoubleMetadataService();

    // Start the agent
    auto agent = std::make_unique<DistributedMonitoringAgent>(sandeshServer, metadataService);
    agent->start();

    // Simulate high load and transient failures
    for (int i = 0; i < 10; ++i) {
        try {
            metadataService->simulateFailure(1);
        } catch (...) {
            std::cerr << "Transient failure detected. Recovering..." << std::endl;
            agent->stop();
            agent->start();
        }
    }

    // Stop the agent
    agent->stop();

    return 0;
}
