    public class OrderProcessor
    {
        private readonly string _apiEndpoint;
        private readonly string _clientId;
        private readonly string _clientSecret;
        private readonly string _databaseConnectionString;
        private readonly int _maxRetries;

        public OrderProcessor(IConfiguration configuration)
        {
            _apiEndpoint = configuration["ApiEndpoint"];
            _clientId = configuration["ClientId"];
            _clientSecret = configuration["ClientSecret"];
            _databaseConnectionString = configuration["DatabaseConnectionString"];
            _maxRetries = int.Parse(configuration["MaxRetries"]);
        }

        public async Task ProcessOrders()
        {
            using var client = ConfidentialClientApplicationBuilder.Create(_clientId)
                .WithClientSecret(_clientSecret)
                .WithAuthority($"{_apiEndpoint}/oauth2/v2.0/authorize")
                .Build();

            string tokenAcquisitionResult = await client.AcquireTokenSilentAsync(new[] { _apiEndpoint }, new UserCredential("username", "password")).ExecuteAsync();
            var token = tokenAcquisitionResult.AccessToken;

            using var connection = new SqlConnection(_databaseConnectionString);
            connection.Open();

            while (true)
            {
                try
                {
                    var orders = await GetOrdersFromApi(token);

                    foreach (var order in orders)
                    {
                        if (!ValidateOrder(order))
                            continue;

                        await ProcessOrderInDatabase(connection, order);
                    }
                }
                catch (Exception ex) when (ShouldRetry(ex))
                {
                    await Task.Delay(500); // Wait for a while before retrying
                }
            }
        }

        private async Task<string[]> GetOrdersFromApi(string token)
        {
            using var client = new HttpClient();
            client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", token);

            var response = await client.GetAsync(_apiEndpoint + "/orders");
            response.EnsureSuccessStatusCode();

            return JsonConvert.DeserializeObject<string[]>(await response.Content.ReadAsStringAsync());
        }

        private bool ValidateOrder(string order)
        {
