            command.CommandType = CommandType.StoredProcedure;

            command.Parameters.AddWithValue("@order_id", order);

            await command.ExecuteNonQueryAsync();
        }

        private bool ShouldRetry(Exception ex)
        {
            // Implement your retry logic here
            return true;
        }
    }
}
