using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;

namespace WeatherAPIIntegration
{
    public class WeatherAPI
    {
        private readonly Dictionary<string, IWeatherAPI> _apis = new Dictionary<string, IWeatherAPI>();
        private readonly IMemoryCache _memoryCache;
        private readonly ILogger _logger;

        public WeatherAPI(IMemoryCache memoryCache, ILogger logger)
        {
            _memoryCache = memoryCache;
            _logger = logger;
        }

        public void RegisterAPI(string apiName, IWeatherAPI weatherAPI)
        {
            _apis.Add(apiName, weatherAPI);
        }

        public async Task<WeatherData> GetWeatherAsync(string region, string apiName)
        {
            if (!_apis.ContainsKey(apiName))
            {
                throw new ArgumentException($"Unknown API: {apiName}");
            }

            var weatherAPI = _apis[apiName];

            // Check cache first
            var cachedResult = _memoryCache.GetOrCreate($"weather:{region}:{apiName}", async entry =>
            {
                try
                {
                    return await weatherAPI.GetWeatherAsync(region);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, $"Failed to retrieve weather data for {region} from {apiName}");
                    throw;
                }
            });

            // If cache hit, return cached result
            if (cachedResult != null) return cachedResult;

            // If cache miss, try other APIs
            foreach (var api in _apis.Where(x => x.Key != apiName))
            {
                try
                {
                    var result = await api.GetWeatherAsync(region);
                    // Store result in cache for future use
                    await _memoryCache.SetAsync($"weather:{region}:{api.Key}", result, TimeSpan.FromMinutes(1));
                    return result;
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, $"Failed to retrieve weather data for {region} from {api.Key}");
                }
            }

            // If all APIs fail, throw exception
            throw new Exception($"Failed to retrieve weather data for {region}");
        }
    }

    public interface IWeatherAPI
    {
        Task<WeatherData> GetWeatherAsync(string region);
    }

    public class WeatherData
    {
        public string Temperature { get; set; }
        public string Humidity { get; set; }
        public string Precipitation { get; set; }
    }
}
