namespace MyApp.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ResourcesController : ControllerBase
    {
        private readonly MyDbContext _context;
        private readonly IAuthenticationService _authSvc;
        private readonly ICachingService _cacheSvc;

        public ResourcesController(MyDbContext context, IAuthenticationService authSvc, ICachingService cacheSvc)
        {
            _context = context;
            _authSvc = authSvc;
            _cacheSvc = cacheSvc;
        }

        // Get all resources
        [HttpGet]
        public async Task<IActionResult> GetAllResources()
        {
            return Ok(await _context.Resources.ToListAsync());
        }

        // Get a specific resource by ID
        [HttpGet("{id}")]
        public async Task<IActionResult> GetResource(int id)
        {
            var resource = await _context.Resources.FindAsync(id);
            if (resource == null) return NotFound();
            return Ok(resource);
        }

        // Create a new resource
        [HttpPost]
        public async Task<IActionResult> CreateResource(ResourceCreateModel model)
        {
            await _authSvc.VerifyPermission("create-resource");
            var resource = new Resource { ... };
            await _context.Resources.AddAsync(resource);
            await _context.SaveChangesAsync();
            return CreatedAtAction(nameof(GetResource), new { id = resource.Id }, resource);
        }

        // Update a specific resource
        [HttpPut("{id}")]
        public async Task<IActionResult> UpdateResource(int id, ResourceUpdateModel model)
        {
            await _authSvc.VerifyPermission("update-resource");
            var resource = await _context.Resources.FindAsync(id);
            if (resource == null) return NotFound();
            // Implement optimistic concurrency control here
            await _context.SaveChangesAsync();
            return Ok(resource);
        }

        // Delete a specific resource (soft deletion)
        [HttpDelete("{id}")]
        public async Task<IActionResult> DeleteResource(int id)
        {
            await _authSvc.VerifyPermission("delete-resource");
            var resource = await _context.Resources.FindAsync(id);
            if (resource == null) return NotFound();
            resource.IsActive = false;
            await _context.SaveChangesAsync();
            return NoContent();
        }

        // Update multiple resources in bulk
        [HttpPut("bulk")]
        public async Task<IActionResult> UpdateBulkResources(ResourceUpdateBulkModel model)
        {
            await _authSvc.VerifyPermission("update-bulk-resources");
            foreach (var resourceId in model.ResourceIds)
            {
                var resource = await _context.Resources.FindAsync(resourceId);
                if (resource == null) continue;
                // Implement optimistic concurrency control here
                await _context.SaveChangesAsync();
            }
            return Ok();
        }

        // Delete multiple resources in bulk
        [HttpDelete("bulk")]
        public async Task<IActionResult> DeleteBulkResources(ResourceDeleteBulkModel model)
        {
            await _authSvc.VerifyPermission("delete-bulk-resources");
            foreach (var resourceId in model.ResourceIds)
            {
                var resource = await _context.Resources.FindAsync(resourceId);
                if (resource == null) continue;
                resource.IsActive = false;
                await _context.SaveChangesAsync();
            }
            return NoContent();
        }
    }

    public class ResourceCreateModel { ... }
    public class ResourceUpdateModel { ... }
    public class ResourceUpdateBulkModel { ... }
    public class ResourceDeleteBulkModel { ... }
}
