using System;
using System.IO;
using System.Net;
using System.Xml.XPath;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using StackExchange.Redis;

public class XmlService
{
    private readonly ILogger _logger;
    private readonly IConfiguration _config;
    private readonly IConnectionMultiplexer _redis;
    private readonly Dictionary<string, XPathDocument> _cache = new();

    public XmlService(ILogger<XmlService> logger, IConfiguration config)
    {
        _logger = logger;
        _config = config;
        _redis = ConnectionMultiplexer.Connect(_config["RedisConnectionString"]);
    }

    [HttpGet]
    public async Task<IActionResult> ProcessXml([FromUri] string xmlUrl)
    {
        using (var stream = await new HttpClient().GetStreamAsync(xmlUrl))
        {
            using (var doc = new XPathDocument(stream, _config["XmlSchema"]))
            {
                if (!doc.Validate())
                    return BadRequest("Invalid XML document");

                var query = Request.Query["query"];
                if (string.IsNullOrEmpty(query))
                    return Ok("No XPath query provided");

                try
                {
                    var result = await ExecuteXPath(doc, query);
                    return Ok(result);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing XPath query");
                    return StatusCode(500, "Failed to process XPath query");
                }
            }
        }
    }

    private async Task<string> ExecuteXPath(XPathDocument doc, string query)
    {
        if (_cache.TryGetValue(query, out var cachedResult))
            return cachedResult.OuterXml;

        try
        {
            var result = await _redis.ExecuteAsync(doc, query);
            _cache[query] = new XPathDocument(new MemoryStream(result), _config["XmlSchema"]);
            return result;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error executing XPath query");
            throw;
        }
    }

    private async Task<string> ExecuteExternalApi(XPathNodeSet nodeSet)
    {
        // Call external API and retrieve metadata
        var apiResult = await new HttpClient().GetStringAsync("https://api.example.com/metadata");

        try
        {
            // Process API result and update XPath nodes
            foreach (var node in nodeSet)
                node.SetAttribute("metadata", apiResult);

            return apiResult;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing external API");
            throw;
        }
    }

    public static void Main(string[] args)
    {
        var builder = WebApplication.CreateBuilder(args);
        builder.Services.AddLogging();
        builder.Services.Configure<XmlServiceOptions>(_config.GetSection("XmlService"));

        var app = builder.Build();
        app.UseRouting();
        app.UseEndpoints(endpoints =>
        {
            endpoints.MapXmlService();
        });

        app.Run();
    }
}
