@RestController
@RequestMapping("/api/resources")
public class ResourceController {

    private final ResourceRepository resourceRepository;
    private final ValidationService validationService;
    private final CircuitBreaker circuitBreaker;

    public ResourceController(ResourceRepository resourceRepository, 
                               ValidationService validationService,
                               CircuitBreaker circuitBreaker) {
        this.resourceRepository = resourceRepository;
        this.validationService = validationService;
        this.circuitBreaker = circuitBreaker;
    }

    @PutMapping("/{id}")
    public ResponseEntity<Resource> updateResource(@PathVariable UUID id, @RequestBody Resource resource) {
        try {
            if (circuitBreaker.open()) {
                return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).build();
            }
            validate(resource);
            resourceRepository.update(id, resource);
            return ResponseEntity.ok(resource)
                    .header("ETag", String.valueOf(MD5.hash(resource.toString())));
        } catch (Exception e) {
            log.error("Error updating resource: {}", e.getMessage());
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).build();
        }
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<String> deleteResource(@PathVariable UUID id) {
        try {
            if (circuitBreaker.open()) {
                return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).build();
            }
            resourceRepository.delete(id);
            return ResponseEntity.ok("Resource deleted successfully");
        } catch (Exception e) {
            log.error("Error deleting resource: {}", e.getMessage());
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).build();
        }
    }

    private void validate(Resource resource) throws Exception {
        try {
            validationService.validate(resource);
        } catch (ValidationException e) {
            throw new Exception("Validation failed: " + e.getMessage());
        }
    }
}

