import os
import hashlib
import asyncio
from typing import List, Dict

class FileMonitor:
    def __init__(self):
        self.config = {}
        self.users = {}

    async def monitor_directory(self, path: str) -> None:
        for root, dirs, files in os.walk(path):
            await asyncio.gather(
                *(self.compute_hashes(file_path) for file_path in files)
            )

    async def compute_hashes(self, file_path: str) -> Dict[str, str]:
        try:
            with open(file_path, 'rb') as file:
                hash_md5 = hashlib.md5()
                while chunk := file.read(4096):
                    hash_md5.update(chunk)
                return {'file_path': file_path, 'md5_hash': hash_md5.hexdigest()}
        except OSError as e:
            print(f"Error reading file: {e}")

    async def manage_users(self) -> None:
        @app.route('/users', methods=['GET'])
        def get_users() -> List[Dict[str, str]]:
            return list(self.users.values())

        @app.route('/users', methods=['POST'])
        def create_user(user_data: Dict[str, str]) -> Dict[str, str]:
            if 'username' not in user_data or 'password' not in user_data:
                raise ValueError('Invalid request')
            self.users[user_data['username']] = user_data
            return user_data

        @app.route('/users/<username>', methods=['GET', 'PUT', 'DELETE'])
        def handle_user(username: str) -> Dict[str, str]:
            if username not in self.users:
                raise ValueError('User not found')
            if request.method == 'GET':
                return self.users[username]
            elif request.method == 'PUT':
                user_data = request.get_json()
                if 'password' not in user_data:
                    raise ValueError('Invalid request')
                self.users[username] = user_data
                return user_data
            elif request.method == 'DELETE':
                del self.users[username]
                return {'message': f"User {username} deleted"}

    async def run(self) -> None:
        try:
            await asyncio.gather(
                *(self.monitor_directory(path) for path in self.config['directories']),
                *(self.manage_users()) 
            )
        except Exception as e:
            print(f"Error: {e}")

if __name__ == '__main__':
    app = Flask(__name__)
    file_monitor = FileMonitor()
    asyncio.run(file_monitor.run())
```

