package com.application.state.util;

import java.io.*;
import java.util.*;
import java.lang.management.*;

public class StateManager {
    private static final String STATE_FILE_NAME = "state.bin";
    private static final int INITIAL_CACHE_SIZE = 1000;
    private static final long CACHE_EVICT_THRESHOLD = 10000L; // milliseconds
    private static final double CPU_LOAD_THRESHOLD = 0.7;

    private File stateFile;
    private ObjectInputStream objectInputStream;
    private ObjectOutputStream objectOutputStream;
    private Map<Object, StateObject> cache;
    private ThreadLocal<Map<String, Long>> hitMetrics = new ThreadLocal<>();
    private MonitoringService monitoringService;

    public StateManager() {
        stateFile = new File(STATE_FILE_NAME);
        cache = new LruCache(INITIAL_CACHE_SIZE);
        hitMetrics.set(new HashMap<>());
        monitoringService = new MonitoringService();
    }

    public void init() throws IOException {
        if (!stateFile.exists()) {
            stateFile.createNewFile();
        }
        objectInputStream = new ObjectInputStream(new FileInputStream(stateFile));
        objectOutputStream = new ObjectOutputStream(new FileOutputStream(stateFile, true));
    }

    public StateObject loadState(String key) throws IOException, ClassNotFoundException {
        StateObject stateObject = (StateObject) cache.get(key);
        if (stateObject == null) {
            try (ObjectInputStream is = new ObjectInputStream(new FileInputStream(stateFile))) {
                stateObject = (StateObject) is.readObject();
                cache.put(key, stateObject);
                hitMetrics.get().put(key, System.nanoTime());
            }
        }
        return stateObject;
    }

    public void saveState(StateObject stateObject) throws IOException {
        try (ObjectOutputStream os = new ObjectOutputStream(new FileOutputStream(stateFile))) {
            os.writeObject(stateObject);
            invalidateCacheEntry(stateObject.getKey());
        }
    }

    public void updateCacheSize(long cpuLoad, long memoryUsage, int transactionRate) {
        double cacheRatio = (double) cache.size() / (INITIAL_CACHE_SIZE * 1.0);
        if (cpuLoad > CPU_LOAD_THRESHOLD || cacheRatio > 0.8) {
            resizeCache(INITIAL_CACHE_SIZE - ((int) (cacheRatio * INITIAL_CACHE_SIZE)));
        } else if (memoryUsage > 90 && transactionRate > 50) {
            resizeCache(INITIAL_CACHE_SIZE + ((int) (cacheRatio * INITIAL_CACHE_SIZE)));
        }
    }

    public void invalidateCacheEntry(String key) {
        cache.remove(key);
        hitMetrics.get().remove(key);
    }

    public void reportMetrics() {
        monitoringService.reportHitMetrics(hitMetrics.get());
    }
}

class LruCache<K, V> extends LinkedHashMap<K, V> {
    private final int initialCapacity;

    public LruCache(int initialCapacity) {
        super(initialCapacity, 0.75f, true);
        this.initialCapacity = initialCapacity;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        if (size() > initialCapacity) {
            return true;
        }
        return false;
    }
}

class MonitoringService {
    public void reportHitMetrics(Map<String, Long> hitMetrics) {
        // TO DO: implement real-time reporting to an external monitoring service
    }
}
