const { WorkerPool } = require('worker-pool');
const fs = require('fs');
const jsonschema = require('jsonschema');
const axios = require('axios');

class Validator {
  constructor(apiUrl) {
    this.apiUrl = apiUrl;
    this.cache = new Map();
  }

  async validateFile(filePath) {
    try {
      const fileContent = await fs.readFile(filePath, 'utf8');
      const schema = // your complex JSON schema here
      const validationResult = jsonschema.validate(fileContent, schema);
      if (!validationResult.errors.length) {
        await this.logValidationSuccess(filePath);
        return { success: true };
      } else {
        await this.logValidationFailure(filePath, validationResult.errors);
        return { success: false, errors: validationResult.errors };
      }
    } catch (error) {
      await this.logValidationFailure(filePath, [error]);
      return { success: false, errors: [error] };
    }
  }

  async logValidationSuccess(filePath) {
    if (!this.cache.has(filePath)) {
      const response = await axios.post(this.apiUrl + '/validate', { file_path: filePath, status: 'success' });
      this.cache.set(filePath, response.data.log_id);
    }
  }

  async logValidationFailure(filePath, errors) {
    if (!this.cache.has(filePath)) {
      const response = await axios.post(this.apiUrl + '/validate', { file_path: filePath, status: 'failure', errors });
      this.cache.set(filePath, response.data.log_id);
    }
  }
}

const workerPool = new WorkerPool();

workerPool.on('error', (error) => {
  console.error(`Worker pool error: ${error}`);
});

async function processFiles(directory) {
  const files = await fs.readdir(directory);
  for (const file of files) {
    if (!file.includes('.txt')) continue;
    const filePath = `${directory}/${file}`;
    workerPool.exec(() => Validator.validateFile(filePath));
  }
