class TestFramework {
  constructor(config) {
    this.config = config;
    this.testService = null;
    this.lockedTests = 0;
  }

  async run(label, tests) {
    console.log(`Starting ${label} test suite...`);

    try {
      await this.initTestService();

      for (const test of tests) {
        if (!this.lockedTests < this.config.concurrentLimit) {
          await new Promise((resolve) => setTimeout(resolve, 1000));
        }

        this.lockedTests++;
        console.log(`Running ${label} test: ${test.name}`);
        await test();
      }
    } catch (error) {
      console.error(`Error running ${label} tests: ${error}`);
    } finally {
      this.unlockTests();
      console.log(`${label} test suite completed.`);
    }
  }

  async initTestService() {
    if (!this.testService) {
      const { apiEndpoint, authConfig } = this.config;
      this.testService = await fetch(apiEndpoint, { 
        method: 'POST', 
        headers: { 'Content-Type': 'application/json' }, 
        body: JSON.stringify(authConfig), 
      });
      this.testService = await this.testService.json();
    }
  }

  unlockTests() {
    this.lockedTests--;
  }
}

module.exports = TestFramework;
