// Footer module
(function (window) {
  'use strict';

  const cache = {};
  let expirationTime = new Date().getTime() + 3600000; // 1 hour

  function getScriptSources() {
    return [
      { url: 'https://api.example.com/script-1.js', type: 'script' },
      { url: 'https://api.example.com/script-2.js', type: 'style' }
    ];
  }

  function fetchScript(src) {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open('GET', src, true);
      xhr.onload = () => {
        if (xhr.status === 200) {
          resolve(xhr.responseText);
        } else {
          reject(new Error(`Failed to load ${src}`));
        }
      };
      xhr.onerror = () => reject(new Error(`Error loading ${src}`));
      xhr.send();
    });
  }

  function sanitizeScript(src, script) {
    // Sanitize and validate script content
    return script.replace(/\/\/.*|\/\*[\s\S]*\*\/|[\s\S]+/g, '');
  }

  function cacheScript(src, script) {
    const cachedScript = { src, script };
    cache[src] = cachedScript;
    expirationTime = new Date().getTime() + 3600000; // Update expiration time
  }

  function getRenderedFooter() {
    return `
      <footer>
        ${getScripts().map((script) => `<script type="${script.type}" src="${script.url}">${sanitizeScript(script.url, script.script)}</script>`).join('')}
      </footer>
    `;
  }

  function getScripts() {
    const now = new Date().getTime();
    if (now > expirationTime) {
      cache = {}; // Reset cache
      expirationTime = new Date().getTime() + 3600000; // Update expiration time
    }
    return Object.keys(cache).map((src) => cache[src]);
  }

  function renderFooter() {
    try {
      const footerHTML = getRenderedFooter();
      document.getElementById('footer').innerHTML = footerHTML;
      console.log('Footer rendered successfully!');
    } catch (error) {
      console.error('Error rendering footer:', error);
    }
  }

  // Fetch script sources and cache them
  Promise.all(getScriptSources().map((scriptSource) => fetchScript(scriptSource.url))).then((scripts) => {
    scripts.forEach((script, index) => cacheScript(getScriptSources()[index].url, script));
  });

  // Render footer on page load
  document.addEventListener('DOMContentLoaded', renderFooter);

})(window);
