import { Injectable } from '@angular/core';
import { logger } from '../logger';

@Injectable({
  providedIn: 'root'
})
export class DialogValidationModule {
  private parentWindow = null;
  private dialogFieldsRegex = new RegExp('^(\\s*|{2,})((?:(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclasiastics|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Zephaniah|Haggai|Zechariah|Malachi)\\b)(?!.*\\w{2,})$');

  async init() {
    try {
      this.parentWindow = window.top;
      if (!this.parentWindow) throw new Error('Failed to establish connection with parent window');
    } catch (error) {
      logger.error(`Error initializing module: ${error.message}`);
    }
  }

  validateDialogFields(text) {
    return new Promise((resolve, reject) => {
      try {
        const result = this.dialogFieldsRegex.test(text);
        if (!result) throw new Error('Invalid dialog field');
        resolve({ isValid: true, message: 'Valid dialog field' });
      } catch (error) {
        reject({ isValid: false, message: error.message });
      }
    });
  }

  countOldTestamentBooks(text) {
    return new Promise((resolve, reject) => {
      try {
        const matches = this.dialogFieldsRegex.exec(text);
        if (!matches) throw new Error('No Old Testament book found');
        const occurrences = (matches[0] || '').split(/\s+/).filter(word => this.dialogFieldsRegex.test(word)).length;
        resolve({ count: occurrences, message: `Found ${occurrences} Old Testament books` });
      } catch (error) {
        reject({ count: 0, message: error.message });
      }
    });
  }

  async processText(text) {
