#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <json-c/json.h>

#define MAX_BUNDLE_SIZE 1024
#define CACHE_SIZE 1024

typedef struct {
    int bundle_size;
    json_object *bundle_data;
} bundle_t;

bundle_t *load_bundle(const char* url) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation failed");
        return NULL;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(80);
    inet_pton(AF_INET, "example.com", &addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Connection failed");
        close(sock);
        return NULL;
    }

    char buffer[MAX_BUNDLE_SIZE];
    size_t bytes_received = recv(sock, buffer, MAX_BUNDLE_SIZE - 1, 0);

    if (bytes_received <= 0) {
        perror("Error receiving data");
        close(sock);
        return NULL;
    }

    buffer[bytes_received] = '\0';

    json_object *bundle_data = json_tokener_parse(buffer);
    int bundle_size = strlen(buffer);

    bundle_t *bundle = malloc(sizeof(bundle_t));
    if (bundle == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    bundle->bundle_size = bundle_size;
    bundle->bundle_data = bundle_data;

    close(sock);
    return bundle;
}

int get_bundle_size(const bundle_t* bundle) {
    return bundle->bundle_size;
}

json_object *get_bundle_data(const bundle_t* bundle) {
    return bundle->bundle_data;
}

void free_bundle(bundle_t* bundle) {
    json_object_put(bundle->bundle_data);
    free(bundle);
}
