@Injectable()
export class DomService {
  async processDomTree(domTree: DocumentFragment, filterOptions: any): Promise<any[]> {
    const filteredElements = [];
    await this.traverseDomTree(domTree, filterOptions, filteredElements);
    return filteredElements;
  }

  async traverseDomTree(node: Node, filterOptions: any, filteredElements: any[]): Promise<void> {
    if (!node) return;

    if (filterOptions.selector && node.matches(filterOptions.selector)) {
      try {
        const metadata = await this.fetchMetadata(node);
        filteredElements.push({ ...node, metadata });
      } catch (error) {
        console.error(`Error fetching metadata for ${node.nodeName}:`, error);
      }
    }

    for (const child of node.childNodes) {
      await this.traverseDomTree(child, filterOptions, filteredElements);
    }
  }

  async fetchMetadata(node: Node): Promise<any> {
    const { url, method } = this.buildApiRequest(node);
    try {
      const response = await axios.request({ url, method });
      return response.data;
    } catch (error) {
      console.error(`Error fetching metadata for ${node.nodeName}:`, error);
      throw error;
    }
  }

  buildApiRequest(node: Node): { url: string; method: 'GET' | 'POST' } {
    // implement your API request builder here
    return {
      url: `https://your-api.com/${node.nodeName}`,
      method: 'GET',
    };
  }
