const fs = require('fs');
const path = require('path');
const { resolve } = require('url');

class ModuleLoader {
  constructor(directory) {
    this.directory = directory;
    this.modules = {};
    this.cachedModules = {};
  }

  async loadModule(name, forceReload = false) {
    if (this.modules[name]) {
      return this.modules[name];
    }

    try {
      const modulePath = path.join(this.directory, `${name}.js`);
      const content = await fs.readFileSync(modulePath, 'utf8');
      let module;

      try {
        ({ default: module } = await import(content));
      } catch (error) {
        throw new Error(`Failed to load module ${name}: ${error}`);
      }

      this.modules[name] = module;
      return module;
    } catch (error) {
      if (!forceReload) {
        throw error;
      }
      try {
        const cachedModule = this.cachedModules[name];
        if (cachedModule) {
          return cachedModule;
        }
      } catch (cachedError) {
        throw new Error(`Failed to load cached module ${name}: ${cachedError}`);
      }
    }
  }

  async executeModule(name, ...args) {
    const module = await this.loadModule(name);
    try {
      return await module(...args);
    } catch (error) {
      console.error(`Error executing module ${name}: ${error}`);
      throw error;
    }
  }

  async runModules() {
    for (const file of fs.readdirSync(this.directory)) {
      const name = path.basename(file, '.js');
      try {
        await this.executeModule(name);
      } catch (error) {
        console.error(`Error executing module ${name}: ${error}`);
      }
    }
  }

  async runConcurrently() {
    const modulesToRun = [];
    for (const file of fs.readdirSync(this.directory)) {
      const name = path.basename(file, '.js');
      modulesToRun.push({ name, promise: this.executeModule(name) });
    }

    try {
      await Promise.all(modulesToRun.map((module) => module.promise));
    } catch (error) {
      console.error(`Error executing concurrently: ${error}`);
    }
  }
}

const loader = new ModuleLoader('./modules');
loader.runConcurrently();
```

This code implements a basic Node.js application that dynamically loads and executes JavaScript modules from a specified directory. It supports both synchronous and asynchronous modules, manages interdependencies among them, and handles errors gracefully."]

