//package declaration
package com.example.dataingestion;

import java.util.concurrent.*;

//main class
public class DataIngestionApplication {
    private static final Logger logger = LoggerFactory.getLogger(DataIngestionApplication.class);

    //queue to hold tasks
    private final BlockingQueue<Task> taskQueue;
    private final ExecutorService executorService;
    private final ScheduledExecutorService scheduledExecutorService;

    public DataIngestionApplication() {
        taskQueue = new LinkedBlockingQueue<>();
        executorService = Executors.newCachedThreadPool();
        scheduledExecutorService = Executors.newScheduledThreadPool(1);
    }

    //method to add tasks to the queue
    public void submitTask(Task task) {
        taskQueue.add(task);
    }

    //method to process tasks from the queue
    public void startProcessing() {
        ScheduledFuture<?> schedulingResult = scheduledExecutorService.scheduleAtFixedRate(() -> {
            while (true) {
                Task task;
                try {
                    task = taskQueue.take();
                } catch (InterruptedException | NoSuchElementException e) {
                    logger.error("Error processing tasks", e);
                    return;
                }
                //process the task
                processTask(task);
            }
        }, 0, 10, TimeUnit.SECONDS); // adjust the frequency based on current system load

        ScheduledFuture<?> backpressureResult = scheduledExecutorService.scheduleAtFixedRate(() -> {
            if (taskQueue.size() > 100) { // adjust this threshold as needed
                logger.info("Backpressure detected. Reducing processing frequency.");
                schedulingResult.cancel();
                //reset the scheduling result to reduce frequency
                schedulingResult = scheduledExecutorService.scheduleAtFixedRate(() -> {
                    processTask(taskQueue.take());
                }, 0, 30, TimeUnit.SECONDS);
            }
        }, 0, 5, TimeUnit.MINUTES); // adjust this interval as needed

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            schedulingResult.cancel();
            backpressureResult.cancel();
        }));
    }

    //method to process a task
    private void processTask(Task task) {
        try {
            executorService.submit(task::process).get(); // adjust the timeout based on your needs
            logger.info("Task processed successfully: {}", task);
        } catch (Exception e) {
            logger.error("Error processing task: {}", task, e);
            //retry failed tasks
            submitTask(task);
        }
    }

    public static void main(String[] args) {
        DataIngestionApplication application = new DataIngestionApplication();
        application.startProcessing();
    }
}

//task interface
interface Task {
    void process() throws Exception;
}
```

