from importlib.util import spec_loader
from importlib.machinery import ModuleSpec
from typing import List, Dict

class EnvironmentConfig:
    def __init__(self):
        self.config = {}
        self.load_config()

    def load_config(self):
        if not os.path.exists('config.json'):
            return
        with open('config.json') as f:
            data = json.load(f)
            for k, v in data.items():
                self.config[k] = v

class ComponentLoader:
    def __init__(self):
        self.components = []

    def load_components(self, env_config: EnvironmentConfig) -> List[Dict]:
        components = []
        if env_config.config.get('dev'):
            # Load development components
            for file in os.listdir('components/dev'):
                if file.endswith('.py'):
                    component_name = file[:-3]
                    component_module = spec_loader(f'component.{component_name}', 'components.dev')
                    component_instance = component_module.Component()
                    components.append({'name': component_name, 'instance': component_instance})
        else:
            # Load production components
            for file in os.listdir('components/prod'):
                if file.endswith('.py'):
                    component_name = file[:-3]
                    component_module = spec_loader(f'component.{component_name}', 'components.prod')
                    component_instance = component_module.Component()
                    components.append({'name': component_name, 'instance': component_instance})
        return components

class Application:
    def __init__(self):
        self.env_config = EnvironmentConfig()
        self.component_loader = ComponentLoader()
        self.components = self.component_loader.load_components(self.env_config)

    def run(self):
        for component in self.components:
            # Run each component
            component['instance'].run()

if __name__ == '__main__':
    app = Application()
    app.run()
