    base_url: String,
    rate_limit: u32,
    retry_policy: u32,
    timeout: u64,
    connection_pool_size: usize,
    quota_service_url: String,
    logger: Box<dyn Fn(&str) + '_>,
}

impl HttpClient {
    // Create a new instance of the HTTP client
    pub fn new(
        base_url: &str,
        rate_limit: u32,
        retry_policy: u32,
        timeout: u64,
        connection_pool_size: usize,
        quota_service_url: &str,
        logger: Box<dyn Fn(&str) + '_>,
    ) -> Self {
        HttpClient {
            base_url: base_url.to_string(),
            rate_limit,
            retry_policy,
            timeout,
            connection_pool_size,
            quota_service_url: quota_service_url.to_string(),
            logger,
        }
    }

    // Send a GET request
    pub fn get(&self, path: &str) -> Result<String, reqwest::Error> {
        let client = reqwest::blocking::Client::new();
        let mut headers = HashMap::new();
        headers.insert("User-Agent", "Rust-HTTP-Client".to_string());
        client
            .get(&format!("{}/{}", self.base_url, path))
            .headers(headers)
            .timeout(std::time::Duration::from_millis(self.timeout))
            .send()
    }

    // Send a POST request
    pub fn post(&self, path: &str) -> Result<String, reqwest::Error> {
        let client = reqwest::blocking::Client::new();
        let mut headers = HashMap::new();
        headers.insert("User-Agent", "Rust-HTTP-Client".to_string());
        client
            .post(&format!("{}/{}", self.base_url, path))
            .headers(headers)
            .timeout(std::time::Duration::from_millis(self.timeout))
            .send()
    }

    // Handle rate limiting
    fn rate_limit(&self) -> u32 {
        self.rate_limit
    }

    // Handle retries
    fn retry_policy(&self) -> u32 {
        self.retry_policy
    }
}
