    private $lockTimeout = 5000; // 5 seconds

    public function __construct($dbConfig, $apiEndpoint) {
        $this->dbConn = new PDO(
            'mysql:host=' . $dbConfig['host'] . ';dbname=' . $dbConfig['database'],
            $dbConfig['username'],
            $dbConfig['password']
        );
        $this->apiEndpoint = $apiEndpoint;
        $this->semaphore = new Semaphore(1); // Initialize with one slot
    }

    public function updateClinicStatus($clinicId) {
        try {
            // Attempt to acquire the semaphore
            if (!$this->semaphore->try_acquire($this->lockTimeout)) {
                throw new Exception('Semaphore timeout');
            }

            // Fetch the latest clinic details from external API
            $response = json_decode(
                file_get_contents($this->apiEndpoint . '/' . $clinicId),
                true
            );

            if (!isset($response['status']) || !isset($response['lastModifiedIP'])) {
                throw new Exception('Invalid response');
            }

            // Update the clinic details in the database
            $stmt = $this->dbConn->prepare(
                'UPDATE clinics SET status = :status, lastModifiedIP = :lastModifiedIP, lastModifiedDate = NOW() WHERE id = :clinicId'
            );
            $stmt->execute([
                ':status' => $response['status'],
                ':lastModifiedIP' => $response['lastModifiedIP'],
                ':clinicId' => $clinicId
            ]);

            // Release the semaphore
            $this->semaphore->release();
        } catch (Exception $e) {
            // Log the error and release the semaphore
            error_log('Error updating clinic status: ' . $e->getMessage());
            $this->semaphore->release();
        }
    }

    public function startService() {
        while (true) {
            try {
                // Poll for updates at a fixed interval
                usleep(1000000); // 1 second

                // Fetch clinics that require an update
                $stmt = $this->dbConn->prepare('SELECT id FROM clinics WHERE lastModifiedDate < DATE_SUB(NOW(), INTERVAL 5 MINUTE)');
                $stmt->execute();
                $clinics = $stmt->fetchAll();

                foreach ($clinics as $clinic) {
                    try {
                        // Update the clinic status
                        $this->updateClinicStatus($clinic['id']);
                    } catch (Exception $e) {
                        error_log('Error updating clinic ' . $clinic['id'] . ': ' . $e->getMessage());
                    }
                }
            } catch (PDOException $e) {
                // Log the database error and retry
                error_log('Database error: ' . $e->getMessage());
            }
        }
    }
}

// Example usage:
$service = new ClinicStatusService(
    [
        'host' => 'localhost',
        'database' => 'clinic_status',
        'username' => 'root',
        'password' => ''
    ],
    'https://api.example.com/clinics'
);

$service->startService();
