#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum JobStatus {
    JOB_SUCCESS,
    JOB_FAILURE,
    JOB_PENDING
} JobStatus;

void BackgroundJobExecutor(char* command, char* logFile) {
    FILE* log = fopen(logFile, "a");
    if (!log) {
        perror("Error opening log file");
        return;
    }

    pid_t jobPid = fork();
    if (jobPid == -1) {
        perror("Error forking process");
        fclose(log);
        return;
    } else if (jobPid > 0) { // Parent process
        JobStatus status = JOB_PENDING;
        while (status == JOB_PENDING) {
            sleep(1); // Wait for job to complete
            system(command);
            status = JOB_SUCCESS; // Assume successful completion
        }
    } else { // Child process
        if (system(command) != 0) {
            JobStatus status = JOB_FAILURE;
        }
        fclose(log);
        exit(EXIT_SUCCESS);
    }

    fclose(log);
}

int main() {
    char* command = "your_system_command_here";
    char* logFile = "/path/to/job/log.txt";

    BackgroundJobExecutor(command, logFile);

    return 0;
}
