import json
import os
import threading

class DataHandler:
    def __init__(self):
        self.data_classes = {}

    def register_data_class(self, data_id, data_class):
        self.data_classes[data_id] = data_class

    def deserialize(self, data_id, json_str):
        if data_id not in self.data_classes:
            return None
        try:
            data_obj = self.data_classes[data_id].load(json.loads(json_str))
        except Exception as e:
            print(f"Error deserializing {data_id}: {str(e)}")
            return None
        return data_obj

    def serialize(self, data_id, data_obj):
        if data_id not in self.data_classes:
            return None
        try:
            return json.dumps(self.data_classes[data_id].dump(data_obj))
        except Exception as e:
            print(f"Error serializing {data_id}: {str(e)}")
            return None


class FileProcessor(threading.Thread):
    def __init__(self, file_path):
        super().__init__()
        self.file_path = file_path
        self.lock = threading.Lock()
        self.data = []

    def run(self):
        with open(self.file_path, 'r') as f:
            for line in f:
                self.data.append(line.strip())

        self.data.sort(key=lambda x: int(x.split(' ')[-1]))

    def get_sequence_number(self):
        if not self.data:
            return None
        return self.data[-1].split(' ')[-1]


class LogFileProcessor(FileProcessor):
    def __init__(self, file_path):
        super().__init__(file_path)

    def get_sequence_number(self):
        try:
            return int(super().get_sequence_number())
        except ValueError as e:
            print(f"Error parsing sequence number: {str(e)}")
            return None


class DataClassSerializer:
    def __init__(self, data_class):
        self.data_class = data_class

    def dump(self, data_obj):
        return json.dumps(data_obj.__dict__)

    def load(self, json_str):
        try:
            data_dict = json.loads(json_str)
            return self.data_class(**data_dict)
        except Exception as e:
            print(f"Error loading {self.data_class.__name__}: {str(e)}")
            return None


if __name__ == '__main__':
    data_handler = DataHandler()

    class User(DataClassSerializer):
        def __init__(self, id, name):
            self.id = id
            self.name = name

    class Message(DataClassSerializer):
        def __init__(self, id, content):
            self.id = id
            self.content = content

    data_handler.register_data_class('user', User)
    data_handler.register_data_class('message', Message)

    file_processor = LogFileProcessor('log_file.log')
    file_processor.start()
    sequence_number = file_processor.get_sequence_number()

    # Example usage
    user_json = '{"id": 1, "name": "John"}'
    message_json = '{"id": 2, "content": "Hello World!"}'
    user_data_obj = data_handler.deserialize('user', user_json)
    message_data_obj = data_handler.deserialize('message', message_json)

    print(f"User: {user_data_obj.name} ({user_data_obj.id})")
    print(f"Message: {message_data_obj.content} ({message_data_obj.id})")
    print(f"Sequence Number: {sequence_number}")
