#include <octree/octree.h>
#include <octree/node.h>
#include <octree/serialization.h>

namespace octree {

class SpatialIndex {
public:
    SpatialIndex(size_t capacity) : root_(new Node(0, 0, 0, capacity)) {}

    void insert(const std::vector<Vector3D>& points) {
        for (const auto& point : points) {
            root_->insert(point);
        }
    }

    void query(const std::vector<Vector3D>& queryPoints,
               const std::function<void(const Vector3D&)>& callback) {
        for (const auto& queryPoint : queryPoints) {
            Node* current = &root_;
            while (*current != nullptr) {
                if ((*current)->isFullyInscribed(queryPoint)) {
                    callback(queryPoint);
                    break;
                }
                current = &(*current)->getChild(queryPoint);
            }
        }
    }

private:
    class Node {
    public:
        Node(Vector3D min, Vector3D max, size_t capacity)
            : min_(min), max_(max), points_(), children_(8) {}

        void insert(const Vector3D& point) {
            if (isFullyInscribed(point)) {
                points_.push_back(point);
            } else {
                for (auto& child : children_) {
                    if (!child) {
                        child = new Node(split(point));
                        break;
                    }
                }
                for (const auto& child : children_) {
                    if (child) {
                        child->insert(point);
                    }
                }
            }
        }

    private:
        Vector3D min_;
        Vector3D max_;
        std::vector<Vector3D> points_;
        std::array<Node*, 8> children_;
    };

    class Serialization {
    public:
        static void serialize(Node* node, std::ostream& os) {
            if (node != nullptr) {
                os << "Node(";
                for (int i = 0; i < 3; ++i) {
                    os << node->min_[i] << ",";
                }
                os << "):";

                for (const auto& point : node->points_) {
                    serializePoint(point, os);
                }

                for (auto& child : node->children_) {
                    if (child != nullptr) {
                        serialize(child, os);
                    } else {
                        os << "null," << std::endl;
                    }
                }
            } else {
                os << "null" << std::endl;
            }
        }

        static void deserialize(Node** node, std::istream& is) {
            if (is >> *node) {
                int i = 0;
                for (; i < 3; ++i) {
                    (*node)->min_[i] = is.read<Vector3D>();
                }
                while (is.peek() != '\n') {
                    Vector3D point;
                    deserializePoint(point, is);
                    (*node)->points_.push_back(point);
                }
                for (auto& child : (*node)->children_) {
                    if (child == nullptr) {
                        child = new Node(Vector3D(), Vector3D(), 0);
                    } else {
                        deserialize(&child, is);
                    }
                }
            } else {
                *node = nullptr;
            }
        }

    private:
        static void serializePoint(const Vector3D& point, std::ostream& os) {
            for (int i = 0; i < 3; ++i) {
                os << point[i] << ",";
            }
            os << std::endl;
        }

        static void deserializePoint(Vector3D* point, std::istream& is) {
            for (int i = 0; i < 3; ++i) {
                (*point)[i] = is.read<Vector3D>();
            }
        }
    };

private:
    Node* root_;
};

} // namespace octree

