            storer(transaction);

            // Calculate weighted sum
            double weighted_sum = calculateWeightedSum(transaction->amount, transaction->description);

            // Check for errors during deserialization
            if (transaction->id == -1 || transaction->amount == 0.0) {
                printf("Error: Transaction ID or amount is invalid.\n");
