using System;
using System.Threading;

public class DynamicValueGenerator
{
    private int _minValue;
    private int _maxValue;
    private float _minFloatValue;
    private float _maxFloatValue;
    private Random _random;
    private bool _initialized = false;

    public DynamicValueGenerator(int minValue, int maxValue, float minFloatValue, float maxFloatValue)
    {
        _minValue = minValue;
        _maxValue = maxValue;
        _minFloatValue = minFloatValue;
        _maxFloatValue = maxFloatValue;
        _random = new Random();
        _initialized = true;
    }

    public void Reset()
    {
        if (_initialized)
        {
            _random = new Random();
            _initialized = false;
        }
        else
        {
            throw new InvalidOperationException("Generator has not been initialized.");
        }
    }

    public int GenerateRandomInt(int? min = null, int? max = null)
    {
        if (!_initialized)
        {
            throw new InvalidOperationException("Generator has not been initialized.");
        }

        var rangeMin = min ?? _minValue;
        var rangeMax = max ?? _maxValue;

        return _random.Next(rangeMin, rangeMax + 1);
    }

    public float GenerateRandomFloat(float? min = null, float? max = null)
    {
        if (!_initialized)
        {
            throw new InvalidOperationException("Generator has not been initialized.");
        }

        var rangeMin = min ?? _minFloatValue;
        var rangeMax = max ?? _maxFloatValue;

        return (float)_random.NextDouble() * (rangeMax - rangeMin) + rangeMin;
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator [min: {_minValue}, max: {_maxValue}, min float: {_minFloatValue}, max float: {_maxFloatValue}, seed: {_random.Seed}";
    }
}
