using Microsoft.Extensions.Logging;

namespace MarketDataReducer
{
    public class MarketDataReducer
    {
        private readonly ILogger<MarketDataReducer> _logger;
        private readonly CancellationTokenSource _cts = new CancellationTokenSource();
        private readonly ConcurrentDictionary<string, double> _aggregatedMetrics = new ConcurrentDictionary<string, double>();
        private readonly Func<double[], double> _aggregationFunction;

        public MarketDataReducer(ILogger<MarketDataReducer> logger, Func<double[], double> aggregationFunction)
        {
            _logger = logger;
            _aggregationFunction = aggregationFunction;
        }

        public async Task ComputeMetricAsync(string metricName, double[] dataPoints)
        {
            try
            {
                if (_cts.IsCancellationRequested)
                    return;

                var reducedValue = _aggregationFunction(dataPoints);

                while (!_cts.IsCancellationRequested)
                {
                    try
                    {
                        _aggregatedMetrics.AddOrUpdate(metricName, reducedValue, (key, value) => value);
                        break;
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError(ex, "Error aggregating metric {MetricName}", metricName);
                        await Task.Delay(100); // retry after 100ms
                    }
                }
            }
            catch (OperationCanceledException)
            {
                // cancellation requested
            }
        }

        public void Start()
        {
            _cts = new CancellationTokenSource();
        }

        public void Stop()
        {
            _cts.Cancel();
        }

        public double GetMetricValue(string metricName)
        {
            return _aggregatedMetrics.GetOrAdd(metricName, 0.0);
        }
    }
}
