#include "resource_manager.h"
#include <string.h>

char* processString(const char* input, int sizeLimit, int* resultSize, ResourceManager* rmgr, ErrorCallback onError) {
    // Validate the resource manager and log an error if it's not properly initialized
    if (!rmgr->isInitialized()) {
        onError("Resource Manager is not properly initialized");
        *resultSize = 0;
        return NULL;
    }

    // Check for null or empty input string
    if (input == NULL || strlen(input) == 0) {
        return NULL;
    }

    // Calculate the length of the input string, handling null bytes correctly
    size_t len = rmgr->calculateStringLength(input);

    // Append a single forward slash to the end of the string if it's within the size limit
    char* result;
    int newSize;
    if (len <= sizeLimit) {
        newSize = len + 1;
        result = rmgr->allocate(newSize);
        strcpy(result, input);
        result[newSize - 1] = '/';
    }
    // If the length exceeds the size limit, check available resources and allocate a new buffer
    else if (rmgr->hasAvailableResources()) {
        newSize = len + 2;
        result = rmgr->allocate(newSize);
        strcpy(result, input);
        result[newSize - 2] = '/';
        result[newSize - 1] = '\0';
    }
    // If resources are insufficient, return NULL
    else {
        onError("Insufficient resources");
        *resultSize = 0;
        return NULL;
    }

    // Update the result size and return the result
    *resultSize = newSize;
    return result;
}
