// Structure for log entry
typedef struct {
    char source[16];
    int timestamp;
    double metrics[5];
} LogEntry;

// Function to calculate moving average of last 5 numerical fields
double calcMovingAverage(LogEntry* entry) {
    double sum = 0.0;
    for (int i = 3; i < 8; i++) {
        if (entry->metrics[i] > 0.0)
            sum += entry->metrics[i];
    }
    return sum / (5 - 3);
}

// Function to process a log file, compute moving average and append it
void* processLogFile(void* arg) {
    FILE* file = (FILE*)arg;
    LogEntry entry;
    int lineNum = 0;

    while (fscanf(file, "%15s %d %lf %lf %lf %lf", 
                  entry.source, &entry.timestamp, &entry.metrics[0], &entry.metrics[1], 
                  &entry.metrics[2], &entry.metrics[3], &entry.metrics[4]) == 7) {
        lineNum++;

        // Compute moving average and append it to the end of the log entry
        double avg = calcMovingAverage(&entry);
        sprintf(entry.source, "%s %.2f", entry.source, avg);

        printf("%s\n", entry.source);
    }

    fclose(file);
}

// Function to handle API call for real-time data validation and correction
