    }

    // Implement retry logic with exponential backoff for failed API calls
    int retries = 3;
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);

        for (int j = 0; j < retries; j++) {
            if (validateLogEntry(NULL) == NULL)
                break;

            // Handle transient error
            sleep(j * 2); // Exponential backoff

            if (j >= retries - 1) {
                printf("Failed to validate log entries.\n");
                return 1;
            }
        }
    }

    fclose(file);

    return 0;
}

