// Structure to represent TIFF image metadata
typedef struct {
    uint16_t bits_per_sample;
    uint16_t samples_per_pixel;
    enum { uncompressed, lzw, packbits } compression_type;
} tiff_metadata;

// Function to parse TIFF image file and extract metadata
tiff_metadata* parse_tiff_file(const char* filename) {
    // Open the TIFF file for reading
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL;  // Return error or throw exception
    }

    // Read the TIFF header to determine bits per sample and samples per pixel
    uint16_t header[2];
    fread(header, sizeof(uint16_t), 2, file);
    tiff_metadata* metadata = malloc(sizeof(tiff_metadata));
    metadata->bits_per_sample = header[0];
    metadata->samples_per_pixel = header[1];

    // Read the TIFF compression type
    uint32_t compression_type;
    fseek(file, 4, SEEK_SET);  // Skip to compression type byte offset
    fread(&compression_type, sizeof(uint32_t), 1, file);
    switch (compression_type) {
        case uncompressed:
            metadata->compression_type = uncompressed;
            break;
        case lzw:
            metadata->compression_type = lzw;
            break;
        case packbits:
            metadata->compression_type = packbits;
            break;
        default:
            fclose(file);  // Return error or throw exception
            free(metadata);
            return NULL;  // Invalid compression type
    }

    // Close the file and return the metadata
    fclose(file);
    return metadata;
}

// Function to test the parse_tiff_file function
int main() {
    tiff_metadata* metadata = parse_tiff_file("test.tiff");
    if (metadata == NULL) {
        printf("Error parsing TIFF file\n");
    } else {
        printf("Bits per sample: %d, Samples per pixel: %d, Compression type: %s\n",
               metadata->bits_per_sample,
               metadata->samples_per_pixel,
               (metadata->compression_type == uncompressed ? "uncompressed" :
                (metadata->compression_type == lzw ? "LZW" : "PackBits")));
        free(metadata);
    }
    return 0;
}
