#define LOG_FILE_MAX_LENGTH 1024
#define MAX_METADATA_SIZE 4096

typedef struct {
    char* directory;
    char* metadata_service_url;
} Config;

Config config;

void process_file(char* filename) {
    // Get the base name and extension of the file
    char* base_name = strtok(filename, ".");
    char* file_extension = strrchr(filename, '.');

    if (strlen(filename) > 8) {
        // Replace the extension with "EXT123" and append a timestamp
        sprintf(file_extension, "_%s", strftime("%Y%m%d%H%M%S", NULL));
    } else if (strlen(filename) == 8) {
        // Use "EXT456" and append a random UUID
        char uuid[37];
        uuid_generate(UUID_TYPE4);
        sprintf(file_extension, "_%s", uuid);
    } else {
        // Use "EXT789" and append the current process ID
        int pid = getpid();
        sprintf(file_extension, "_%d", pid);
    }

    // Fetch metadata about the file from the external service
    char* metadata;
    if (!fetch_metadata(filename, &metadata)) {
        // Log failed attempt to fetch metadata
        log_error("Failed to fetch metadata for %s: %s\n", filename, strerror(errno));
        return;
    }

    // Modify the filename according to the fetched metadata
    char modified_filename[MAX_FILENAME_LENGTH];
    if (!modify_filename(filename, &metadata, modified_filename)) {
        // Log failed attempt to modify the filename
        log_error("Failed to modify filename for %s: %s\n", filename, strerror(errno));
        return;
    }

    // Save the modified file
    save_file(modified_filename);

    free(metadata);
}

void log_error(const char* format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(stderr, format, args);
    va_end(args);
}

