using System;
using System.Threading.Tasks;
using System.Data.SqlClient;
using System.Collections.Generic;

namespace DataProcessingPipeline
{
    public class DataProcessor
    {
        private readonly List<Task> _tasks = new();
        private readonly int _maxWorkerThreads;
        private readonly int _retryAttempts;
        private readonly TimeSpan _initialRetryDelay;
        private readonly TimeSpan _maximumRetryDelay;
        private readonly TimeSpan _transactionTimeout;
        private readonly string _connectionString;

        public DataProcessor(int maxWorkerThreads, int retryAttempts, TimeSpan initialRetryDelay, TimeSpan maximumRetryDelay, TimeSpan transactionTimeout, string connectionString)
        {
            _maxWorkerThreads = maxWorkerThreads;
            _retryAttempts = retryAttempts;
            _initialRetryDelay = initialRetryDelay;
            _maximumRetryDelay = maximumRetryDelay;
            _transactionTimeout = transactionTimeout;
            _connectionString = connectionString;
        }

        public void Start()
        {
            for (int i = 0; i < _maxWorkerThreads; i++)
            {
                Task task = new WorkerTask(_retryAttempts, _initialRetryDelay, _maximumRetryDelay, _connectionString);
                _tasks.Add(task);
                task.Start();
            }
        }

        private class WorkerTask : IRunnable
        {
            private readonly int _retryAttempts;
            private readonly TimeSpan _initialRetryDelay;
            private readonly TimeSpan _maximumRetryDelay;
            private readonly string _connectionString;

            public WorkerTask(int retryAttempts, TimeSpan initialRetryDelay, TimeSpan maximumRetryDelay, string connectionString)
            {
                _retryAttempts = retryAttempts;
                _initialRetryDelay = initialRetryDelay;
                _maximumRetryDelay = maximumRetryDelay;
                _connectionString = connectionString;
            }

            public void Run()
            {
                while (true)
                {
                    try
                    {
                        // Read raw byte streams from networked device
                        byte[] data = ...;

                        // Validate data against flexible schema
                        SchemaValidator validator = new SchemaValidator();
                        bool isValid = validator.Validate(data);

                        if (!isValid)
                        {
                            throw new Exception("Invalid data format");
                        }

                        // Persist data into cloud-hosted SQL Server database
                        using (SqlConnection connection = new SqlConnection(_connectionString))
                        {
                            connection.Open();

                            using (SqlCommand command = new SqlCommand("INSERT INTO ...", connection))
                            {
                                command.ExecuteNonQuery();
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        // Handle network disruptions gracefully with exponential backoff
                        int retryAttempt = 0;
                        TimeSpan delay = _initialRetryDelay;

                        while (retryAttempt < _retryAttempts && delay <= _maximumRetryDelay)
                        {
                            try
                            {
                                // Retry failed connection
                                // ...
                                break;
                            }
                            catch (Exception innerEx)
                            {
                                Console.WriteLine($"Failed to retry connection: {innerEx.Message}");
                                System.Threading.Thread.Sleep(delay);
                                delay = TimeSpan.FromMilliseconds(delay.Milliseconds * 2);

                                if (delay > _maximumRetryDelay)
                                {
                                    throw new Exception("Failed to reconnect after maximum retries", ex);
                                }
                            }

                            retryAttempt++;
                        }

                        if (retryAttempt >= _retryAttempts)
                        {
                            Console.WriteLine($"Failed to connect after {_retryAttempts} retries: {ex.Message}");
                            // Log failure and notify administrators
                        }
                    }
                }
            }
        }
    }
}
