using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace ApiIntegrator
{
    class Program
    {
        static readonly HttpClient _httpClient = new HttpClient();
        static readonly string _apiKey = Environment.GetEnvironmentVariable("API_KEY");
        static readonly string _encryptedKey = Environment.GetEnvironmentVariable("ENCRYPTED_KEY");

        static async Task Main(string[] args)
        {
            await StartApplication(args);
        }

        static async Task StartApplication(string[] args)
        {
            Console.WriteLine("API Integrator started...");

            // Initialize in-memory cache
            var cache = new Dictionary<int, DateTime>();

            while (true)
            {
                try
                {
                    // Fetch data from API
                    var response = await _httpClient.GetAsync("https://api.example.com/integers");
                    response.EnsureSuccessStatusCode();

                    // Parse JSON response and store integers in cache
                    var json = await response.Content.ReadAsStringAsync();
                    var integers = JsonConvert.DeserializeObject<int[]>(json);
                    foreach (var integer in integers)
                    {
                        cache.Add(integer, DateTime.Now);
                    }

                    // Find and print largest integer
                    var largestInteger = integers.Max();
                    Console.WriteLine($"Largest integer: {largestInteger}");

                    // Decrypt Base64-encoded string
                    var base64String = await _httpClient.GetAsync("https://api.example.com/base64").Content.ReadAsStringAsync();
                    var bytes = Convert.FromBase64String(base64String);
                    var tripleDes = new TripleDESCryptoServiceProvider();
                    tripleDes.Key = Encoding.ASCII.GetBytes(_encryptedKey);
                    tripleDes.IV = Encoding.ASCII.GetBytes(_encryptedKey);
                    var decryptedBytes = tripleDes.TransformFinalBlock(bytes, 0, bytes.Length);
                    Console.WriteLine($"Decrypted string: {Encoding.ASCII.GetString(decryptedBytes)}");

                    // Log operations
                    await WriteLog();

                    // Check for cache expiration and update cache
                    UpdateCache(cache);
                }
                catch (HttpRequestException ex)
                {
                    Console.WriteLine("Failed to retrieve data from API: " + ex.Message);
                    await WriteLog(ex);
                }
                catch (Exception ex)
                {
                    Console.WriteLine("Error: " + ex.Message);
                    await WriteLog(ex);
                }

                // Wait for 1 minute before next iteration
                await Task.Delay(60 * 1000);
            }
        }

        static async Task WriteLog(Exception exception = null)
        {
            try
            {
                using var fileStream = File.Open("log.txt", FileMode.Append);
                using var writer = new StreamWriter(fileStream);

                if (exception != null)
                {
                    await writer.WriteLineAsync($"Error at {DateTime.Now}: {exception.Message}");
                }
                else
                {
                    await writer.WriteLineAsync($"Operation completed at {DateTime.Now}");
                }

                fileStream.Flush();
            }
            catch (Exception ex)
            {
                Console.WriteLine("Failed to write log: " + ex.Message);
            }
        }

        static void UpdateCache(Dictionary<int, DateTime> cache)
        {
            foreach (var entry in cache.ToArray())
            {
                if ((DateTime.Now - entry.Value).Minutes > 10)
                {
                    cache.Remove(entry.Key);
                }
            }
        }
    }
}

