using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class Md5Service
{
    private readonly ConcurrentDictionary<string, string> _hashCache = new();
    private readonly ILogger _logger;
    private readonly CancellationTokenSource _cts = new();

    public Md5Service(ILogger logger)
    {
        _logger = logger;
    }

    public async Task<string> ComputeHashAsync(string input)
    {
        using (var md5 = MD5.Create())
        {
            var hashBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(input));
            return BitConverter.ToString(hashBytes).Replace("-", string.Empty);
        }
    }

    public async Task StoreHashAsync(string userId, string timestamp, string hashValue)
    {
        try
        {
            _hashCache.AddOrUpdate(userId + "-" + timestamp, hashValue, (key, value) => value);
            await _logger.LogAsync(new LogEntry
            {
                Timestamp = DateTime.Now,
                UserIdentifier = userId,
                EventType = "Hash computation and storage",
                Data = $"User {userId} computed and stored hash '{hashValue}'"
            });
        }
        catch (Exception ex)
        {
            await HandleErrorAsync(ex);
        }
    }

    public async Task<string> GetHashAsync(string userId, string timestamp)
    {
        try
        {
            return _hashCache.GetOrAdd(userId + "-" + timestamp, default);
        }
        catch (Exception ex)
        {
            await HandleErrorAsync(ex);
            return null;
        }
    }

    private async Task HandleErrorAsync(Exception ex)
    {
        await _logger.LogAsync(new LogEntry
        {
            Timestamp = DateTime.Now,
            UserIdentifier = "System",
            EventType = "Error",
            Data = $"Error occurred: {ex.Message}"
        });
    }

    public void Cleanup()
    {
        var expiredHashes = _hashCache.Where(x => DateTime.UtcNow - x.Key.ToDateTime() > TimeSpan.FromDays(30));
        foreach (var pair in expiredHashes)
        {
            _hashCache.TryRemove(pair.Key, out _);
        }
    }
}

public class LogEntry
{
    public DateTime Timestamp { get; set; }
    public string UserIdentifier { get; set; }
    public string EventType { get; set; }
    public string Data { get; set; }
}
