            _logger.LogError(ex, "Failed to save configurations.");
            throw;
        }
    }

    private Configurations DecryptConfigurations(Configurations configurations)
    {
        byte[] encryptedBytes = Convert.FromBase64String(configurations.ToString());
        using (Aes aes = Aes.Create())
        {
            aes.Key = await _kms.GetEncryptionKeyAsync();
            aes.IV = await _kms.GenerateIVAsync();

            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    cs.Write(encryptedBytes, 0, encryptedBytes.Length);
                }

                byte[] decryptedBytes = ms.ToArray();
                configurations = JsonConvert.DeserializeObject<Configurations>(Encoding.UTF8.GetString(decryptedBytes));
            }
        }

        return configurations;
    }

    private string EncryptConfigurations(Configurations configurations)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = await _kms.GetEncryptionKeyAsync();
            aes.IV = await _kms.GenerateIVAsync();

            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, aes.CreateEncryptor(), CryptoStreamMode.Write))
                {
                    byte[] configurationBytes = Encoding.UTF8.GetBytes(JsonConvert.SerializeObject(configurations));
                    cs.Write(configurationBytes, 0, configurationBytes.Length);
                }

                return Convert.ToBase64String(ms.ToArray());
            }
        }
    }
}

