            graph[vertex["id"]] = {"metadata": vertex.get("metadata"), "sensitive_attributes": {}}
            if vertex.get("sensitive_attributes"):
                for attribute, value in vertex["sensitive_attributes"].items():
                    encrypted_value = self.encrypt(value)
                    graph[vertex["id"]]["sensitive_attributes"][attribute] = encrypted_value
        for edge in edges:
            graph[edge["start_id"]].setdefault("edges", [])
            graph[edge["end_id"]].setdefault("edges", [])
            graph[edge["start_id"]]["edges"].append(edge["end_id"])
            graph[edge["end_id"]]["edges"].append(edge["start_id"])
        return graph

