use clap::{App, Arg};

#[derive(Serialize, Deserialize)]
struct Data {
    id: u32,
    name: String,
}

async fn fetch_data(url: &str) -> Result<Data, Box<dyn std::error::Error>> {
    let client = reqwest::Client::new();
    let resp = client.get(url).send().await?;
    let data: Data = resp.json().await?;
    Ok(data)
}

async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let app = App::new("API Fetcher")
        .version("1.0")
        .author("Your Name")
        .about("Fetches data from multiple APIs asynchronously using Tokio");
    let args = app.args();

    let (data_type, source_endpoint) = match &*args {
        [arg] => (arg.clone(), "default_endpoints".to_string()),
        _ => panic!("Invalid number of arguments"),
    };

    // Set up Redis client
    let redis_client = Client::open("redis://localhost:6379/0").unwrap();

    // Fetch data from API(s)
    match fetch_data(&source_endpoint).await {
        Ok(data) => {
            // Cache the fetched data using Redis
            let mut pipeline = redis_client.get_pipeline();
            pipeline.set(format!("data:{}", data_type), serde_json::to_string_pretty(&data)?).exec().unwrap();
            println!("Fetched and cached {} data", data_type);
        }
        Err(err) => {
            eprintln!("Error fetching {}: {}", source_endpoint, err);
            // Handle error
        },
    };

    Ok(())
}

fn main() {
    tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .unwrap()
        .block_on(main());
}
