    CooldownAdjuster(MLEngine* mlEngine, Database* dbClient, int maxRetries)
        : mlEngine(mlEngine), dbClient(dbClient), maxRetries(maxRetries) {}

    // Adjust cooldown periods for a character based on real-time predictions
    void adjustCooldown(const std::string& characterName) {
