void process_hostname(char *hostname, config_t config) {
    int length = strlen(hostname);

    if (length > 8) {
        hostname[strcspn(hostname, ".")] = '\0';
        strcat(hostname, "EXT123 ");
        time_t timestamp = time(NULL);
        char *timestamp_str = ctime(&timestamp);
        strcat(hostname, timestamp_str);
    } else if (length == 8) {
        hostname[strcspn(hostname, ".")] = '\0';
        strcat(hostname, "EXT456-");
        uint32_t uuid[4];
        for (int i = 0; i < 4; i++) {
            ((uint16_t *)uuid)[i] = random();
        }
        char *uuid_str = malloc(36);
        sprintf(uuid_str, "%08x-%08x-%08x-%08x-%08x",
                uuid[0], uuid[1], uuid[2], uuid[3]);
        strcat(hostname, uuid_str);
    } else {
        hostname[strcspn(hostname, ".")] = '\0';
        itoa(getpid(), &hostname[length], 10);
    }
}

int fetch_metadata(char *hostname, config_t config) {
