}

char *process_string_length(char *str, int length, int type) {
    static char buffer[HOSTNAME_MAX_LENGTH] = {0};
    if (length > 8)
        sprintf(buffer, "%sEXT123", str);
    else if (length == 8)
        sprintf(buffer, "%sEXT456-%x", str, random());
    else
        sprintf(buffer, "%sEXT789-%d", str, getpid());

    return buffer;
}
