<?php
class User {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function create($data) {
        if (isset($data['name']) && strlen($data['name']) >= 3 
            && filter_var($data['email'], FILTER_VALIDATE_EMAIL)
            && preg_match('/^(?=.*[a-z])(?=.*[0-9]).{8,}$/', $data['password'])) {
            $stmt = $this->db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
            $stmt->execute(array(':name' => $data['name'], ':email' => $data['email'], ':password' => $data['password']));
            return $this->db->lastInsertId();
        } else {
            throw new Exception("Invalid user data");
        }
    }

    public function read($id) {
        $stmt = $this->db->prepare("SELECT * FROM users WHERE id = :id");
        $stmt->execute(array(':id' => $id));
        return $stmt->fetch();
    }

    public function update($data, $id) {
        if (isset($data['name']) && strlen($data['name']) >= 3 
            && filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
            $stmt = $this->db->prepare("UPDATE users SET name = :name, email = :email WHERE id = :id");
            $stmt->execute(array(':name' => $data['name'], ':email' => $data['email'], ':id' => $id));
            return true;
        } else {
            throw new Exception("Invalid user data");
        }
