    new_node->algorithm = alg;
    new_node->next = NULL;
    return new_node;
}

void add_algorithm_to_list(LinkedList** head, Algorithm* algorithm) {
    LinkedList* new_node = create_list(algorithm);
    if (*head == NULL || (*head)->algorithm->name > new_node->algorithm->name) {
        new_node->next = *head;
        *head = new_node;
    } else {
        LinkedList* current = *head;
        while (current->next && current->next->algorithm->name <= new_node->algorithm->name) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
