```rust
use tokio::prelude::*;
use tokio::net::{TcpListener, TcpStream};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

#[tokio::main]
async fn main() {
    let listener = TcpListener::bind("0.0.0.0:8080").await.unwrap();
    loop {
        let (stream, _) = listener.accept().await.unwrap();
        tokio::spawn(handle_stream(stream));
    }
}

async fn handle_stream(mut stream: TcpStream) {
    let args = get_args(&mut stream).await;
    match process_args(args) {
        Ok(_) => println!("Service started"),
        Err(err) => println!("Error: {}", err),
    }
}

async fn get_args(mut stream: TcpStream) -> Result<HashMap<String, String>, String> {
    let mut args = HashMap::new();
    loop {
        let line = stream.recv_line().await?;
        if line.is_empty() {
            break;
        }
        let parts: Vec<&str> = line.trim().split_whitespace().collect();
        if parts.len() != 2 {
            return Err("Invalid input format. Expected <key> <value>".to_string());
        }
        args.insert(parts[0].to_string(), parts[1].to_string());
    }
    Ok(args)
}

fn process_args(mut args: HashMap<String, String>) -> Result<(), String> {
    // implement the logic for processing command-line arguments
    match &*args.get("key") {
        Some(value) => println!("Key: {}, Value: {}", value, "some_value"),
        None => return Err("Key not found".to_string()),
    }
    Ok(())
}

