        int retries = 0;
        while (retries < 3) {
            if (!isUpdateFailed()) {
                break;
            }
            this_thread::sleep_for(chrono::milliseconds(500)); // wait for 500ms before retrying
            retries++;
        }

        if (retries >= 3) {
