const fs = require('fs');
const path = require('path');
const jsonfile = require('jsonfile');
const axios = require('axios');
const { Worker } = require('worker_threads');
const { Queue, WorkerPool } = require('bull');

class FileProcessor {
  constructor(options) {
    this.options = options;
    this.queue = new Queue('file-processor', this.options);
    this.workerPool = new WorkerPool(this.queue, this.options);
  }

  async start() {
    await fs.watchFile(this.options.directory, (curr, prev) => {
      if (!prev) return; // Ignore initial event
      const files = Object.keys(curr);
      for (const file of files) {
        const filePath = path.join(this.options.directory, file);
        if (curr[file] === 0 && prev[file] > 0) {
          // New file added
          this.queue.add(filePath);
        }
      }
    });
  }

  async processFile(file) {
    try {
      const json = await fs.readFile(file, 'utf8');
      const data = JSON.parse(json);
      if (!this.options.validators.every((validator) => validator(data))) return;
      // Validate and aggregate data
      const aggregatedData = this.options.aggregator(data);
      // Send to analytics API with caching (TTL: 5 minutes)
      await axios.post(this.options.analyticsApi, { data: aggregatedData }, {
        headers: { 'Content-Type': 'application/json' },
        params: { cache: true, ttl: 300000 },
      });
    } catch (err) {
      console.error(`Error processing file ${file}:`, err);
    }
  }

  async notifyExceedingQueue() {
    const queueLength = await this.queue.length();
    if (queueLength > this.options.threshold && Date.now() - this.options.lastNotification > this.options.notificationInterval) {
      // Send email notification
      console.log('Notification sent: Queue length exceeded');
      this.options.lastNotification = Date.now();
    }
  }

  async stop() {
    await this.queue.empty();
    await this.workerPool.close();
  }
}

module.exports = FileProcessor;
