function updateTheme(themeId) {
  // Update the theme cache and notify connected clients
  io.emit('themeUpdate', themeId);
}

// Define a function to handle socket connections
io.on('connection', (socket) => {
  console.log('New client connected');

  // Handle incoming data streams
  socket.on('data', (data) => {
    const processedData = processIncomingData(data);
    io.emit('data', processedData);
  });

  // Handle theme changes
  socket.on('themeChange', (themeId) => {
    updateTheme(themeId);
  });

  // Handle disconnections
