package com.highfrequencytrading;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class HighFrequencyTradingAnalyzer {

    // Method to identify disjoint consecutive timestamp pairs
    public List<List<Long>> findTimestampPairs(List<Long> timestamps) {
        List<List<Long>> result = new ArrayList<>();
        long prevTimestamp = Long.MIN_VALUE;

        for (long timestamp : timestamps) {
            if (timestamp - prevTimestamp == 1) {
                result.add(new ArrayList<>(Arrays.asList(prevTimestamp, timestamp)));
            }
            prevTimestamp = timestamp;
        }

        return result;
    }

    // Method to validate transactions using an external API
    public boolean validateTransactions(List<Transaction> transactions) throws Exception {
        for (Transaction transaction : transactions) {
            if (!validateTransactionWithAPI(transaction)) {
                throw new Exception("Invalid transaction: " + transaction);
            }
        }

        return true;
    }

    // Method to retrieve historical data using an external API
    public List<HistoricalData> getHistoricalData(List<Transaction> transactions) throws Exception {
        List<HistoricalData> result = new ArrayList<>();

        for (Transaction transaction : transactions) {
            try {
                HistoricalData data = retrieveDataFromAPI(transaction);
                result.add(data);
            } catch (Exception e) {
                // Handle API failure
                throw e;
            }
        }

        return result;
    }

    // Concurrency management using ExecutorService
    public void processTransactions(List<Transaction> transactions) {
        ExecutorService executor = Executors.newFixedThreadPool(5);

        for (Transaction transaction : transactions) {
            executor.submit(() -> processTransaction(transaction));
        }

        executor.shutdown();
    }

    // Performance optimization using parallel processing
    public List<HistoricalData> retrieveHistoricalDataInParallel(List<Transaction> transactions) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(5);

        List<Future<HistoricalData>> futures = new ArrayList<>();

        for (Transaction transaction : transactions) {
            Callable<HistoricalData> task = () -> retrieveDataFromAPI(transaction);
            Future<HistoricalData> future = executor.submit(task);
            futures.add(future);
        }

        List<HistoricalData> result = new ArrayList<>();

        for (Future<HistoricalData> future : futures) {
            try {
                HistoricalData data = future.get();
                result.add(data);
            } catch (Exception e) {
                // Handle API failure
                throw e;
            }
        }

        return result;
    }

    // Error handling using try-catch blocks and custom exceptions
    public void processTransaction(Transaction transaction) {
        try {
            validateTransactionWithAPI(transaction);
        } catch (InvalidTransactionException e) {
            // Handle invalid transaction
            System.out.println("Invalid transaction: " + transaction);
        }
    }
}
