public class ThemeManager {
    private static final String CACHE_ROOT = "/cache";
    private static final String DEFAULT_THEME = "default_theme.png";
    private Map<String, Bitmap> themeCache = new HashMap<>();
    private File cacheRootDir;
    private ExternalThemeRepository externalRepo;

    public ThemeManager() {
        cacheRootDir = new File(CACHE_ROOT);
        if (!cacheRootDir.exists()) {
            cacheRootDir.mkdirs();
        }
    }

    public void initializeDefaultTheme() {
        String defaultThemePath = cacheRootDir.getAbsolutePath() + "/" + DEFAULT_THEME;
        Bitmap defaultBitmap = loadBitmapFromDisk(defaultThemePath);
        themeCache.put(DEFAULT_THEME, defaultBitmap);
    }

    public Bitmap getTheme(String themeName) throws IOException {
        if (themeCache.containsKey(themeName)) {
            return themeCache.get(themeName);
        } else {
            Bitmap bitmap = loadBitmapFromExternalRepo(themeName);
            if (bitmap != null) {
                themeCache.put(themeName, bitmap);
                return bitmap;
            } else {
                return getFallbackTheme();
            }
        }
    }

