impl HttpClient {
    fn new(config: ClientConfig) -> Self {
        let config = Arc::new(Mutex::new(config));
        let mut connections = Vec::new();

        // Initialize connection pool with initial connections
        for _ in 0..5 {
            connections.push(Connection::new());
        }

        let connection_pool = Arc::new(Mutex::new(connections));

        HttpClient { config, connection_pool }
    }

    fn send_request(&self, request: Request) -> Response {
        // Acquire a connection from the pool
        let mut connections = self.connection_pool.lock().unwrap();
        if connections.is_empty() {
            thread::sleep(Duration::from_millis(100));
            return self.send_request(request);
        }
        let connection = connections.pop().unwrap();

        // Send the request and receive the response
        let response = connection.send_request(request);

        // Release the connection back into the pool
        connections.push(connection);

        response
    }

    fn close_connection(&self, connection: &Connection) {
        // Remove the connection from the pool and release any resources it holds
    }
}

