    // Initialize NIC statistics threads
    pthread_t nic_stats_threads[MAX_CONCURRENT_THREADS];
    for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        pthread_create(&nic_stats_threads[i], NULL, nic_stats_thread, NULL);
    }

    // Simulate network events and update NIC statistics
    while (1) {
        // Update NIC statistics based on real-time network events
        for (int i = 0; i < num_interfaces; i++) {
            uint32_t packets = rand() % 100;
            uint64_t bytes = rand() % 1000000;
            update_nic_stats(i, packets, bytes);
        }

        // Sleep for a short duration to simulate latency
        usleep(MIN_LATENCY * 1000);
    }

    return 0;
}

void* nic_stats_thread(void* arg) {
    while (1) {
        // Fetch NIC statistics and perform analytics
        for (int i = 0; i < num_interfaces; i++) {
            nic_stats_t* stats = get_nic_stats(i);
            printf("Interface: %s, Packets: %u, Bytes: %llu, Timestamp: %ld\n", 
                   stats->interface_name, stats->packet_counts, stats->byte_counts, stats->timestamp);
        }

        // Sleep for a short duration to simulate latency
        usleep(MIN_LATENCY * 1000);
    }
}

