    d->tail = NULL;
    d->size = 0;
    pthread_mutex_init(&d->lock, NULL);
    return d;
}

void dll_free(DLL* d) {
    Node* current = d->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(d);
}

int dll_insert(DLL* d, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->prev = NULL;
    node->next = NULL;

    pthread_mutex_lock(&d->lock);

    if (d->head == NULL) {
        d->head = node;
        d->tail = node;
    } else {
        node->next = d->head;
        d->head->prev = node;
        d->head = node;
    }

    d->size++;
    pthread_mutex_unlock(&d->lock);

    return 0;
}

int dll_remove(DLL* d, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* current = d->head;
    while (current != NULL && current->data != data) {
        current = current->next;
    }

    if (current == NULL) {
        return -1; // Not found
    }

    pthread_mutex_lock(&d->lock);

    if (current == d->head) {
        d->head = current->next;
    } else if (current == d->tail) {
        d->tail = current->prev;
    }

    if (current->prev != NULL) {
        current->prev->next = current->next;
    }
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }

    free(current);
    d->size--;
    pthread_mutex_unlock(&d->lock);

    return 0;
}

int dll_get_size(DLL* d) {
    return d->size;
}
