async function asyncReduce(accumulator, callback) {
  return new Promise((resolve, reject) => {
    const transactions = [];
    let error;

    (async () => {
      for await (const transaction of getTransactions()) {
        try {
          const result = await callback({ ...transaction, accumulator });
          if (!result || typeof result !== 'number') {
            throw new Error('Invalid transaction format');
          }
          transactions.push(result);
        } catch (err) {
          error = err;
          break;
        }
      }

      if (error) {
        reject(error);
      } else {
        resolve({ total: transactions.reduce((a, b) => a + b, 0), transactions });
      }
    })();

    function getTransactions() {
      // simulate real-time transactions from multiple sources
      return [
        { id: 1, amount: 100.00 },
        { id: 2, amount: 50.00 },
        { id: 3, amount: 200.00 },
        // ...
      ];
    }

    function externalFinancialServiceValidation(transaction) {
      // simulate integration with an external financial service
      return new Promise((resolve, reject) => {
        setTimeout(() => {
          if (Math.random() < 0.5) {
            resolve();
          } else {
            reject(new Error('Transaction validation failed'));
          }
        }, 500);
      });
    }

    function processTransaction(transaction) {
      // simulate processing each transaction
      return new Promise((resolve, reject) => {
        setTimeout(() => {
          try {
            const isValid = await externalFinancialServiceValidation(transaction);
            if (isValid) {
              resolve({ ...transaction, isValid: true });
            } else {
              reject(new Error('Transaction validation failed'));
            }
          } catch (err) {
            reject(err);
          }
        }, 500);
      });
    }

    async function processTransactions() {
      for await (const transaction of getTransactions()) {
        try {
          const processedTransaction = await processTransaction(transaction);
          if (!processedTransaction || !processedTransaction.isValid) {
            throw new Error('Invalid transaction format');
          }
        } catch (err) {
          error = err;
          break;
        }
      }

      if (error) {
        reject(error);
      } else {
        resolve({ total: transactions.reduce((a, b) => a + b, 0), transactions });
      }
    }

    processTransactions();
  });
}
