["```cpp
#include <boost/asio.hpp>
#include <boost/enable_shared_from_this.hpp>
#include <string>

class StringProcessor {
public:
    std::string processStringAsync(const char* input, int sizeLimit, int& resultSize, boost::asio::io_service& rmgr, void (*onError)(int)) {
        if (!rmgr.is_open()) {
            onError(1);
            resultSize = 0;
            return nullptr;
        }

        if (!input || *input == '\0') {
            return nullptr;
        }

        int len = std::strlen(input);

        if (len > sizeLimit) {
            char* buffer = rmgr.alloc(len + 1);
            boost::asio::async_write(rmgr, boost::asio::buffer(buffer), [this, &rmgr, buffer, onError, &resultSize](boost::system::error_code ec, std::size_t bytes_transferred) {
                if (ec) {
                    onError(2);
                    resultSize = 0;
                }
            });
        } else {
            rmgr.alloc(len + 1);
        }

        return input;
    }
};
```"]

