    uint16_t    byte_offset;     // offset of first IFD
    uint16_t    total_images;
} TIFFHeader;

// Define structure for TIFF image data
typedef struct {
    uint32_t    width;
    uint32_t    height;
    uint16_t    bits_per_sample;
    uint16_t    samplesPerPixel;
    uint8_t     *image_data;
