// Define function to parse TIFF file header
TIFFHeader* parse_TIFF_header(FILE *file) {
    // Read and validate TIFF header fields
    TIFFHeader* header = (TIFFHeader*)malloc(sizeof(TIFFHeader));
    fread(&header->tif_header, sizeof(header->tif_header), 1, file);
    if (fread(&header->byte_offset, sizeof(header->byte_offset), 1, file) != 1)
        return NULL;
    if (fread(&header->total_images, sizeof(header->total_images), 1, file) != 1)
        return NULL;

    // Check for valid TIFF header
    if (strcmp(header->tif_header, "II") && strcmp(header->tif_header, "MM"))
        return NULL;

    return header;
}

// Define function to read and process TIFF image data
TIFFImage* read_TIFF_image(FILE *file) {
    // Read and validate TIFF image fields
    TIFFImage* image = (TIFFImage*)malloc(sizeof(TIFFImage));
    fread(&image->width, sizeof(image->width), 1, file);
    if (fread(&image->height, sizeof(image->height), 1, file) != 1)
        return NULL;
    if (fread(&image->bits_per_sample, sizeof(image->bits_per_sample), 1, file) != 1)
        return NULL;
    if (fread(&image->samplesPerPixel, sizeof(image->samplesPerPixel), 1, file) != 1)
        return NULL;

    // Read and process TIFF image data
    image->image_data = (uint8_t*)malloc(image->width * image->height * image->samplesPerPixel);
    fread(image->image_data, 1, image->width * image->height * image->samplesPerPixel, file);

