using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using LZ4;
using Newtonsoft.Json;

public class LogProcessorService
{
    private readonly ILogger _logger;
    private readonly ILogFormatParser[] _parsers;
    private readonly CompressionSettings _compressionSettings;

    public LogProcessorService(ILogger logger, ILogFormatParser[] parsers, CompressionSettings compressionSettings)
    {
        _logger = logger;
        _parsers = parsers;
        _compressionSettings = compressionSettings;
    }

    public async Task ProcessLogsAsync(string logFilePath)
    {
        using (var fileStream = File.OpenRead(logFilePath))
        {
            await CompressAndProcessLog(fileStream);
        }
    }

    private async Task CompressAndProcessLog(Stream logStream)
    {
        var compressedData = await CompressLog(logStream);
        await ProcessCompressedLog(compressedData);
    }

    private async Task<byte[]> CompressLog(Stream logStream)
    {
        using (var compressedStream = new MemoryStream())
        {
            using (var lz4Stream = new Lz4OutputStream(compressedStream, _compressionSettings))
            {
                await logStream.CopyToAsync(lz4Stream);
                return compressedStream.ToArray();
            }
        }
    }

    private async Task ProcessCompressedLog(byte[] compressedData)
    {
        foreach (var parser in _parsers)
        {
            var logs = parser.Parse(compressedData);
            foreach (var log in logs)
            {
                await _logger.LogAsync(log);
            }
        }
    }
}

public interface ILogger
{
    Task LogAsync(object log);
}

public interface ILogFormatParser
{
    IEnumerable<object> Parse(byte[] compressedData);
}
