using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;
using MongoDB.Bson;
using MongoDB.Driver;

namespace DataIngestionPipeline
{
    public class FileProcessor
    {
        private readonly MongoClient _mongoClient;
        private readonly IFileAdapter[] _adapters;

        public FileProcessor(MongoClient mongoClient, IFileAdapter[] adapters)
        {
            _mongoClient = mongoClient;
            _adapters = adapters;
        }

        public async Task ProcessFiles(string[] filepaths)
        {
            foreach (string filepath in filepaths)
            {
                if (!File.Exists(filepath))
                {
                    Console.WriteLine($"File not found: {filepath}");
                    continue;
                }

                string filename = Path.GetFileName(filepath);
                string extension = Path.GetExtension(filepath);

                IFileAdapter adapter = _adapters.FirstOrDefault(ad => ad.SupportsFormat(extension));
                if (adapter == null)
                {
                    Console.WriteLine($"Unsupported file format: {extension}");
                    continue;
                }

                try
                {
                    await adapter.ProcessFile(filepath, filename);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing file: {filepath} - {ex.Message}");
                }
            }
        }
    }

    public interface IFileAdapter
    {
        bool SupportsFormat(string extension);

        Task ProcessFile(string filepath, string filename);
    }

    public class JsonFileAdapter : IFileAdapter
    {
        public bool SupportsFormat(string extension)
        {
            return extension == ".json";
        }

        public async Task ProcessFile(string filepath, string filename)
        {
            string json = await File.ReadAllTextAsync(filepath);
            MongoDB.Bson.Document doc = BsonDocument.Parse(json);
            _mongoClient.GetDatabase("mydatabase").GetCollection<BsonDocument>("mycollection").InsertOne(doc);
        }
    }

    public class BinaryFileAdapter : IFileAdapter
    {
        public bool SupportsFormat(string extension)
        {
            return extension == ".bin";
        }

        public async Task ProcessFile(string filepath, string filename)
        {
            byte[] data = await File.ReadAllBytesAsync(filepath);
            _mongoClient.GetDatabase("mydatabase").GetCollection<BsonDocument>("mycollection").InsertOne(new BsonDocument("_id", filename));
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            MongoClient mongoClient = new MongoClient("mongodb://localhost:27017/");
            IFileAdapter[] adapters = new IFileAdapter[] { new JsonFileAdapter(), new BinaryFileAdapter() };

            string[] filepaths = new string[] { @"C:\path\to\file1.json", @"C:\path\to\file2.bin" };
            FileProcessor processor = new FileProcessor(mongoClient, adapters);
            await processor.ProcessFiles(filepaths);
        }
    }
}
