extern crate threadpool;
use std::sync::{Arc, Mutex};
use std::thread;
use threadpool::{ThreadPool, WorkerId};

#[derive(Debug)]
struct NicStats {
    packet_counts: Vec<u32>,
    byte_counts: Vec<u32>,
    timestamps: Vec<f64>,
}

impl NicStats {
    fn new() -> NicStats {
        NicStats {
            packet_counts: vec![0; 5000],
            byte_counts: vec![0; 5000],
            timestamps: vec![0.0; 5000],
        }
    }

    fn update(&mut self, interface_id: usize, packets: u32, bytes: u32, timestamp: f64) {
        self.packet_counts[interface_id] = packets;
        self.byte_counts[interface_id] = bytes;
        self.timestamps[interface_id] = timestamp;
    }

    fn get_stats(&self, interface_id: usize) -> (u32, u32, f64) {
        (
            self.packet_counts[interface_id],
            self.byte_counts[interface_id],
            self.timestamps[interface_id],
        )
    }
}

struct NicStatsManager {
    stats: Arc<Mutex<NicStats>>,
    worker_pool: ThreadPool<4>,
}

impl NicStatsManager {
    fn new() -> NicStatsManager {
        NicStatsManager {
            stats: Arc::new(Mutex::new(NicStats::new())),
            worker_pool: ThreadPool::new(4),
        }
    }

    fn update_stats(&self, interface_id: usize, packets: u32, bytes: u32, timestamp: f64) {
        self.worker_pool.execute(move || {
            let mut stats = self.stats.lock().unwrap();
            stats.update(interface_id, packets, bytes, timestamp);
        });
    }
}

fn main() {
    let manager = NicStatsManager::new();

    // Update statistics concurrently
    for _ in 0..5000 {
        manager.update_stats(_ as usize, 10, 100, 1643723456.5);
    }

    // Read statistics concurrently
    let (packets, bytes, timestamp) = manager.stats.lock().unwrap().get_stats(0);

    println!("Packets: {}, Bytes: {}, Timestamp: {}", packets, bytes, timestamp);
}
