import json
import requests
from typing import Any, Dict, List

class DynamicJsonParser:
    def __init__(self):
        self._factory_registry = {}
        self._schema_version = "1.0"
        self._api_url = "https://example.com/api/schema"

    def register_factory(self, factory_id: str, factory_func: Any) -> None:
        self._factory_registry[factory_id] = factory_func

    def create_instance(self, factory_id: str, data: Dict[str, Any]) -> Any:
        try:
            factory_func = self._factory_registry[factory_id]
            return factory_func(data)
        except KeyError:
            return None  # handle missing or mismatched IDs gracefully

    def fetch_schema(self) -> Dict[str, Any]:
        response = requests.get(self._api_url)
        if response.status_code == 200:
            return json.loads(response.text)
        else:
            return {}  # default to an empty schema on failure

    def parse_json(self, json_string: str) -> Any:
        try:
            data = json.loads(json_string)
            return self.parse_data(data, self._schema_version)
        except json.JSONDecodeError:
            return None  # invalid JSON string

    def parse_data(self, data: Dict[str, Any], schema_version: str) -> Any:
        if not data:
            return None
        try:
            parsed_data = {}
            for key, value in data.items():
                if isinstance(value, dict):
                    parsed_data[key] = self.parse_data(value, schema_version)
                elif isinstance(value, list):
                    parsed_data[key] = [self.parse_data(item, schema_version) for item in value]
                else:
                    parsed_data[key] = value
            return parsed_data
        except Exception as e:
            print(f"Error parsing data: {e}")
            return None

    def serialize(self, data: Any) -> str:
        try:
            return json.dumps(data)
        except Exception as e:
            print(f"Error serializing data: {e}")
            return None

    def validate_schema(self, schema_version: str) -> bool:
        if self._schema_version != schema_version:
            # backward compatibility for older versions
            if self._schema_version == "0.9":
                return True  # allow older versions to pass validation
            else:
                return False  # fail validation for unknown or newer versions
        return True  # validate using the current schema version

    def migrate_schema(self, new_schema_version: str) -> None:
        if self._schema_version != "1.0":
            print(f"Schema migration from {self._schema_version} to {new_schema_version}")
            self._schema_version = new_schema_version
