#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_CLIENTS 200
#define BUFFER_SIZE 1024
#define INT_MAX (int)0x7fffffff
#define INT_MIN (int)0x80000000

typedef struct {
    int socket;
    char ip[16];
} client_t;

// Function to validate integer and log errors if necessary
void process_integer(int *data, int length) {
    for (int i = 0; i < length; i++) {
        int value = data[i];
        // Validate integer range
        if (value < INT_MIN || value > INT_MAX) {
            printf("Invalid integer: %d\n", value);
            return;
        }
    }
}

// Function to print the top ten largest integers in the current dataset
void print_top_ten(int *data, int length) {
    int max = INT_MIN;
    int count[10] = {0};

    for (int i = 0; i < length; i++) {
        if (data[i] > max) {
            max = data[i];
            memset(count, 0, sizeof(count));
            count[0]++;
        } else if (data[i] == max && max != INT_MAX) {
            count[count[0]]++;
        }
    }

    printf("Top Ten Largest Integers: \n");
    for (int i = 9; i >= 0; i--) {
        if (count[i] > 0) {
            printf("%d: %d occurrences\n", max, count[i]);
        }
    }
}

// Function to handle concurrent data streams
void *handle_client(void *arg) {
    client_t *client = arg;
    int sock = client->socket;

    // Process data from the client
    char buffer[BUFFER_SIZE];
    while (1) {
        int length = read(sock, buffer, BUFFER_SIZE);
        if (length < 0) {
            printf("Error reading from socket\n");
            break;
        } else if (length == 0) {
            printf("Socket closed by client\n");
            break;
        }
        // Process the received data
        int *data = (int *)buffer;
        process_integer(data, length / sizeof(int));
    }

    close(sock);
    return NULL;
}

// Function to manage concurrent clients and their connections
void start_server() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);

    // Create a socket for the server
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        printf("Error creating server socket\n");
        return;
    }

    // Set up the server address and bind the socket
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        printf("Error binding server socket\n");
        return;
    }

    // Listen for incoming connections
    listen(server_fd, MAX_CLIENTS);

    printf("Server started. Listening for connections...\n");

    pthread_t threads[MAX_CLIENTS];
    client_t clients[MAX_CLIENTS];

    while (1) {
        // Accept a new connection
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            printf("Error accepting client\n");
            continue;
        }

        for (int i = 0; i < MAX_CLIENTS; i++) {
            if (!clients[i].socket) {
                clients[i].socket = client_fd;
                pthread_create(&threads[i], NULL, handle_client, &clients[i]);
                break;
            }
        }
    }
}

// Function to start the server thread
void start_server_thread() {
    pthread_t server_thread;
    pthread_create(&server_thread, NULL, start_server, NULL);
}

int main() {
    // Start the server thread
    start_server_thread();
    return 0;
}
