import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DistributedService {

    private final ExecutorService executor = Executors.newCachedThreadPool();
    private AsynchronousServerSocketChannel serverSocket;
    private List<Connection> connections = new ArrayList<>();
    private ExternalAuthenticationService authenticationService;

    public DistributedService(InetSocketAddress address, ExternalAuthenticationService authenticationService) {
        this.serverSocket = AsynchronousServerSocketChannel.open();
        this.authenticationService = authenticationService;
        serverSocket.bind(address);
        serverSocket.accept(executor, (channel, result) -> {
            if (result.isCompletedExceptionally()) {
                return;
            }
            channel.setOption(AsynchronousSocketChannel.OPTION_REUSEADDR, true);
            Connection connection = new Connection(channel, authenticationService);
            connections.add(connection);
        });
    }

    public void start() {
        while (true) {
            AsynchronousSocketChannel socket = serverSocket.accept().get();
            executor.submit(() -> {
                try {
                    handleConnection(socket);
                } catch (IOException | InterruptedException e) {
                    // handle exception
                }
            });
        }
    }

    private void handleConnection(AsynchronousSocketChannel socket) throws IOException, InterruptedException {
        Connection connection = new Connection(socket, authenticationService);
        connections.add(connection);
        connection.handle();
    }

    public static class Connection {

        private AsynchronousSocketChannel channel;
        private ExternalAuthenticationService authenticationService;

        public Connection(AsynchronousSocketChannel channel, ExternalAuthenticationService authenticationService) {
            this.channel = channel;
            this.authenticationService = authenticationService;
        }

