// Define the DataPoint structure
typedef struct {
    time_t timestamp;
    int sensor_id;
    float temperature;
} DataPoint;

// Define the DataQueue structure for managing concurrent access
typedef struct {
    pthread_mutex_t mutex; // Mutex for synchronization
    pthread_cond_t cond; // Condition variable for notifications
    size_t size; // Current queue size
    DataPoint* points; // Array of DataPoints
} DataQueue;

// Initialize a new data queue with the given initial capacity
void data_queue_init(DataQueue* queue, size_t capacity) {
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    queue->size = 0;
    queue->points = (DataPoint*)malloc(capacity * sizeof(DataPoint));
}

// Enqueue a new data point into the queue
void data_queue_enqueue(DataQueue* queue, DataPoint* point) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->size == queue->points->capacity) {
        // Handle overflow by expanding the array
        size_t new_capacity = queue->points->capacity * 2;
        DataPoint* new_points = (DataPoint*)realloc(queue->points, new_capacity * sizeof(DataPoint));
        queue->points = new_points;
    }
    queue->points[queue->size] = *point;
    queue->size++;
    pthread_mutex_unlock(&queue->mutex);
    pthread_cond_signal(&queue->cond); // Notify waiting threads
}

// Dequeue the next available data point from the queue
DataPoint* data_queue_dequeue(DataQueue* queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->cond, &queue->mutex); // Wait for new data to arrive
    }
    DataPoint* point = &queue->points[0];
    memmove(queue->points, &queue->points[1], sizeof(DataPoint*) * (queue->size - 1));
    queue->size--;
    pthread_mutex_unlock(&queue->mutex);
    return point;
}

// Close the data queue
void data_queue_close(DataQueue* queue) {
    free(queue->points);
    pthread_cond_destroy(&queue->cond);
    pthread_mutex_destroy(&queue->mutex);
}
