    float temperature;
    float humidity;
    char metadata[256];
} DataPoint;

typedef enum {
    FILE_DESCRIPTOR,
    NETWORK_STREAM,
    IOT_DEVICE,
    CLOUD_SERVICE
} InputChannelType;

// Define the structure for the scalable collection of data points
typedef struct {
    DataPoint* data_points;
    uint32_t size;
    pthread_mutex_t mutex;
} DataCollection;

// Function to create a new data collection
DataCollection* create_data_collection(uint32_t initial_size) {
    DataCollection* data_collection = (DataCollection*)malloc(sizeof(DataCollection));
    data_collection->data_points = (DataPoint*)malloc(initial_size * sizeof(DataPoint));
    data_collection->size = 0;
    pthread_mutex_init(&data_collection->mutex, NULL);
    return data_collection;
}

// Function to add a new data point to the collection
void add_data_point(DataCollection* data_collection, DataPoint* data_point) {
    pthread_mutex_lock(&data_collection->mutex);
    if (data_collection->size >= data_collection->data_points->size) {
        // Resize the array if necessary
        data_collection->data_points = (DataPoint*)realloc(data_collection->data_points, (data_collection->size * 2 + 1) * sizeof(DataPoint));
    }
    memcpy(&data_collection->data_points[data_collection->size], data_point, sizeof(DataPoint));
    data_collection->size++;
    pthread_mutex_unlock(&data_collection->mutex);
}

// Function to get a data point by its index
DataPoint* get_data_point(DataCollection* data_collection, uint32_t index) {
    if (index >= data_collection->size) {
        return NULL;
    }
    pthread_mutex_lock(&data_collection->mutex);
    DataPoint* data_point = &data_collection->data_points[index];
    pthread_mutex_unlock(&data_collection->mutex);
    return data_point;
}

// Function to free the memory allocated for the data collection
void free_data_collection(DataCollection* data_collection) {
    pthread_mutex_lock(&data_collection->mutex);
    free(data_collection->data_points);
    pthread_mutex_unlock(&data_collection->mutex);
    free(data_collection);
}
