package com.subscriptionservice;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

// CRUD Operations
public class SubscriptionService {
    private List<Subscription> subscriptions = new ArrayList<>();

    public void createSubscription(Subscription subscription) {
        // Soft deletion
        if (subscription.getDeleted()) {
            subscriptions.removeIf(s -> s.getId().equals(subscription.getId()));
        } else {
            subscriptions.add(subscription);
        }
    }

    public Subscription readSubscription(String id) {
        return subscriptions.stream()
                .filter(s -> s.getId().equals(id))
                .findFirst()
                .orElse(null);
    }

    public void updateSubscription(Subscription subscription, String currentVersion) {
        // Optimistic concurrency control
        if (subscription.getVersion() == currentVersion) {
            readSubscription(subscription.getId()).ifPresent(s -> {
                s.setName(subscription.getName());
                s.setPlan(subscription.getPlan());
            });
        }
    }

    public void deleteSubscription(String id, String version) {
        // Soft deletion
        subscriptions.removeIf(s -> s.getId().equals(id));
    }

    public List<Subscription> getSubscriptions() {
        return subscriptions;
    }

    // Real-time Analytics
    public class SubscriptionAnalytics {
        public static Map<String, Long> getSubscriptionTrends(List<Subscription> subscriptions) {
            return subscriptions.stream()
                    .collect(Collectors.groupingBy(Subscription::getName, Collectors.counting()));
        }
    }
}

// OAuth Key Fetcher
public class OAuthKeyFetcher {
    private final String privateKeyLocation;
    private final String certificateLocation;

    public OAuthKeyFetcher(String privateKeyLocation, String certificateLocation) {
        this.privateKeyLocation = privateKeyLocation;
        this.certificateLocation = certificateLocation;
    }

    public PEMFile fetchOAuthKeys() throws IOException {
        // Fetch private key and certificate
        byte[] privateKeyBytes = Files.readAllBytes(Paths.get(privateKeyLocation));
        byte[] certificateBytes = Files.readAllBytes(Paths.get(certificateLocation));

        // Combine into a single PEM file
        PEMFile pemFile = new PEMFile();
        pemFile.addCertificate(certificateBytes);
        pemFile.addPrivateKey(privateKeyBytes);

        return pemFile;
    }
}

// PEM File Class
public class PEMFile {
    private List<byte[]> contents = new ArrayList<>();

    public void addCertificate(byte[] certificate) {
        contents.add(certificate);
    }

    public void addPrivateKey(byte[] privateKey) {
        contents.add(privateKey);
    }

    public byte[] getContents() {
        return Stream.of(contents.toArray()).collect(Collectors.joining());
    }
}
