#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Define the structure to hold NIC statistics
typedef struct {
    uint32_t packet_counts;
    uint64_t byte_counts;
    time_t timestamp;
} nic_stats;

// Define a linked list node for storing NIC statistics
typedef struct Node {
    nic_stats stats;
    struct Node* next;
} Node;

// Function to create a new Node with given NIC statistics
Node* create_node(nic_stats stats) {
    Node* node = (Node*) malloc(sizeof(Node));
    if (!node) return NULL;
    node->stats = stats;
    node->next = NULL;
    return node;
}

// Function to add a new Node at the end of the linked list
void add_node(Node** head, nic_stats stats) {
    Node* node = create_node(stats);
    if (*head == NULL) {
        *head = node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

// Function to print the NIC statistics in the linked list
void print_stats(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("Packet counts: %u, Byte counts: %llu, Timestamp: %ld\n", 
               current->stats.packet_counts, current->stats.byte_counts, current->stats.timestamp);
        current = current->next;
    }
}

// Function to find a specific NIC statistics in the linked list
Node* find_node(Node* head, uint32_t packet_counts) {
    Node* current = head;
    while (current != NULL) {
        if (current->stats.packet_counts == packet_counts) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Function to update the NIC statistics in the linked list
void update_stats(Node** head, uint32_t new_packet_counts, uint64_t new_byte_counts, time_t timestamp) {
    Node* node = find_node(*head, new_packet_counts);
    if (node != NULL) {
        node->stats.packet_counts = new_packet_counts;
        node->stats.byte_counts = new_byte_counts;
        node->stats.timestamp = timestamp;
    } else {
        add_node(head, (nic_stats){new_packet_counts, new_byte_counts, timestamp});
    }
}

int main() {
    // Create a linked list to store NIC statistics
    Node* head = NULL;

    // Add some sample NIC statistics
    add_node(&head, (nic_stats){1000, 1000000, time(NULL)});
    add_node(&head, (nic_stats){2000, 2000000, time(NULL)});
    add_node(&head, (nic_stats){3000, 3000000, time(NULL)});

    // Print the NIC statistics
    print_stats(head);

    // Update some NIC statistics
    update_stats(&head, 4000, 4000000, time(NULL));

    return 0;
}
```

This code provides a basic structure for managing dynamic Network Interface Control (NIC) statistics. It includes functions to create and add new nodes to a linked list of NIC statistics, as well as functions to print and update the statistics.']

