    return nics[nic_id];
}

// Function to initialize the library and set up NIC statistics.
void init_library() {
    int i;
    for (i = 0; i < MAX_NICS; i++) {
        nics[i].packet_count = 0;
        nics[i].byte_count = 0;
        nics[i].last_updated = time(NULL);
    }
}

// Function to handle network events.
void handle_network_events(int nic_id, int packet_count, int byte_count) {
    update_nic_stats(nic_id);

    // Update the packet and byte counts for this NIC.
    nics[nic_id].packet_count += packet_count;
    nics[nic_id].byte_count += byte_count;

    // Update the last updated timestamp.
    nics[nic_id].last_updated = time(NULL);
}

int main() {
    init_library();

    while (1) {
        // Handle network events for each NIC.
        int i;
        for (i = 0; i < MAX_NICS; i++) {
            handle_network_events(i, 10, 100);  // Simulate network events.
        }
    }

    return 0;
}
```

