from datetime import datetime
import logging

logging.basicConfig(level=logging.INFO)

class BillingService:
    def __init__(self):
        self.database = None  # Initialize database connection
        self.payment_gateways = {
            'primary': {'host': 'primary_gateway.com', 'port': 443},
            'secondary': {'host': 'secondary_gateway.com', 'port': 443}
        }
        self.transaction_queue = asyncio.Queue()

    async def process_transaction(self, transaction):
        try:
            # Validate transaction against business rules
            if not self.validate_transaction(transaction):
                raise ValueError("Invalid transaction")

            # Process payment gateway-specific logic
            payment_gateway = self.get_payment_gateway()
            response = await payment_gateway.make_payment(transaction)
            if response.status == 200:
                # Securely persist transaction details in database
                await self.database.write_transaction(transaction)
                return {"status": "success"}
            else:
                raise ValueError(f"Payment failed: {response.text}")

        except (ValueError, asyncio.TimeoutError) as e:
            logging.error(f"Transaction processing failed: {e}")
            # Retry with exponential backoff and circuit breaker pattern
            await self.retry_write_transaction(transaction)

    async def get_payment_gateway(self):
        try:
            return await self.payment_gateways['primary'].connect()
        except (ConnectionRefusedError, asyncio.TimeoutError):
            # Fallback to secondary payment gateway if primary fails
            return await self.payment_gateways['secondary'].connect()

    async def retry_write_transaction(self, transaction):
        delay = 0.5  # Initial backoff time
        max_attempts = 3

        for _ in range(max_attempts):
            try:
                await self.database.write_transaction(transaction)
                return
            except (asyncio.TimeoutError, ConnectionRefusedError) as e:
                logging.error(f"Transaction write failed: {e}")
                delay *= 2  # Exponential backoff
                await asyncio.sleep(delay)

        # Circuit breaker pattern: route transaction to secondary payment gateway if all attempts fail
        return await self.get_payment_gateway().make_payment(transaction)

    async def validate_transaction(self, transaction):
        # Complex business rules and fraud detection checks go here
        pass

    async def database_write_transaction(self, transaction):
        # Write-ahead log (WAL) mechanism for durable storage
        try:
            # Log transaction to disk
            await self.database.log_transaction(transaction)
            return True
        except (asyncio.TimeoutError, ConnectionRefusedError) as e:
            logging.error(f"Database write failed: {e}")
            return False

    async def main(self):
        while True:
            transaction = await self.transaction_queue.get()
            await self.process_transaction(transaction)

if __name__ == "__main__":
    service = BillingService()
    web.run_app(web.Application(), host='0.0.0.0', port=8080)
