#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // PDU structure fields
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure to hold the doubly-linked list nodes
typedef struct node_t {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct node_t *prev;
    struct node_t *next;
} node_t;

// Doubly-linked list structure
typedef struct dllist_t {
    node_t *head;
    node_t *tail;
    pthread_mutex_t lock;
} dllist_t;

// Initialize the doubly-linked list
dllist_t* init_dllist() {
    dllist_t* dll = (dllist_t*)malloc(sizeof(dllist_t));
    dll->head = NULL;
    dll->tail = NULL;
    pthread_mutex_init(&dll->lock, NULL);
    return dll;
}

// Insert a new node at the end of the doubly-linked list
void insert_node(dllist_t* dll, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    node_t* node = (node_t*)malloc(sizeof(node_t));
    node->pdu = pdu;
    node->prev = dll->tail;
    node->next = NULL;

    if (dll->head == NULL) {
        dll->head = node;
        dll->tail = node;
    } else {
        dll->tail->next = node;
        dll->tail = node;
    }
}

// Delete a node from the doubly-linked list
void delete_node(dllist_t* dll, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    node_t* node = dll->head;

    while (node != NULL && node->pdu != pdu) {
        node = node->next;
    }

    if (node == NULL) {
        printf("Node not found!\n");
        return;
    }

    if (node == dll->head) {
        dll->head = node->next;
    } else {
        node->prev->next = node->next;
    }

    if (node == dll->tail) {
        dll->tail = node->prev;
    } else {
        node->next->prev = node->prev;
    }

    free(node);
}

// Print the contents of the doubly-linked list
void print_dllist(dllist_t* dll) {
    node_t* node = dll->head;

    while (node != NULL) {
        printf("%p -> ", node);
        printf("%p\n", node->pdu);
        node = node->next;
    }
}

int main() {
    dllist_t* dll = init_dllist();

    NFAPI_CRC_INDICATION_PDU_T pdu1, pdu2, pdu3;

    insert_node(dll, &pdu1);
    insert_node(dll, &pdu2);
    insert_node(dll, &pdu3);

    print_dllist(dll);

    delete_node(dll, &pdu2);

    print_dllist(dll);

    return 0;
}
