import hashlib
import os
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend

class FileIntegrityVerifier:
    def __init__(self):
        self.md5_hashes = {}

    def compute_md5(self, file_path):
        md5_hash = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                md5_hash.update(chunk)
        return md5_hash.hexdigest()

    def generate_symmetric_key(self, md5_hash):
        salt = os.urandom(16)
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=100000,
            backend=default_backend()
        )
        key = kdf.derive(md5_hash.encode())
        return serialization.load_pem_publickey(key)

    def encrypt_metadata(self, file_path):
        symmetric_key = self.generate_symmetric_key(self.compute_md5(file_path))
        with open(file_path, 'rb') as f:
            metadata = {'filename': os.path.basename(file_path)}
            encrypted_metadata = symmetric_key.encrypt(metadata.encode())
            return encrypted_metadata

    def verify_integrity(self, file_path):
        md5_hash = self.compute_md5(file_path)
        if md5_hash in self.md5_hashes:
            if self.md5_hashes[md5_hash] == os.path.getsize(file_path):
                print(f"File {file_path} is intact")
            else:
                print(f"File {file_path} has been modified")
        else:
            self.md5_hashes[md5_hash] = os.path.getsize(file_path)
