// Java 11+
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

public class LogProcessor {
    private static final int LOG_BUFFER_SIZE = 1024 * 16; // 16 KB
    private static final String LOG_DIR = "logs";

    public static void processLog(String logEntry) throws IOException {
        MessageDigest md5 = getMessageDigest("MD5");
        MessageDigest sha256 = getMessageDigest("SHA-256");

        String[] parts = logEntry.split(",");
        Instant timestamp = Instant.parse(parts[0]);
        UUID uuid = UUID.fromString(parts[1]);

        byte[] data = (timestamp.toString() + "," + uuid.toString()).getBytes();
        byte[] md5Hash = md5.digest(data);
        byte[] sha256Hash = sha256.digest(data);

        String logEntryMetadata = timestamp.toString() + "," + uuid.toString() + "," + new String(md5Hash) + "," + new String(sha256Hash);
        Files.write(Paths.get(LOG_DIR, "log-" + timestamp.toEpochMilli() + ".txt"), logEntryMetadata.getBytes());
    }

    private static MessageDigest getMessageDigest(String algorithm) {
        try {
            return MessageDigest.getInstance(algorithm);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
}
