#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* add_slash(char* str, int size) {
    if (strlen(str) + 2 > size) {
        return NULL;
    }
    char* new_str = (char*)malloc((size_t)(size + 1));
    if (!new_str) {
        return NULL;
    }
    strcpy(new_str, str);
    strcat(new_str, "/");
    return new_str;
}

int main() {
    char* input_string = "Hello";
    int size = 10;
    char* output_string = add_slash(input_string, size);
    if (output_string) {
        printf("%s\n", output_string);
        free(output_string);
    }
    return 0;
}
