bool validateSensorDataRecord(const Json::Value& json) {
    if (!json.isObject()) return false;

    bool isValid = true;
    try {
        // Check for mandatory fields: temperature, humidity, pressure, and timestamp
        if (!json["temperature"].isNumeric() || !json["humidity"].isNumeric()
            || !json["pressure"].isNumeric() || !json["timestamp"].asString().size() == 0) {
            isValid = false;
        }

        // Check that timestamp is a valid ISO 8601 date-time string
        if (!isValidTimestamp(json["timestamp"].asString())) {
            isValid = false;
        }
    } catch (const Json::Exception& e) {
        std::cerr << "Error parsing JSON: " << e.what() << std::endl;
        isValid = false;
    }

    return isValid;
}

bool isValidTimestamp(const std::string& timestampStr) {
    // Implement ISO 8601 date-time string validation logic here
    // For demonstration purposes, assume the input is valid if it contains at least one digit
