    let sem = semaphore(10); // thread pool size

    loop {
        tokio::spawn(async move {
            if let Ok(mut response) = get("https://your-metadataservice.com/validate").await {
                if let Ok(data) = response.json::<Vec<metric_record>>::await {
                    for record in data {
