        loop {
            tokio::task::spawn_blocking(move || {
                if let Ok(mut response) = get("https://your-external-api.com/anomaly-detection").await {
                    if let Ok(data) = response.json::<Vec<anomaly_detection_result>>::await {
                        for result in data {
                            tx.send(result).await.unwrap();
                        }
                    }
                }
            });
        }

        // rate limit concurrent requests
        while let Some(mut msg) = rx.recv().await {
            sem.acquire().unwrap(); // block until slot is available
            if let Err(err) = process_metric(msg) {
                sem.release().unwrap();
                println!("Error processing metric: {}", err);
            }
        }
