using System;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

namespace PaymentGatewaySimulationService
{
    public class PaymentGatewaySimulationService : IRunnable
    {
        private readonly ILogger _logger;
        private readonly IConfiguration _config;
        private readonly ICurrencyConverter _currencyConverter;
        private readonly ITxnProcessor _txnProcessor;
        private readonly ITransactionSimulator _transactionSimulator;

        public PaymentGatewaySimulationService(ILogger<PaymentGatewaySimulationService> logger, 
                                               IConfiguration config, 
                                               ICurrencyConverter currencyConverter, 
                                               ITxnProcessor txnProcessor, 
                                               ITransactionSimulator transactionSimulator)
        {
            _logger = logger;
            _config = config;
            _currencyConverter = currencyConverter;
            _txnProcessor = txnProcessor;
            _transactionSimulator = transactionSimulator;
        }

        public async Task RunAsync()
        {
            // Initialize configuration
            await InitializeConfiguration();

            // Start transaction simulator
            _transactionSimulator.Start();

            while (true)
            {
                // Process transactions
                await ProcessTransactions();
            }
        }

        private async Task InitializeConfiguration()
        {
            // Load configuration from environment variables or file
            _config.Load();

            // Initialize currency conversion with dynamic rate updates
            _currencyConverter.Initialize(_config["CurrencyRateAPI"]);

            // Initialize transaction processor with retry logic and circuit breaker
            _txnProcessor.Initialize(_config["TxnRetryCount"], _config["TxnCircuitBreakerThreshold"]);
        }

        private async Task ProcessTransactions()
        {
            while (true)
            {
                // Get next transaction from simulator
                var transaction = await _transactionSimulator.GetNextTransaction();

                try
                {
                    // Convert currency if necessary
                    if (transaction.Currency != _config["DefaultCurrency"])
                    {
                        transaction.Amount = await _currencyConverter.Convert(transaction.Amount, 
                                                                                  transaction.Currency, 
                                                                                  _config["DefaultCurrency"]);
                    }

                    // Process transaction
                    await _txnProcessor.ProcessTransaction(transaction);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing transaction");
                }
            }
        }
    }
}
