public class RoleService {

    private Map<String, List<Role>> roleCache = new HashMap<>();
    private Map<String, IdP> idpCache = new HashMap<>();

    public void createRole(String userId, String roleId) {
        try (Connection conn = dataSource.getConnection()) {
            // Create role in database
            conn.createStatement().execute("INSERT INTO roles (user_id, role_id) VALUES (?, ?)", userId, roleId);
            // Update user's roles in external IdP
            for (IdP idp : getIdpsForUser(userId)) {
                idp.updateRole(userId, roleId);
            }
        } catch (Exception e) {
            log.error("Error creating role: ", e);
        }
    }

    public List<Role> getRolesForUser(String userId) {
        try (Connection conn = dataSource.getConnection()) {
            // Retrieve user's roles from database
            List<Role> roles = conn.createStatement().executeQuery("SELECT * FROM roles WHERE user_id = ?", userId).getResultSet();
            return roles;
        } catch (Exception e) {
            log.error("Error retrieving roles: ", e);
            return new ArrayList<>();
        }
    }

    public void updateRole(String userId, String oldRoleId, String newRoleId) {
        try (Connection conn = dataSource.getConnection()) {
            // Update role in database
            conn.createStatement().execute("UPDATE roles SET role_id = ? WHERE user_id = ? AND role_id = ?", userId, newRoleId, oldRoleId);
            // Update user's role in external IdP
            for (IdP idp : getIdpsForUser(userId)) {
                idp.updateRole(userId, newRoleId);
            }
        } catch (Exception e) {
            log.error("Error updating role: ", e);
        }
    }

    private List<IdP> getIdpsForUser(String userId) {
        // Retrieve IdPs for user from cache or database
        return idpCache.getOrDefault(userId, new ArrayList<>());
    }

    public void authenticate(String username, String password) {
        try (Connection conn = dataSource.getConnection()) {
            // Authenticate user with database
            User user = conn.createStatement().executeQuery("SELECT * FROM users WHERE username = ?", username).getResultSet();
            if (!user.getPassword().equals(password)) {
                throw new AuthenticationException("Invalid credentials");
            }
            // Retrieve IdPs for user and authenticate with each
            for (IdP idp : getIdpsForUser(user.getId())) {
                try {
                    idp.authenticate(username, password);
                } catch (AuthenticationException e) {
                    log.error("Error authenticating with {}: ", e.getMessage());
                }
            }
        } catch (Exception e) {
            log.error("Error authenticating: ", e);
            throw new AuthenticationException("Failed to authenticate");
        }
    }

    private static final Logger log = LoggerFactory.getLogger(RoleService.class);

    @NotthreadSafe
    public void start() {
        // Start caching and auditing services
        roleCacheService.start();
        auditLogger.start();
    }

    public void stop() {
        // Stop caching and auditing services
        roleCacheService.stop();
        auditLogger.stop();
    }
}

