// Dynamic Data Handling
class SensorBuffer {
public:
    explicit SensorBuffer(size_t initialCapacity) : buffer_(new std::queue<int>[initialCapacity]), capacity_(initialCapacity), load_(0.0f) {}

    void addData(int data) {
        if (buffer_[load_.toInt() % capacity_].full()) {
            // Handle partial failure by flagging for reprocessing
            std::cout << "Buffer full! Flagging for reprocessing." << std::endl;
            return;
        }
        buffer_[load_.toInt() % capacity_].push(data);
    }

    int getBufferData() {
        if (buffer_[load_.toInt() % capacity_].empty()) {
            // Handle data freshness and system resource usage
            load_.setToF((float)capacity_);
            return -1;  // or throw an exception
        }
        return buffer_[load_.toInt() % capacity_].front();
    }

private:
    std::queue<int>* buffer_;
    size_t capacity_;
    float load_;
};

// Storage Tiering
class StorageTier {
public:
    explicit StorageTier(size_t initialCapacity) : inMemoryStorage_(new std::queue<int>[initialCapacity]), diskStorage_(new std::queue<int>[initialCapacity]), currentStorage_("in-memory") {}

    void storeData(int data) {
        if (currentStorage_ == "in-memory") {
            inMemoryStorage_.push(data);
        } else {
            diskStorage_.push(data);
        }
    }

    int getBufferData() {
        if (currentStorage_ == "in-memory" && !inMemoryStorage_.empty()) {
            return inMemoryStorage_.front();
        } else if (currentStorage_ == "disk" && !diskStorage_.empty()) {
            return diskStorage_.front();
        }
        return -1;  // or throw an exception
    }

private:
    std::queue<int>* inMemoryStorage_;
    std::queue<int>* diskStorage_;
    std::string currentStorage_;
};

