#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>

#define LOGGING_SERVICE_PORT 8080
#define MAX_BUFFER_SIZE 1024
#define RETRY_ATTEMPTS 3
#define BACKOFF_FACTOR 2

typedef struct {
    json_object *message;
    int64_t timestamp;
} log_message;

void* handleLogConditionError(void* data) {
    // Initialize logging service socket and buffer pool
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket creation failed");
        return NULL;
    }

    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(LOGGING_SERVICE_PORT);
    inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr);

    int buffer_pool_size = 10;
    pthread_mutex_t *buffer_pool_lock = malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(buffer_pool_lock, NULL);
    log_message* buffer_pool = calloc(buffer_pool_size, sizeof(log_message));

    // Monitor condition and log error messages
    while (1) {
        if (condition_met()) {
            json_object *message = json_object_new_object();
            json_object_object_add(message, "timestamp", json_string_format("%ld", time(NULL)));
            json_object_object_add(message, "error_code", json_string("my_error_code"));
            json_object_object_add(message, "context_info", json_string("my_context_info"));

            log_message* buffer = NULL;
            pthread_mutex_lock(buffer_pool_lock);
            for (int i = 0; i < buffer_pool_size; i++) {
                if (buffer_pool[i].message == NULL) {
                    buffer = &buffer_pool[i];
                    break;
                }
            }
            if (buffer != NULL) {
                buffer->message = message;
                buffer->timestamp = time(NULL);
            } else {
                printf("Error: Buffer pool is full.\n");
            }
            pthread_mutex_unlock(buffer_pool_lock);

            // Send messages to logging service
            while (1) {
                int retry_attempts = 0;
                while (retry_attempts <= RETRY_ATTEMPTS) {
                    if (send_message(sock, buffer->message)) {
                        break;
                    } else {
                        retry_attempts++;
                        if (retry_attempts == RETRY_ATTEMPTS) {
                            printf("Error: Could not send message. Retrying in %d seconds...\n", (1 << retry_attempts) * BACKOFF_FACTOR);
                            sleep((1 << retry_attempts) * BACKOFF_FACTOR);
                        }
                    }
                }
            }
        }
    }

    // Clean up
    close(sock);
    free(buffer_pool_lock);
    free(buffer_pool);

    return NULL;
}

int send_message(int sock, json_object* message) {
    char buffer[MAX_BUFFER_SIZE];
    int bytes_sent = 0;

    json_object_to_json_string_ex(message, buffer, MAX_BUFFER_SIZE, JSON_INDENT_NONE);

    while (bytes_sent < strlen(buffer)) {
        int sent_bytes = send(sock, buffer + bytes_sent, strlen(buffer) - bytes_sent, 0);
        if (sent_bytes <= 0) {
            return 0;
        }
        bytes_sent += sent_bytes;
    }

    return 1;
}

int main() {
    // Initialize the logging condition monitoring thread
    pthread_t thread;
    pthread_create(&thread, NULL, handleLogConditionError, NULL);

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    return 0;
}
