#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <unordered_map>

class Transaction {
public:
    int id;
    double amount;
    std::string instrument;

    Transaction(int id, double amount, std::string instrument) : id(id), amount(amount), instrument(instrument) {}
};

class Database {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<Transaction> transactions;
    bool running = true;

public:
    void processTransactions() {
        while (running) {
            Transaction transaction;
            {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this] { return !transactions.empty(); });
                transaction = transactions.front();
                transactions.pop();
            }
            // Process the transaction
            std::cout << "Processing transaction: " << transaction.id << ", Amount: " << transaction.amount << ", Instrument: " << transaction.instrument << std::endl;
        }
    }

    void addTransaction(Transaction transaction) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            transactions.push(transaction);
            cv.notify_one();
        }
    }

    void stop() {
        running = false;
    }
};

class TradingSystem {
private:
    Database database;
    std::vector<std::thread> threads;

public:
    TradingSystem(int numThreads) {
        for (int i = 0; i < numThreads; i++) {
            threads.emplace_back([this, &database]() {
                database.processTransactions();
            });
        }
    }

    void addTransaction(Transaction transaction) {
        database.addTransaction(transaction);
    }

    void stop() {
        database.stop();
    }

    void joinThreads() {
        for (auto& thread : threads) {
            thread.join();
        }
    }
};

int main() {
    TradingSystem system(4);

    while (true) {
        Transaction transaction;
        // Read transactions from input
        // ...

        system.addTransaction(transaction);
    }

    return 0;
}
