async function initializeWebsite(directoryPath, siteName) {
  try {
    const config = await getWebConfig(directoryPath);
    if (!config) return null;

    const dnsSetupResult = await setupDns(config.dnsConfig);
    const sslSetupResult = await setupSsl(config.sslConfig);
    const appVersioningResult = await versionApp(config.appVersion);

    if (dnsSetupResult === false || sslSetupResult === false) {
      console.error(`Failed to set up DNS or SSL for site ${siteName}`);
    }

    if (!appVersioningResult) {
      console.error(`Failed to update application version for site ${siteName}`);
    } else {
      await startWebsite(directoryPath, siteName);
      console.log(`Site ${siteName} successfully added and started`);
    }
  } catch (error) {
    console.error(`Error initializing website: ${error.message}`);
    process.exit(1);
  }
}

async function getWebConfig(directoryPath) {
  try {
    const configBuffer = await fs.promises.readFile(`${directoryPath}/web.config`, 'utf8');
    return JSON.parse(configBuffer.toString());
  } catch (error) {
    console.error(`Failed to read web.config file: ${error.message}`);
    return null;
  }
}

async function setupDns(dnsConfig) {
  try {
    await dnsSetupApi(dnsConfig.host, dnsConfig.port);
    return true;
  } catch (error) {
    console.error(`Failed to set up DNS: ${error.message}`);
    return false;
  }
}

async function setupSsl(sslConfig) {
  try {
    await sslSetupApi(sslConfig.certificatePath, sslConfig.privateKeyPath);
    return true;
  } catch (error) {
    console.error(`Failed to set up SSL: ${error.message}`);
    return false;
  }
}

async function versionApp(appVersion) {
  try {
    await appVersioningApi(appVersion.major, appVersion.minor, appVersion.patch);
    return true;
  } catch (error) {
    console.error(`Failed to update application version: ${error.message}`);
    return false;
  }
}

async function startWebsite(directoryPath, siteName) {
  try {
    await startServer(directoryPath);
    console.log(`Site ${siteName} started successfully`);
  } catch (error) {
    console.error(`Error starting website: ${error.message}`);
  }
}
