// footer.js
import { WebSocket } from 'ws';
import { validateScriptSource } from './scriptValidator';
import { sanitizeHTML } from './htmlSanitizer';
import { cacheFooterContent } from './footerCache';

const FOOTER_ELEMENT_ID = 'footer-component';
const WEB_SOCKET_URL = 'wss://example.com/api/socket';
const SCRIPT_SOURCES = [
  'https://cdn.jsdelivr.net/npm/script1@latest/dist/script.min.js',
  'https://cdn.jsdelivr.net/npm/script2@latest/dist/script.min.js'
];

let footerElement;
let webSocket;

function initFooter() {
  if (!footerElement) {
    footerElement = document.getElementById(FOOTER_ELEMENT_ID);
  }

  // establish WebSocket connection
  webSocket = new WebSocket(WEB_SOCKET_URL);

  // initialize script sources
  SCRIPT_SOURCES.forEach((scriptSource) => {
    const scriptTag = document.createElement('script');
    scriptTag.src = scriptSource;
    scriptTag.crossOrigin = 'anonymous';
    document.body.appendChild(scriptTag);
  });

  // handle WebSocket messages
  webSocket.onmessage = (event) => {
    const { data } = event;
    const footerContent = JSON.parse(data);

    // validate and sanitize footer content
    const sanitizedFooterContent = sanitizeHTML(footerContent);

    // update footer component
    footerElement.innerHTML = sanitizedFooterContent;

    // cache updated footer content for future use
    cacheFooterContent(sanitizedFooterContent);
  };

  // handle WebSocket errors
  webSocket.onerror = (error) => {
    console.error('WebSocket error:', error);
  };

  // handle WebSocket close
  webSocket.onclose = () => {
    console.log('WebSocket connection closed');
  };
}

function updateFooterContent() {
  // get latest footer content from cache or re-fetch from API if necessary
  const cachedFooterContent = cacheFooterContent();
  if (cachedFooterContent) {
    return cachedFooterContent;
  }

  // re-fetch footer content from WebSocket API
  webSocket.send('GET /api/footer');

  // wait for updated footer content and re-render the component
  setTimeout(() => {
    updateFooterContent();
  }, 1000);
}

export { initFooter, updateFooterContent };
