const express = require('express');
const app = express();
const port = 3000;
const cors = require('cors');
app.use(cors());
const path = require('path');
const fs = require('fs');
const os = require('os');

// Load configuration file
const config = JSON.parse(fs.readFileSync(path.join(__dirname, 'config.json'), 'utf8'));

// Define task management functions
function submitTask(taskName) {
    // Check if task exists in directory
    const taskDir = path.join(__dirname, 'tasks');
    const taskPath = path.join(taskDir, `${taskName}.js`);
    if (!fs.existsSync(taskPath)) {
        console.error(`Task ${taskName} not found`);
        return;
    }

    // Execute task with Node.js child process
    const exec = require('child_process').execFile('node', [taskPath]);
    exec.stdout.on('data', (data) => {
        console.log(data.toString());
    });
    exec.stderr.on('data', (data) => {
        console.error(data.toString());
    });
}

function scheduleTask(taskName, delay) {
    setTimeout(() => submitTask(taskName), delay);
}

// Define API endpoints
app.get('/tasks', (req, res) => {
    const tasks = fs.readdirSync(taskDir).filter((file) => file.endsWith('.js'));
    res.json(tasks.map((task) => task.replace('.js', '')));
});

app.post('/tasks', (req, res) => {
    submitTask(req.body.taskName);
    res.send({ message: 'Task submitted successfully' });
});

app.get('/schedule', (req, res) => {
    scheduleTask(req.query.taskName, req.query.delay * 1000);
    res.send({ message: `Task ${req.query.taskName} scheduled for execution` });
});

// Start server
app.listen(port, () => {
    console.log(`Server started on port ${port}`);
});
```"]

