// 1. Data Analysis
class TimestampAnalysis {
public:
    std::vector<std::pair<long, long>> identifyDisjointTimestamps(const std::vector<long>& timestamps) {
        std::vector<std::pair<long, long>> disjointTimestamps;
        for (size_t i = 0; i < timestamps.size() - 1; ++i) {
            if (timestamps[i + 1] - timestamps[i] == 1) {
                disjointTimestamps.push_back({timestamps[i], timestamps[i + 1]});
            }
        }
        return disjointTimestamps;
    }
};

// 2. String Manipulation
class ForwardListManipulator {
public:
    void insertStringAfter(const std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
        auto it = list.cbegin();
        while (it != list.cend()) {
            if (*it == target) {
                list.insert_after(it, insertion);
                return;
            }
            ++it;
        }
        list.append(insertion);
    }
};

