from flask import Flask, jsonify, request
from flask_sqlalchemy import SQLAlchemy
from flask_caching import Cache

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "postgresql://user:password@host:port/dbname"
app.config["SQLALCHEMY_TRACK_MODIFICATIONS"] = False
db = SQLAlchemy(app)

cache = Cache(app, config={"CACHE_TYPE": "SimpleCache"})

class Employee(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    city = db.Column(db.String(50), nullable=False)
    address = db.Column(db.String(200), nullable=False)
    project_details = db.Column(db.Text, nullable=False)
    supervisor_id = db.Column(db.Integer, db.ForeignKey("employee.id"))

@app.route("/employees", methods=["GET"])
def get_employees():
    supervisor_id = request.args.get("supervisor_id")
    if not supervisor_id:
        return jsonify({"error": "Supervisor ID is required"}), 400

    employees = Employee.query.filter_by(supervisor_id=supervisor_id).all()
    result = [employee.to_dict() for employee in employees]
    return jsonify(result)

@app.route("/employees/<int:employee_id>", methods=["GET"])
def get_employee(employee_id):
    employee = Employee.query.get(employee_id)
    if not employee:
        return jsonify({"error": "Employee not found"}), 404

    return jsonify(employee.to_dict())

@cache.cached(timeout=300, key_prefix="get_employees_")
def get_employees_supervisor(supervisor_id):
    employees = Employee.query.filter_by(supervisor_id=supervisor_id).all()
    result = [employee.to_dict() for employee in employees]
    return jsonify(result)

@app.route("/employees/supervisor/<int:supervisor_id>", methods=["GET"])
def get_employees_supervisor_id(supervisor_id):
    return get_employees_supervisor(supervisor_id)

if __name__ == "__main__":
    app.run(debug=True)
