pub struct DisjointSetAnalyzer {
    sets: Vec<HashSet<i32>>,
}

impl DisjointSetAnalyzer {
    pub fn new() -> Self {
        Self { sets: vec![] }
    }

    pub fn add_array(&mut self, arr: &[i32]) {
        let mut set = HashSet::new();
        for &x in arr {
            set.insert(x);
        }
        self.sets.push(set);
    }

    pub fn find(&self, x: i32) -> Option<&HashSet<i32>> {
        self.sets.iter().find(|set| set.contains(&x))
