    enum class AttackType { ATTACK_A, ATTACK_B, ATTACK_C };

    CharacterAttack() : cooldown_(10) {}

    void set_cooldown(int seconds) {
        if (seconds >= 1)
            cooldown_ = seconds;
    }

    void select_attack() {
        std::this_thread::sleep_for(std::chrono::seconds(cooldown_));
        int random_attack = (rand() % 3);
        switch (random_attack) {
            case 0:
                attack_type_ = AttackType::ATTACK_A;
                break;
            case 1:
                attack_type_ = AttackType::ATTACK_B;
                break;
            case 2:
                attack_type_ = AttackType::ATTACK_C;
                break;
        }
    }

private:
    int cooldown_;
    AttackType attack_type_;
};

int main() {
    CharacterAttack character;

    // Configure cooldown period via environment variable
    if (std::getenv("COOLDOWN_SECONDS")) {
        int seconds = std::stoi(std::getenv("COOLDOWN_SECONDS"));
        character.set_cooldown(seconds);
    }

    while (true) {
        character.select_attack();
        std::cout << "Selected attack: ";
        switch (character.attack_type_) {
            case CharacterAttack::AttackType::ATTACK_A:
                std::cout << "Attack A" << std::endl;
                break;
            case CharacterAttack::AttackType::ATTACK_B:
                std::cout << "Attack B" << std::endl;
                break;
            case CharacterAttack::AttackType::ATTACK_C:
                std::cout << "Attack C" << std::endl;
                break;
        }
    }

    return 0;
}
