        var filter = Builders<TenantDocument>.Filter.Eq("_id", id);
        var result = await _database.GetCollection<TenantDocument>("tenants").FindAsync(filter).FirstOrDefault();
        if (result == null) return NotFound();
        return result;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateTenant(string id, [FromBody]TenantModel tenant)
    {
        var filter = Builders<TenantDocument>.Filter.Eq("_id", id);
        await _database.GetCollection<TenantDocument>("tenants").UpdateOneAsync(filter, Builders<TenantDocument>.Update.Set("name", tenant.Name));
        return Ok();
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteTenant(string id)
    {
        var filter = Builders<TenantDocument>.Filter.Eq("_id", id);
        await _database.GetCollection<TenantDocument>("tenants").DeleteOneAsync(filter);
