// Function to execute a command using Runtime.getRuntime().exec()
void executeCommand(const std::string& command) {
    auto process = ::Runtime.getRuntime().exec(command, nullptr, "/path/to/directory");
    auto outputBufferedReader = std::make_unique<BufferedReader>(process.getInputStream());
    auto errorBufferedReader = std::make_unique<BufferedReader>(process.getErrorStream());

    // Read the output and error streams
    std::string line;
    while (std::getline(*outputBufferedReader, line)) {
        std::cout << "Output: " << line << std::endl;
    }
    while (std::getline(*errorBufferedReader, line)) {
        std::cerr << "Error: " << line << std::endl;
    }

    // Close the streams
    process.getInputStream().close();
    process.getErrorStream().close();

    if (!process.waitFor()) {
        std::cerr << "Process did not terminate normally" << std::endl;
    }
}

int main() {
    executeCommand("ls /path/to/directory");
    return 0;
}
