use reqwest::blocking::{get, Client};
use rand::Rng;
use std::time::Duration;

struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: String,
    rnti: u16,
    crc_indication_rel8_tag: String,
    crcflag: bool,
}

async fn generate_crc_indications(
    num_pds: usize,
    target_url: &str,
    timeout: u64,
    enable_validation: bool,
) -> Result<Vec<NFAPI_CRC_INDICATION_PDU_T>, String> {
    let mut rng = rand::thread_rng();
    let client = reqwest::blocking::ClientBuilder::new()
        .timeout(Duration::from_millis(timeout as u128))
        .build()?;

    let mut pds: Vec<NFAPI_CRC_INDICATION_PDU_T> = vec![];

    for _ in 0..num_pds {
        let rx_ue_information_tag = format!("RX UE INFO {}", rng.gen::<u32>());
        let rnti = rng.gen::<u16>();
        let crc_indication_rel8_tag = format!("CRC INDICATION REL8 TAG {}", rng.gen::<u32>());
        let crcflag = rng.gen::<f64>() < 0.5;

        match get(target_url).await {
            Ok(res) => {
                if enable_validation && !res.status().is_success() {
                    return Err("Certificate validation failed".to_string());
                }
                pds.push(NFAPI_CRC_INDICATION_PDU_T {
                    rx_ue_information_tag,
                    rnti,
                    crc_indication_rel8_tag,
                    crcflag: crcflag as bool,
                });
            }
            Err(e) => {
                return Err(format!("Failed to get data from {}: {}", target_url, e));
            }
        }
    }

    Ok(pds)
}

fn main() {
    // Example usage
    let result = generate_crc_indications(10, "https://example.com/api", 1000, true);
    match result {
        Ok(pds) => println!("Generated {} PDS: {:?}", pds.len(), pds),
        Err(err) => eprintln!("{}", err),
    }
}
