using Newtonsoft.Json;

namespace MarketDataAggregator
{
    public class MarketDataAggregator
    {
        private readonly ILogger _logger;
        private readonly Dictionary<string, IDataSource> _dataSources = new();
        private readonly MemoryPool<AggregatedMetric> _metricPool;

        public MarketDataAggregator(ILogger logger)
        {
            _logger = logger;
            _metricPool = new MemoryPool<AggregatedMetric>(1000);
        }

        public void RegisterDataSource(string sourceId, IDataSource dataSource)
        {
            _dataSources[sourceId] = dataSource;
        }

        public async Task ComputeMetricsAsync(List<string> aggregationFunctions, CancellationToken cancellationToken)
        {
            foreach (var function in aggregationFunctions)
            {
                switch (function)
                {
                    case "moving_average":
                        await ProcessMovingAverageAsync(cancellationToken);
                        break;
                    case "percentile":
                        await ProcessPercentileAsync(cancellationToken);
                        break;
                    // Add more functions as needed
                    default:
                        _logger.LogError("Unsupported aggregation function: {0}", function);
                        return;
                }
            }
        }

        private async Task ProcessMovingAverageAsync(CancellationToken cancellationToken)
        {
            foreach (var dataSource in _dataSources.Values)
            {
                try
                {
                    var data = await dataSource.GetMarketDataAsync(cancellationToken);
                    if (!data.Any())
                    {
                        continue;
                    }

                    // Perform moving average computation and store the result in the metric pool.
                    AggregatedMetric metric = null;
                    foreach (var point in data)
                    {
                        metric = _metricPool.Get();
                        metric.Value = point.Average(x => x.Close);
                        await _metricPool.Enqueue(metric, cancellationToken);
                    }
                }
                catch (Exception ex)
                {
                    // Handle error and log the failure.
                    _logger.LogError(ex, "Error processing moving average for {0}", dataSource.Id);
                }
            }
        }

        private async Task ProcessPercentileAsync(CancellationToken cancellationToken)
        {
            foreach (var dataSource in _dataSources.Values)
            {
                try
                {
                    var data = await dataSource.GetMarketDataAsync(cancellationToken);
                    if (!data.Any())
                    {
                        continue;
                    }

                    // Perform percentile computation and store the result in the metric pool.
                    AggregatedMetric metric = null;
                    foreach (var point in data)
                    {
                        metric = _metricPool.Get();
                        metric.Value = point.Percentile(0.5);
                        await _metricPool.Enqueue(metric, cancellationToken);
                    }
                }
                catch (Exception ex)
                {
                    // Handle error and log the failure.
                    _logger.LogError(ex, "Error processing percentile for {0}", dataSource.Id);
                }
            }
        }

        public void StartMonitoring()
        {
            Task.Run(async () =>
            {
                while (true)
                {
                    try
                    {
                        var metrics = await _metricPool.DequeueAll();
                        foreach (var metric in metrics)
                        {
                            // Log and send the aggregated metric to the trading platform.
                            _logger.LogInformation("Sent metric: {0}", JsonConvert.SerializeObject(metric));
                        }
                    }
                    catch (Exception ex)
                    {
                        // Handle error and log the failure.
                        _logger.LogError(ex, "Error processing and sending metrics");
                    }

                    await Task.Delay(1000); // Monitor every 1 second
                }
            });
        }
    }

    public interface IDataSource
    {
        Task<List<MarketDataPoint>> GetMarketDataAsync(CancellationToken cancellationToken);
    }

