    DynamicEventLogger(int priorityLevel, const std::vector<ResourceManager*>& resourceManagers)
        : priorityLevel_(priorityLevel), resourceManagers_(resourceManagers) {}

    void initialize() {
        // Check dependencies and trigger error callback on failure
        for (auto& rm : resourceManagers_) {
            if (!rm->checkDependency()) {
                // Trigger error callback and halt operation until resolved
                std::cerr << "Initialization failed: " << rm->getErrorMessage() << std::endl;
                return;
            }
        }
