// Define a struct to represent log entry
typedef struct {
    int num_fields;
    double *fields;
} LogEntry;

// Define a struct to hold log processing state
typedef struct {
    FILE *file; // File pointer for current file being processed
    pthread_mutex_t lock; // Lock for thread safety
    int thread_id; // Unique ID for each thread
    double *averages; // Rolling averages of last 5 numerical fields
} ProcessingState;

// Function to parse log entry and compute rolling averages
void process_log_entry(LogEntry* entry, ProcessingState* state) {
    // Calculate averages and update state
    for (int i = 0; i < entry->num_fields; i++) {
        if (entry->fields[i] != -1.0 && isnumeric(entry->fields[i])) { // Check if field is numerical
            state->averages[i % 5] += entry->fields[i];
        }
    }
}

// Function to handle file processing and average calculations
void* process_file(void* arg) {
    ProcessingState* state = (ProcessingState*)arg;

    while (state->file != NULL) {
        LogEntry entry;
        fscanf(state->file, "%d %lf %lf", &entry.num_fields, &entry.fields[0], &entry.fields[1]);

        process_log_entry(&entry, state);

        // Append average to log line and output
        fseek(state->file, -5 * sizeof(double), SEEK_CUR);
        fprintf(stdout, "[Average: %.2f] ", (state->averages[4]));
        fwrite(entry.fields, 1, entry.num_fields * sizeof(double), stdout);
        putc('\n', stdout);
    }

    return NULL;
}

// Function to start file processing in separate threads
void start_processing(char* files[], int num_files) {
    pthread_t threads[num_files];
    ProcessingState state[num_files];

    for (int i = 0; i < num_files; i++) {
        state[i].file = fopen(files[i], "r");
        state[i].averages = malloc(5 * sizeof(double));
        pthread_create(&threads[i], NULL, process_file, &state[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
        free(state[i].averages);
        fclose(state[i].file);
    }
}

