use reqwest;
use serde_json::json;
use std::{
    collections::{HashMap, VecDeque},
    error::Error,
    sync::{Arc, Mutex},
};

struct NetworkTrafficStat {
    // Define your stat fields here
}

async fn fetch_and_process_network_traffic(
    token: &str,
    url: &str,
    ssl_verify: bool,
    timeout: u64,
) -> Result<(Vec<NetworkTrafficStat>, u64), Box<dyn Error>> {
    let mut retry_attempts = 0;
    let max_retries = 5;
    let backoff_duration = 100; // in milliseconds

    loop {
        match reqwest::get(url)
            .bearer_auth(token)
            .timeout(std::time::Duration::from_millis(timeout))
            .verify_ssl(ssl_verify)
            .send()
            .await
        {
            Ok(response) => {
                let json_response = response.json::<HashMap<String, NetworkTrafficStat>>().await?;
                let mut stats: Vec<NetworkTrafficStat> = json_response.values().cloned().collect();
                // Process the stats...
                let total_entries = stats.len() as u64;
                return Ok((stats, total_entries));
            }
            Err(err) => {
                match err.downcast_ref::<reqwest::Error>() {
                    Some(req_err) if req_err.is_timeout() || req_err.is_connection_error() => {
                        // Handle connection or timeout errors
                        retry_attempts += 1;
                        if retry_attempts > max_retries {
                            return Err(format!("Max retries exceeded: {}", err).into());
                        }
                        std::thread::sleep(std::time::Duration::from_millis(backoff_duration));
                    }
                    Some(req_err) => {
                        // Handle other errors
                        return Err(err.into());
                    }
                    None => {
                        // Handle other errors
                        return Err(err.into());
                    }
                }
            }
        }
    }
}
