nic_stats* get_nic_stats(nic_manager* manager, int interface_id) {
    pthread_mutex_lock(&manager->lock);
    nic_stats* stats = &manager->stats[interface_id];
    pthread_mutex_unlock(&manager->lock);
    return stats;
}

// Function to update NIC statistics for a specific interface
void update_nic_stats(nic_manager* manager, int interface_id, uint64_t packet_counts, uint64_t byte_counts, int timestamp) {
    pthread_mutex_lock(&manager->lock);
    nic_stats* stats = &manager->stats[interface_id];
    stats->packet_counts += packet_counts;
    stats->byte_counts += byte_counts;
    stats->timestamp = timestamp;
    pthread_mutex_unlock(&manager->lock);
}

