// SessionState struct representing active user sessions
typedef struct {
    int session_id;
    char* username;
    // ... other session attributes ...
} SessionState;

// Dynamic pool of SessionState structs
typedef struct {
    int size;
    SessionState** sessions;
    pthread_mutex_t lock; // Lock for thread-safe operations
} SessionPool;

// Function to create a new SessionPool instance
SessionPool* create_session_pool(int initial_size) {
    SessionPool* pool = (SessionPool*)malloc(sizeof(SessionPool));
    pool->size = initial_size;
    pool->sessions = (SessionState**)malloc(pool->size * sizeof(SessionState*));
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Function to add a new session to the pool
void add_session(SessionPool* pool, int session_id, char* username) {
    // ... data validation and error handling ...
    pthread_mutex_lock(&pool->lock);
    SessionState* new_session = (SessionState*)malloc(sizeof(SessionState));
    new_session->session_id = session_id;
    new_session->username = strdup(username);
    // ... other session attributes ...
    pool->sessions[pool->size++] = new_session;
    pthread_mutex_unlock(&pool->lock);
}

// Function to update an existing session
void update_session(SessionPool* pool, int session_id, char* username) {
    // ... data validation and error handling ...
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->size; i++) {
        if (pool->sessions[i]->session_id == session_id) {
            free(pool->sessions[i]->username);
            pool->sessions[i]->username = strdup(username);
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

// Function to retrieve a session by ID
SessionState* get_session(SessionPool* pool, int session_id) {
    // ... data validation and error handling ...
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->size; i++) {
        if (pool->sessions[i]->session_id == session_id) {
            return pool->sessions[i];
        }
