    // ... data validation and error handling ...
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; i++) {
        if (cache->cache[i]->session_id == session->session_id) {
            free(cache->cache[i]->username);
            cache->cache[i]->username = strdup(session->username);
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

// Function to get a session from the cache
SessionState* get_from_cache(Cache* cache, int session_id) {
    // ... data validation and error handling ...
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; i++) {
        if (cache->cache[i]->session_id == session_id) {
            return cache->cache[i];
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

// Function to calculate average bandwidth usage
float calculate_bandwidth(Cache* cache, int time_window) {
    // ... algorithm for calculating and reporting average bandwidth ...
    float total_bandwidth = 0.0f;
    int session_count = 0;
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; i++) {
        SessionState* session = cache->cache[i];
        // ... calculate bandwidth usage based on session attributes ...
        total_bandwidth += bandwidth_usage(session);
        session_count++;
    }
    pthread_mutex_unlock(&cache->lock);
    return total_bandwidth / (float)session_count;
}

