['```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <condition_variable>

class SensorReading {
public:
    std::string sensorId;
    int value;

    SensorReading(const std::string& id, int val) : sensorId(id), value(val) {}
};

class SensorManager {
private:
    std::vector<SensorReading> readings;
    std::mutex mtx;
    std::condition_variable cv;
    bool stopped = false;

public:
    void addReading(SensorReading reading) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            readings.push_back(reading);
        }
        cv.notify_one();
    }

    void start() {
        thread t([this] {
            while (!stopped) {
                {
                    std::unique_lock<std::mutex> lock(mtx);
                    if (readings.empty()) {
                        cv.wait(lock, [this] { return !readings.empty(); });
                    }
                }
                // process readings
            }
        });
    }

    void stop() {
        stopped = true;
    }
};

int main() {
    SensorManager manager;

    std::thread t1([&manager] {
        for (int i = 0; i < 10; ++i) {
            manager.addReading(SensorReading("Sensor " + std::to_string(i), i));
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    });

    std::thread t2([&manager] {
        manager.start();
    });

    std::cout << "Press enter to stop.\n";
    std::cin.get();

    manager.stop();

    return 0;
}
