#include <pthread.h>
#include <semaphore.h>

// Define constants for the library
#define M 10 // Maximum number of interfaces
#define N 20 // Maximum number of concurrent threads

// Structure to represent an interface's statistics
typedef struct {
    uint64_t packets;
    uint64_t bytes;
    time_t last_updated;
} nic_stats_t;

// Structure to represent the cache
typedef struct {
    nic_stats_t *stats;
    sem_t lock;
} cache_t;

// Function to initialize the cache
void cache_init(cache_t *cache, int size) {
    // Initialize the statistics array with zeros
    cache->stats = (nic_stats_t *)calloc(size, sizeof(nic_stats_t));
    // Initialize the lock semaphore
    sem_init(&cache->lock, 0, 1);
}

// Function to update the cache with new statistics
void cache_update(cache_t *cache, int interface_id, nic_stats_t *stats) {
    // Lock the cache to prevent concurrent access
    sem_wait(&cache->lock);
    // Update the statistics for the specified interface
    cache->stats[interface_id] = *stats;
    // Unlock the cache
    sem_post(&cache->lock);
}

// Function to get the cached statistics for an interface
nic_stats_t *cache_get(cache_t *cache, int interface_id) {
    // Lock the cache to prevent concurrent access
    sem_wait(&cache->lock);
    // Return a copy of the cached statistics
    nic_stats_t *stats = (nic_stats_t *)malloc(sizeof(nic_stats_t));
    *stats = cache->stats[interface_id];
    free(cache->stats); // Release the original cache
    sem_post(&cache->lock);
    return stats;
}

// Function to initialize the NIC statistics
void nic_init(nic_stats_t **stats, int size) {
    for (int i = 0; i < size; i++) {
        (*stats)[i].packets = 0;
        (*stats)[i].bytes = 0;
        (*stats)[i].last_updated = time(NULL);
    }
}

// Function to update the NIC statistics
void nic_update(nic_stats_t *stats, int interface_id, uint64_t packets, uint64_t bytes) {
    stats[interface_id].packets += packets;
    stats[interface_id].bytes += bytes;
    stats[interface_id].last_updated = time(NULL);
}

// Function to get the NIC statistics
nic_stats_t *get_nic_stats(nic_stats_t **stats, int interface_id) {
    return &(*stats)[interface_id];
}

// Function to append a slash to a string if it doesn't exceed the size limit
char *append_slash(char *str, int size_limit) {
    if (strlen(str) + 1 <= size_limit) {
        char *new_str = (char *)malloc((size_limit + 2) * sizeof(char));
        strcpy(new_str, str);
        new_str[size_limit] = '/';
        new_str[size_limit + 1] = '\0';
        free(str);
        return new_str;
    }
    return str;
}

// Define the utility function
char *get_utility_function(char *str, int size_limit) {
    if (strlen(str) <= size_limit) {
        char *new_str = append_slash(str, size_limit);
        return new_str;
    } else {
        return str;
    }
}
