// Import required libraries
const { GraphQLSchema } = require('@graphql-tools/schema');
const { makeExecutableSchema } = require('@graphql-tools/schema');
const { ApolloServer } = require('apollo-server-express');
const express = require('express');
const app = express();
const cors = require('cors');

// Define the GraphQL schema
const typeDefs = `
  type Query {
    nodes: [Node!]!
    edges: [Edge!]!
  }
  type Node {
    id: ID!
    labels: [String!]!
    properties: Properties!
  }
  type Edge {
    id: ID!
    from: ID!
    to: ID!
    label: String!
    properties: Properties!
  }
  type Properties {
    key: String!
    value: String!
  }
`;

// Define the resolvers
const resolvers = {
  Query: {
    nodes: () => [...nodes],
    edges: () => [...edges]
  },
  Node: {
    id: node => node.id,
    labels: node => node.labels,
    properties: node => node.properties
  },
  Edge: {
    id: edge => edge.id,
    from: edge => edge.from,
    to: edge => edge.to,
    label: edge => edge.label,
    properties: edge => edge.properties
  }
};

// Initialize the Apollo Server
const server = new ApolloServer({
  typeDefs,
  resolvers,
});

// Start the server
server.listen().then(({ url }) => {
  console.log(`GraphQL API server listening on ${url}`);
});
