// Dynamic Resource Allocation and Performance Tuning
class BufferManager {
public:
    BufferManager(size_t initialBufferSize) : buffer_(initialBufferSize), used_(0) {}

    void addData(size_t dataSize) {
        while (buffer_.size() * 2 < dataSize + used_) {
            resizeBuffer();
        }
        used_ += dataSize;
    }

    void removeData(size_t dataSize) {
        used_ -= dataSize;
        if (used_ < buffer_.size()) {
            shrinkBuffer();
        }
    }

private:
    std::vector<char> buffer_;
    size_t used_;

    void resizeBuffer() {
        size_t newSize = buffer_.size() * 2;
        buffer_.resize(newSize);
    }

    void shrinkBuffer() {
        size_t newSize = buffer_.size() / 2;
        buffer_.resize(newSize);
    }
};

// Real-Time Data Pipelines and Network Resilience
class Pipeline {
public:
    Pipeline(size_t bufferSize) : buffer_(bufferSize), retryCount_(0) {}

