        return false; // invalid JSON format
    }

    if (!jsonData.isObject()) {
        return false; // not an object
    }

    for (const auto& field : {"temperature", "humidity", "pressure", "timestamp"}) {
        if (!jsonData[field].isNumeric()) {
            return false; // invalid value type
        }
    }

    return true;
}

