class SessionManager {
public:
    SessionManager(std::shared_ptr<IdentityAPI> identityApi)
        : identityApi_(identityApi) {}

    void startSession(const std::string& userId, const std::string& token) {
        // Check if the user is authenticated
        if (!identityApi_->verifyToken(token)) {
            throw std::runtime_error("Invalid authentication token");
        }

        // Start a new session and store it in memory
        auto sessionId = generateSessionId();
        sessions_.insert({sessionId, {userId, token, 0}});
    }

    void updateSession(const std::string& userId, const std::string& token) {
        for (auto& session : sessions_) {
            if (session.first == userId && session.second.token == token) {
                session.second.lastActivity = std::chrono::high_resolution_clock::now().time_since_epoch() / 1000;
                return;
            }
        }
    }

    void destroySession(const std::string& userId, const std::string& token) {
        for (auto it = sessions_.begin(); it != sessions_.end();) {
            if (it->first == userId && it->second.token == token) {
                it = sessions_.erase(it);
                return;
            }
            ++it;
        }
    }

private:
    std::shared_ptr<IdentityAPI> identityApi_;
    std::map<std::string, SessionData> sessions_;

    std::string generateSessionId() {
        // Generate a unique session ID
