// Define constants for domain extensions
#define EXT_123 "EXT123"
#define EXT_456 "EXT456"
#define EXT_789 "EXT789"

// Function to process hostnames
void process_hostname(char* hostname) {
    // Check hostname length
    int len = strlen(hostname);

    // Replace domain extension with timestamp if necessary
    if (len > 8) {
        char timestamp[20];
        time_t now = time(NULL);
        struct tm *info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", info);
        strcpy(hostname + len - 4, EXT_123);
        strcat(hostname, "@");
        strcat(hostname, timestamp);
    }

    // Use random UUID if hostname is exactly 8 characters
    else if (len == 8) {
        uuid_t myuuid;
        uuid_generate(myuuid);
        char uuid_str[37];
        uuid_unparse(myuuid, uuid_str);
        strcpy(hostname + len - 4, EXT_456);
        strcat(hostname, "@");
        strcat(hostname, uuid_str);
    }

    // Append process ID if hostname has fewer than 8 characters
    else {
        int pid = getpid();
        char pid_str[6];
        sprintf(pid_str, "%d", pid);
        strcpy(hostname + len, EXT_789);
        strcat(hostname, "@");
        strcat(hostname, pid_str);
    }
}

