using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using StackExchange.Redis;

namespace SaaSPlatform.AuthService.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class AuthenticationsController : ControllerBase
    {
        private readonly RedisConnection _redisConnection;
        private readonly IAuthorizationService _authorizationService;
        private readonly IMFAService _mfaService;

        public AuthenticationsController(RedisConnection redisConnection, IAuthorizationService authorizationService, IMFAService mfaService)
        {
            _redisConnection = redisConnection;
            _authorizationService = authorizationService;
            _mfaService = mfaService;
        }

        [HttpPost("login")]
        public async Task<IActionResult> Login([FromBody]LoginRequest request)
        {
            // Authenticate user credentials
            var authenticationResult = await _authorizationService.AuthenticateAsync(request.Username, request.Password);

            if (!authenticationResult.Succeeded)
            {
                return BadRequest(new { error = "Invalid username or password" });
            }

            // Perform MFA if required
            var mfaResult = await _mfaService.PerformMFAAsync(authenticationResult.Principal);

            if (!mfaResult.Succeeded)
            {
                return BadRequest(new { error = "MFA failed" });
            }

            // Generate authentication token and store in Redis
            var token = GenerateToken(request.Username);
            await _redisConnection.ExecuteAsync($"SET token:{request.Username} {token}");

            return Ok(new { token, expirationTime = DateTime.UtcNow.AddMinutes(30) });
        }

        [HttpGet("logout")]
        public async Task<IActionResult> Logout([FromQuery]string username)
        {
            // Remove authentication token from Redis
            await _redisConnection.ExecuteAsync($"DEL token:{username}");
            return Ok();
        }

        [HttpGet("mfa/enroll/{provider}")]
        public async Task<IActionResult> EnrollMFA([RouteValue]string provider, [FromQuery]string username)
        {
            // Handle MFA enrollment flow
            var mfaEnrollmentResult = await _mfaService.EnrollAsync(username, provider);

            if (!mfaEnrollmentResult.Succeeded)
            {
                return BadRequest(new { error = "MFA enrollment failed" });
            }

            return Ok();
        }
    }
}
