void add_nic_interface(char* name) {
    // Allocate memory for the new interface struct
    nic_interface_t* new_interface = (nic_interface_t*) malloc(sizeof(nic_interface_t));
    strcpy(new_interface->name, name);
    new_interface->stats.bytes_sent = 0;
    new_interface->stats.packets_sent = 0;
    new_interface->stats.errors_sent = 0;

    // Initialize the lock for this interface
    pthread_mutex_init(&new_interface->lock, NULL);

    // Add the new interface to the array
    nic_interfaces = (nic_interface_t*) realloc(nic_interfaces, (num_interfaces + 1) * sizeof(nic_interface_t));
    nic_interfaces[num_interfaces++] = *new_interface;
}

// Function to update NIC statistics for a given interface
void update_nic_stats(char* name, int bytes_sent, int packets_sent, int errors_sent) {
    // Find the interface with the matching name
    for (int i = 0; i < num_interfaces; i++) {
        if (strcmp(nic_interfaces[i].name, name) == 0) {
            // Lock the interface to prevent concurrent access
            pthread_mutex_lock(&nic_interfaces[i]->lock);

            // Update the statistics
            nic_interfaces[i]->stats.bytes_sent += bytes_sent;
            nic_interfaces[i]->stats.packets_sent += packets_sent;
            nic_interfaces[i]->stats.errors_sent += errors_sent;

