        while (true)
        {
            try
            {
                // Consume events from Event Hubs
                var events = await _eventHubConsumerClient.ReceiveEventsAsync();

                foreach (var eventModel in events)
                {
                    try
                    {
                        // Transform and process data
                        var transformedData = _dataTransformerPipeline.Transform(eventModel);

                        // Send to messaging queue
                        await _messagingQueueClient.SendAsync(transformedData);
                    }
                    catch (Exception ex)
                    {
                        // Handle exceptions and log errors
                        _logger.LogError(ex, "Error processing event");
                    }
                }
            }
            catch (Exception ex)
            {
                // Handle exceptions and log errors
                _logger.LogError(ex, "Error consuming events");
            }

            await Task.Delay(100);
        }
    }

    public async Task ProcessMessagingQueue()
    {
        while (true)
        {
            try
