class SensorReading {
public:
    std::string sensorType;
    double value;

    SensorReading(std::string sensorType, double value) : sensorType(sensorType), value(value) {}
};

class SensorReadings {
private:
    std::vector<std::shared_ptr<SensorReading>> readings;
    mutable std::mutex mtx;
    std::condition_variable cv;

public:
    void addReading(std::shared_ptr<SensorReading> reading) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            readings.push_back(reading);
        }
        cv.notify_all();
    }

    void readReadings() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !readings.empty(); });
            for (auto& reading : readings) {
                std::cout << "Sensor: " << reading->sensorType << ", Value: " << reading->value << std::endl;
            }
            readings.clear();
        }
    }

    void startReadingThread() {
        std::thread t([&this] { readReadings(); });
        t.detach();
    }
};

int main() {
    SensorReadings sensorReadings;

    // Add some sample readings
    sensorReadings.addReading(std::make_shared<SensorReading>("Temperature", 25.0));
    sensorReadings.addReading(std::make_shared<SensorReading>("Humidity", 60.0));
    sensorReadings.addReading(std::make_shared<SensorReading>("Light", 800.0));

    // Start the reading thread
    sensorReadings.startReadingThread();

    return 0;
}

