            await _userManager.CreateAsync(user);
            return Ok();
        }

        [HttpPost("login")]
        public async Task<IActionResult> Login([FromBody]LoginRequest request)
        {
            var user = await _userManager.FindByEmailAsync(request.Email);
            if (user == null || !await _userManager.VerifyPasswordAsync(user, request.Password))
                return BadRequest();

            var claims = new[] { new Claim(ClaimTypes.Email, user.Email) };
            var ticket = await _authenticationService.CreateTicketAsync(user);

            return Ok(new LoginResponse { Token = ticket.Serialize() });
        }

        [HttpPost("logout")]
        public async Task<IActionResult> Logout([FromHeader]string token)
        {
            await _authenticationService.RevokeTicketAsync(token);
            return Ok();
        }
    }
