    } else if (connCount > newConnCount) {
        int diff = connCount - newConnCount;
        for (int i = 0; i < diff; i++) {
            free(ueConns[connCount - i - 1]);
        }
        ueConns = realloc(ueConns, sizeof(UEConnectionInfo *) * newConnCount);
    }
    connCount = newConnCount;
    for (int i = 0; i < connCount; i++) {
        memcpy(&ueConns[i], &newConns[i], sizeof(UEConnectionInfo *));
    }
}

// Initialize and configure the dynamic array
void initUEConns() {
    // Fetch initial network parameters from external service
    UEConnectionInfo **initialConns = fetchInitialNetworkParams();
    updateNetworkParams(initialConns, initialConnCount);

    // Start a separate thread to periodically update network parameters
    pthread_t updateThread;
    pthread_create(&updateThread, NULL, periodicUpdateFunc, NULL);
}

// Periodic function to update network parameters
void* periodicUpdateFunc(void *arg) {
    while (true) {
        // Fetch updated network parameters from external service
        UEConnectionInfo **updatedConns = fetchUpdatedNetworkParams();

        // Update the dynamic array with new connection info
        updateNetworkParams(updatedConns, updatedConnCount);

        // Sleep for a short duration before next update
        usleep(10000);  // 10ms
    }
}

// Function to query and modify individual UE connection info entries
int getUEConnInfo(int rnti) {
    for (int i = 0; i < connCount; i++) {
        if (ueConns[i]->rnti == rnti) {
            // Return the corresponding UE connection info struct
            return i;
        }
    }
    return -1;  // RNTI not found
}

// Function to set a specific UE connection info entry
void setUEConnInfo(int rnti, int sfn, int frameType, int cellId) {
    int index = getUEConnInfo(rnti);
    if (index != -1) {
        ueConns[index]->sfn = sfn;
        ueConns[index]->frameType = frameType;
        ueConns[index]->cellId = cellId;
    }
}

// Free dynamically allocated memory
void freeUEConns() {
    for (int i = 0; i < connCount; i++) {
        free(ueConns[i]);
    }
    free(ueConns);
}
