// Thread-safe rate-limited queue
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int capacity;
    int size;
    void** items;
} RateLimitedQueue;

// Initialize and configure the dynamic array of UEConnectionInfo structs
void* initializeUEConnections(int capacity) {
    return calloc(capacity, sizeof(UEConnectionInfo));
}

// Implement thread-safe rate-limited queue
RateLimitedQueue* createRateLimitedQueue(int capacity) {
    RateLimitedQueue* q = (RateLimitedQueue*)malloc(sizeof(RateLimitedQueue));
    q->capacity = capacity;
    q->size = 0;
    q->items = malloc(capacity * sizeof(void*));
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->cond, NULL);
    return q;
}

// Add item to rate-limited queue
void enqueue(RateLimitedQueue* q, void* item) {
    pthread_mutex_lock(&q->mutex);
    if (q->size == q->capacity) {
        // Queue is full, wait until an item is removed or the queue is resized
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    q->items[q->size++] = item;
    pthread_mutex_unlock(&q->mutex);
}

// Remove and return the oldest item from the rate-limited queue
void* dequeue(RateLimitedQueue* q) {
    pthread_mutex_lock(&q->mutex);
    if (q->size == 0) {
        // Queue is empty, wait until an item is added or the queue is resized
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    void* oldest = q->items[0];
    memmove(q->items, q->items + 1, (q->size - 1) * sizeof(void*));
    q->size--;
    if (q->size == 0) {
        // Queue is empty, signal waiting threads
        pthread_cond_signal(&q->cond);
    }
    pthread_mutex_unlock(&q->mutex);
    return oldest;
}

