// Dynamic array of UEConnectionInfo structs
typedef struct {
    UEConnectionInfo** data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} UEConnectionInfoArray;

// Initialize and resize dynamic array
UEConnectionInfoArray* ueConnectionInfoArray_new(size_t initialCapacity) {
    UEConnectionInfoArray* arr = (UEConnectionInfoArray*)malloc(sizeof(UEConnectionInfoArray));
    arr->data = (UEConnectionInfo**)calloc(initialCapacity, sizeof(UEConnectionInfo*));
    arr->capacity = initialCapacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

// Resize dynamic array
void ueConnectionInfoArray_resize(UEConnectionInfoArray* arr, size_t newCapacity) {
    UEConnectionInfo** newData = (UEConnectionInfo**)calloc(newCapacity, sizeof(UEConnectionInfo*));
    memcpy(newData, arr->data, sizeof(UEConnectionInfo*) * arr->size);
    free(arr->data);
    arr->data = newData;
    arr->capacity = newCapacity;
}

// Lock and unlock dynamic array
void ueConnectionInfoArray_lock(UEConnectionInfoArray* arr) {
    pthread_mutex_lock(&arr->mutex);
}

void ueConnectionInfoArray_unlock(UEConnectionInfoArray* arr) {
    pthread_mutex_unlock(&arr->mutex);
}

// API for querying and modifying UEConnectionInfo entries
int ueConnectionInfoArray_add(UEConnectionInfoArray* arr, int id, const char* ipAddress, int port) {
    if (arr->size >= arr->capacity) {
        size_t newCapacity = arr->capacity * 2;
        ueConnectionInfoArray_resize(arr, newCapacity);
    }
    UEConnectionInfo* entry = (UEConnectionInfo*)malloc(sizeof(UEConnectionInfo));
    entry->id = id;
    entry->ipAddress = strdup(ipAddress);
    entry->port = port;
    arr->data[arr->size] = entry;
    arr->size++;
    return 0;
}

int ueConnectionInfoArray_remove(UEConnectionInfoArray* arr, int id) {
    for (size_t i = 0; i < arr->size; i++) {
        if (arr->data[i]->id == id) {
            free(arr->data[i]->ipAddress);
            free(arr->data[i]);
            memmove(&arr->data[i], &arr->data[i + 1], sizeof(UEConnectionInfo*) * (arr->size - i - 1));
            arr->size--;
            return 0;
        }
    }
    return -1; // Entry not found
}

int ueConnectionInfoArray_update(UEConnectionInfoArray* arr, int id, const char* ipAddress, int port) {
    for (size_t i = 0; i < arr->size; i++) {
        if (arr->data[i]->id == id) {
            free(arr->data[i]->ipAddress);
            arr->data[i]->ipAddress = strdup(ipAddress);
            arr->data[i]->port = port;
            return 0;
        }
    }
    return -1; // Entry not found
}

// Logging API for connection updates
void ueConnectionInfoArray_logUpdate(UEConnectionInfoArray* arr, UEConnectionInfo* entry) {
    printf("Updated connection info: id=%d, ipaddress=%s, port=%d\n", entry->id, entry->ipAddress, entry->port);
}

int main() {
    UEConnectionInfoArray* arr = ueConnectionInfoArray_new(10);

    // Example usage
    ueConnectionInfoArray_add(arr, 1, "192.168.1.100", 8080);
    ueConnectionInfoArray_add(arr, 2, "192.168.1.101", 8081);
    ueConnectionInfoArray_update(arr, 1, "192.168.1.102", 8082);

    // Logging example
    UEConnectionInfo* entry = arr->data[0];
    ueConnectionInfoArray_logUpdate(arr, entry);

    return 0;
}
