class NetworkDeviceStatus {
public:
    int deviceId;
    std::string ipAddress;
    std::string macAddress;
    double currentThroughput;
    bool isConnected;

    NetworkDeviceStatus(int deviceId, const std::string& ipAddress, const std::string& macAddress, double currentThroughput, bool isConnected)
        : deviceId(deviceId), ipAddress(ipAddress), macAddress(macAddress), currentThroughput(currentThroughput), isConnected(isConnected) {}
};

class NetworkDeviceManager {
public:
    using DeviceMap = std::map<int, std::unique_ptr<NetworkDeviceStatus>>;
    using MutexType = std::mutex;
    using LockType = std::lock_guard<MutexType>;

    void addDevice(int deviceId, const std::string& ipAddress, const std::string& macAddress, double currentThroughput, bool isConnected) {
        LockType lock(deviceMapMutex);
        deviceMap_[deviceId] = std::make_unique<NetworkDeviceStatus>(deviceId, ipAddress, macAddress, currentThroughput, isConnected);
    }

    void removeDevice(int deviceId) {
        LockType lock(deviceMapMutex);
        deviceMap_.erase(deviceId);
    }

    NetworkDeviceStatus* getDeviceStatus(int deviceId) {
        LockType lock(deviceMapMutex);
        auto it = deviceMap_.find(deviceId);
        if (it != deviceMap_.end()) {
            return it->second.get();
        }
        return nullptr;
    }

    void updateDeviceStatus(int deviceId, double newThroughput, bool isConnected) {
        LockType lock(deviceMapMutex);
        auto it = deviceMap_.find(deviceId);
        if (it != deviceMap_.end()) {
            it->second->currentThroughput = newThroughput;
            it->second->isConnected = isConnected;
        }
    }

private:
    DeviceMap deviceMap_;
    MutexType deviceMapMutex;
};

