namespace ECommerceUserManagementSystem.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class UserController : ControllerBase
    {
        private readonly UserManager<User> _userManager;
        private readonly RoleManager<Role> _roleManager;
        private readonly IEmailService _emailService;
        private readonly ICircuitBreaker _circuitBreaker;

        public UserController(UserManager<User> userManager, RoleManager<Role> roleManager, IEmailService emailService, ICircuitBreaker circuitBreaker)
        {
            _userManager = userManager;
            _roleManager = roleManager;
            _emailService = emailService;
            _circuitBreaker = circuitBreaker;
        }

        [HttpPost]
        public async Task<IActionResult> CreateUser([FromBody]UserCreateRequest request)
        {
            // Implement flexible validation rules for usernames and passwords
            if (!ValidateUsernameAndPassword(request.Username, request.Password))
            {
                return BadRequest("Invalid username or password");
            }

            // Implement rate limiting and account lockout mechanisms
            if (_userManager.IsAccountLockedOut(request.Username))
            {
                return StatusCode(StatusCodes.Status429TooManyRequests);
            }

            try
            {
                // Implement transactional database operations using distributed transactions and retry strategies
                await _userManager.CreateAsync(new User { Username = request.Username, Email = request.Email }, request.Password);

                // Send email verification for new users with retry mechanisms for transient network failures
                await _emailService.SendEmailVerification(request.Username);

                return CreatedAtAction(nameof(GetUser), new { id = request.Username }, "User created successfully");
            }
            catch (Exception ex)
            {
                // Implement error handling and logging
                _logger.LogError(ex, "Error creating user");
                throw;
            }
        }

        [HttpGet]
        public async Task<IActionResult> GetUser([FromRoute]int id)
        {
            // Implement role-based access control with dynamic permission assignment based on user activity
            var user = await _userManager.FindByIdAsync(id);
            if (user == null)
            {
                return NotFound("User not found");
            }

            // Implement caching frequently accessed data and minimizing database round trips
            var cachedUser = _cache.GetOrAdd($"user:{id}", async () =>
            {
                return await _userManager.FindByIdAsync(id);
            });

            return Ok(cachedUser);
        }

        [HttpPut]
        public async Task<IActionResult> UpdateUser([FromBody]UserUpdateRequest request)
        {
            // Implement email verification for existing users with retry mechanisms for transient network failures
            if (!await _emailService.VerifyEmail(request.Username))
            {
                return BadRequest("Invalid email");
            }

            try
            {
                // Implement transactional database operations using distributed transactions and retry strategies
                await _userManager.UpdateAsync(new User { Id = request.Id, Username = request.Username }, request.NewPassword);

                return Accepted($"User updated successfully");
            }
            catch (Exception ex)
            {
                // Implement error handling and logging
                _logger.LogError(ex, "Error updating user");
                throw;
            }
        }

        [HttpPost("login")]
        public async Task<IActionResult> Login([FromBody]LoginRequest request)
        {
            // Implement sophisticated rate limiting and account lockout mechanisms with adjustable thresholds based on user and IP patterns
            if (_userManager.IsAccountLockedOut(request.Username))
            {
                return StatusCode(StatusCodes.Status429TooManyRequests);
            }

            try
            {
                // Implement transactional database operations using distributed transactions and retry strategies
                var user = await _userManager.FindByNameAsync(request.Username);

                if (await _emailService.VerifyEmail(request.Username) && _roleManager.IsInRole(user, "admin"))
                {
                    return Ok("Admin login successful");
                }

                return Unauthorized("Invalid username or password");
            }
            catch (Exception ex)
            {
