using Microsoft.AspNetCore.Authentication.OpenIdConnect;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

public class Startup
{
    public Startup(IConfiguration configuration)
    {
        Configuration = configuration;
    }

    public IConfiguration Configuration { get; }

    // This method gets called by the runtime. Use this method to add services to the container.
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddAuthentication(options =>
        {
            options.DefaultAuthenticateScheme = "oidc";
            options.DefaultChallengeScheme = "oidc";
        })
        .AddOpenIdConnect("oidc", o =>
        {
            o.ClientId = Configuration["OpenIDConnect:ClientId"];
            o.ClientSecret = Configuration["OpenIDConnect:ClientSecret"];
            o.Authority = Configuration["OpenIDConnect:Authority"];
            o.CallbackPath = "/oidc/callback";
            o.GetAccessTokenForUserCallback = async (context) =>
            {
                var token = await context.Properties.GetTokenAsync();
                return token;
            };
        });

        services.AddControllers();
    }

    // This method gets called by the runtime. Use this method to configure the HTTP request pipeline.
    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }
        else
        {
            app.UseExceptionHandler("/Home/Error");
            // The default HSTS values are appropriate for most websites and
            // can be overridden if necessary for specific websites.
            app.UseHsts();
        }

        app.UseAuthentication();

        app.UseRouting();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
        });
    }
}
```

This is the basic ASP.NET Core startup class, setting up authentication with OpenID Connect and defining the routing for the application.']

