#include <condition_variable>

class NetworkDeviceStatus {
public:
    int deviceID;
    std::string IPaddress;
    std::string MACaddress;
    double currentThroughput;
    bool connectionStatus;

    // Constructor for creating a new NetworkDeviceStatus
    NetworkDeviceStatus(int id, const std::string& ip, const std::string& mac,
                         double throughput, bool status) :
        deviceID(id), IPaddress(ip), MACaddress(mac),
        currentThroughput(throughput), connectionStatus(status) {}
};

class NetworkDeviceManager {
private:
    using DeviceMap = std::unordered_map<int, std::shared_ptr<NetworkDeviceStatus>>;
    DeviceMap devices;

    // Mutex and condition variable for synchronization
    mutable std::mutex mutex;
    mutable std::condition_variable cv;

public:
    // Add a new network device to the manager
    void addDevice(int id, const std::string& ip, const std::string& mac,
                    double throughput, bool status) {
        auto device = std::make_shared<NetworkDeviceStatus>(id, ip, mac,
                                                              throughput, status);
        devices[deviceID] = device;
    }

    // Remove a network device from the manager
    void removeDevice(int id) {
        if (devices.find(id) != devices.end()) {
            devices.erase(id);
        }
    }

    // Get the current status of a network device
    NetworkDeviceStatus* getDeviceStatus(int id) {
        std::unique_lock<std::mutex> lock(mutex, stdstd::defer_lock);
        cv.wait_for(lock, std::chrono::milliseconds(10));  // Wait for 10ms before retrying

        if (devices.find(id) != devices.end()) {
            return devices.at(id).get();
        }
        return nullptr;
    }

    // Update the status of a network device
    void updateDeviceStatus(int id, double throughput, bool status) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait_for(lock, std::chrono::milliseconds(10));  // Wait for 10ms before retrying

        if (devices.find(id) != devices.end()) {
            devices.at(id)->currentThroughput = throughput;
            devices.at(id)->connectionStatus = status;
        }
    }

    // Handle API integration and caching
    void updateDeviceStatusFromAPI(int id, const std::string& apiResponse) {
        // Implement caching strategy and API communication logic here
        // For example:
        if (apiResponse.empty()) {
            return;  // No response from the API, no update needed
        }

        double throughput = getThroughputFromApiResponse(apiResponse);
        bool status = getStatusFromApiResponse(apiResponse);

        updateDeviceStatus(id, throughput, status);
    }
};
