int nfa_pi_crc_indication_pdu_array_add(nfa_pi_crc_indication_pdu_array_t* arr, nfa_pi_crc_indication_pdu_t* pdu) {
    pthread_mutex_lock(&arr->lock);
    if (arr->size == 0) {
        // Handle error: no space in the array
        return -1;
    }
    arr->array[arr->size] = *pdu;
    arr->size++;
    pthread_mutex_unlock(&arr->lock);
    return 0;
