void add_element(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to remove an element from the linked list
void remove_element(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* current = list->head;
    Node* previous = NULL;
    while (current != NULL && current->data.rnti != data.rnti) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) return;

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

