    while (current != NULL && current->data.rnti != data.rnti) {
        current = current->next;
    }
    return current;
}

// Function to free the linked list
void free_list(LinkedList* list) {
    Node* current = list->head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
