using System;

public class HybridCache
{
    private readonly Dictionary<string, object> _cache = new Dictionary<string, object>();
    private readonly List<string> _evictList = new List<string>();

    public void Add(string key, object value)
    {
        // In-memory caching for frequently accessed content
        _cache.Add(key, value);
    }

    public object Get(string key)
    {
        if (_cache.TryGetValue(key, out object value))
        {
            return value;
        }
        else
        {
            // Database query to retrieve data from the external data warehouse
            // ...
            return value;
        }
    }

    public void Evict(string key)
    {
        _evictList.Add(key);
    }

    public void Purge()
    {
        foreach (string key in _evictList)
        {
            _cache.Remove(key);
        }
        _evictList.Clear();
    }
}
