using System;
using System.Threading.Tasks;

public class DistributedJobQueue
{
    private readonly Queue<Task> _jobQueue = new Queue<Task>();
    private readonly List<WorkerThread> _workerThreads = new List<WorkerThread>();

    public void EnqueueTask(Task task)
    {
        _jobQueue.Enqueue(task);
    }

    public void StartWorkers(int numWorkers)
    {
        for (int i = 0; i < numWorkers; i++)
        {
            WorkerThread worker = new WorkerThread();
            _workerThreads.Add(worker);
            worker.Start();
        }
    }

    public void StopWorkers()
    {
        foreach (WorkerThread worker in _workerThreads)
        {
            worker.Stop();
        }
    }
}

class WorkerThread
{
    private readonly Thread _thread;

    public WorkerThread()
    {
        _thread = new Thread(Work);
    }

    public void Start()
    {
        _thread.Start();
    }

    public void Stop()
    {
        _thread.Abort();
    }

    private void Work()
    {
        while (true)
        {
            Task task;
            lock (_jobQueue)
            {
                if (_jobQueue.Count == 0)
                {
                    break;
                }
                task = _jobQueue.Dequeue();
            }
            task.Run();
        }
    }
}
```

