typedef struct {
    // Fields...
} NFAPI_CRC_INDICATION_PDU_T;

void populate_array(int N, int seed, char* log_path, char* serialization_path) {
    if (N < 1 || N > 1000) {
        fprintf(stderr, "Invalid array size: %d. Must be between 1 and 1000.\n", N);
        return;
    }

    srand(seed);

    // Create a thread-safe memory pool
    void* pool = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool) {
        fprintf(stderr, "Memory allocation failed. Out of memory.\n");
        return;
    }

    // Initialize the array with valid structures
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)pool;
    for (int i = 0; i < N; i++) {
        arr[i].RX_UE_INFORMATION_TAG = i;
        arr[i].RNTI = rand() % 256;
        arr[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        arr[i].CRCFLAG = rand() % 2;

        // Add error handling for memory allocation failures
    }

    // Serialize the array to binary and JSON formats
    FILE* file = fopen(serialization_path, "wb");
    if (file) {
        fwrite(arr, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
        fclose(file);

        file = fopen(serialization_path, "w");
        fprintf(file, "[\n");
        for (int i = 0; i < N; i++) {
            fprintf(file, "{\"RX_UE_INFORMATION_TAG\": %d, \"RNTI\": %d, \"CRC_INDICATION_REL8_TAG\": %d, \"CRCFLAG\": %d},\n",
                    arr[i].RX_UE_INFORMATION_TAG, arr[i].RNTI, arr[i].CRC_INDICATION_REL8_TAG, arr[i].CRCFLAG);
        }
        fprintf(file, "]");
        fclose(file);
    } else {
        fprintf(stderr, "Failed to serialize the array.\n");
    }

    // Log the array population process
    FILE* log_file = fopen(log_path, "w");
    if (log_file) {
        fprintf(log_file, "Array populated with %d structures.\n", N);
        fclose(log_file);
    } else {
        fprintf(stderr, "Failed to log the array population process.\n");
    }

    // Deallocate memory
    free(pool);

    return;
}
