from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_marshmallow import Marshmallow
import datetime
import requests
import logging.config

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///ecommerce.db"
db = SQLAlchemy(app)
marshmallow = Marshmallow(app)

class Product(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(100), nullable=False)
    description = db.Column(db.String, nullable=False)
    category = db.Column(db.String(50), nullable=False)
    price = db.Column(db.Float, nullable=False)
    stock = db.Column(db.Integer, nullable=False)

class ProductSchema(marshmallow.Schema):
    class Meta:
        fields = ("id", "title", "description", "category", "price", "stock")

product_schema = ProductSchema()
products_schema = ProductSchema(many=True)

@app.route("/products", methods=["GET"])
def get_products():
    all_products = Product.query.all()
    return jsonify(products_schema.dump(all_products))

@app.route("/products/<int:product_id>", methods=["GET"])
def get_product(product_id):
    product = Product.query.get(product_id)
    if product is None:
        return jsonify({"message": "Product not found"}), 404
    return jsonify(product_schema.dump(product))

@app.route("/products", methods=["POST"])
def create_product():
    data = request.get_json()
    new_product = Product(title=data["title"], description=data["description"], category=data["category"], price=data["price"], stock=data["stock"])
    db.session.add(new_product)
    db.session.commit()
    return jsonify(product_schema.dump(new_product))

@app.route("/products/<int:product_id>", methods=["PUT"])
def update_product(product_id):
    product = Product.query.get(product_id)
    if product is None:
        return jsonify({"message": "Product not found"}), 404
    data = request.get_json()
    product.title = data["title"]
    product.description = data["description"]
    product.category = data["category"]
    product.price = data["price"]
    product.stock = data["stock"]
    db.session.commit()
    return jsonify(product_schema.dump(product))

@app.route("/products/<int:product_id>", methods=["DELETE"])
def delete_product(product_id):
    product = Product.query.get(product_id)
    if product is None:
        return jsonify({"message": "Product not found"}), 404
    db.session.delete(product)
    db.session.commit()
    return jsonify({"message": "Product deleted"})

if __name__ == "__main__":
    app.run(debug=True)

# External Integration Code

@app.route("/payment", methods=["POST"])
def process_payment():
    data = request.get_json()
    # Process payment using external payment gateway API
    payment_gateway_api = requests.post("https://api.paymentgateway.com/payments", json=data)
    if payment_gateway_api.status_code == 200:
        return jsonify({"message": "Payment processed successfully"})
    else:
        return jsonify({"message": "Payment failed"}), 500

# Load Testing and Stress Testing Code

@app.route("/loadtest", methods=["GET"])
def load_test():
    # Run load test using tools like Apache JMeter or Gatling
    pass

if __name__ == "__main__":
    app.run(debug=True)

