// Define mutex to protect concurrent access
pthread_mutex_t stats_lock = PTHREAD_MUTEX_INITIALIZER;

// Define array to store NIC statistics records
nic_stats_record* nic_stats[M];

// Define function to update NIC statistics record
void update_stats(int interface_id, int packet_count, long byte_count) {
    pthread_mutex_lock(&stats_lock);

    // Update record for specified interface
    nic_stats[interface_id]->packet_count += packet_count;
    nic_stats[interface_id]->byte_count += byte_count;
    nic_stats[interface_id]->timestamp = time(NULL);

    pthread_mutex_unlock(&stats_lock);
}

// Define function to retrieve NIC statistics record
nic_stats_record* get_stats(int interface_id) {
    pthread_mutex_lock(&stats_lock);

    // Return record for specified interface
    return nic_stats[interface_id];

    pthread_mutex_unlock(&stats_lock);
}
