<?php

function authenticate_user($client_id, $client_secret, $redirect_uri, $code) {
    // Initialize OAuth 2.0 client
    $oauth = new GuzzleHttp\Client(['base_uri' => 'https://example.com/oauth/']);

    try {
        // Exchange authorization code for access token
        $response = $oauth->post('/token', [
            'form_params' => [
                'grant_type' => 'authorization_code',
                'code' => $code,
                'redirect_uri' => $redirect_uri,
                'client_id' => $client_id,
                'client_secret' => $client_secret
            ]
        ]);

        // Extract access token from response
        $access_token = json_decode($response->getBody()->getContents(), true)['access_token'];

        // Store access token securely in session variable
        $_SESSION['access_token'] = $access_token;

        return $access_token;
    } catch (GuzzleHttp\Exception\RequestException $e) {
        echo 'Error authenticating user: ' . $e->getMessage();
    }
}

function get_user_info($access_token) {
    // Initialize OAuth 2.0 client
    $oauth = new GuzzleHttp\Client(['base_uri' => 'https://example.com/api/']);

    try {
        // Retrieve user information using access token
        $response = $oauth->get('/user', [
            'headers' => [
                'Authorization' => 'Bearer ' . $access_token
            ]
        ]);

        // Extract user information from response
        $user_info = json_decode($response->getBody()->getContents(), true);

        return $user_info;
    } catch (GuzzleHttp\Exception\RequestException $e) {
        echo 'Error retrieving user information: ' . $e->getMessage();
    }
}

