app.use(authMiddleware);

// Retry Mechanisms for Transient Failures
app.use((req, res, next) => {
  const maxRetries = 3;
  let retries = 0;
  return async () => {
    try {
      await api1.callAPI();
    } catch (error) {
      if (retries < maxRetries) {
        setTimeout(() => {
          retries++;
          api1.retry();
        }, Math.pow(2, retries) * 100);
      } else {
        res.status(500).send({ message: error.message });
      }
    }
  };
});

// Front-End and Back-End Optimization
app.use(express.static('public'));
app.set('view engine', 'pug');
app.get('/', (req, res) => {
  // Optimize for performance and minimize payload size
  res.render('index', { title: 'Real-Time Analytics' });
});
