    std::map<std::string, std::chrono::time_point<std::chrono::system_clock>> cooldowns;
    std::mutex mutex;

    void executeStrategy(std::string strategy) {
        std::unique_lock<std::mutex> lock(mutex);

        if (cooldowns.find(strategy) == cooldowns.end()) {
            cooldowns[strategy] = std::chrono::system_clock::now();
        } else {
            auto lastExecutionTime = cooldowns[strategy];
            auto currentTime = std::chrono::system_clock::now();
            if (std::chrono::duration_cast<std::chrono::seconds>(currentTime - lastExecutionTime).count() < 15) {
                // Too soon, wait for the cooldown period
                return;
            }
        }

        // Strategy execution code here

        lock.unlock();

        std::cout << "Selected strategy: " << strategy << std::endl;

        // Update cooldown time
        cooldowns[strategy] = std::chrono::system_clock::now();
