class Logger {
public:
    Logger(const std::string& logDir, const std::string& metadataFile)
        : logDir_(logDir), metadataFile_(metadataFile) {}

    void processLogEntry(const LogEntry& entry) {
        // Check MD5 and SHA-256 hashes for integrity
        std::stringstream ss;
        ss << "uuid: " << entry.uuid << ", timestamp: " << entry.timestamp << ", level: " << entry.level
          << ", message: " << entry.message;
        const char* hashData = ss.str().c_str();
        unsigned char md5[MD5_DIGEST_LENGTH];
        unsigned char sha256[SHA256_DIGEST_LENGTH];
        MD5((const unsigned char*)hashData, strlen(hashData), md5);
        SHA256((const unsigned char*)hashData, strlen(hashData), sha256);

        // Store log entry and metadata in a distributed, version-controlled logging system
        std::ofstream file(logDir_ + "/" + entry.uuid + ".log", std::ios_base::app);
        if (file.is_open()) {
            file << "uuid: " << entry.uuid << ", timestamp: " << entry.timestamp << ", level: " << entry.level
                 << ", message: " << entry.message << "\n";
            file.close();
        }

        // Store metadata in a separate file for version control and indexing
        std::ofstream metaFile(metadataFile_);
        if (metaFile.is_open()) {
            metaFile << "uuid: " << entry.uuid << ", timestamp: " << entry.timestamp << ", level: " << entry.level
