    CRC_INDICATION_REL8_TAG* crc_ind_rel8_tag;
    CRCFLAG crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a struct to represent the library's state
typedef struct {
    int num_elements;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    NFAPI_CRC_INDICATION_PDU_T** elements;
} LibraryState;

// Function to create a new library instance
LibraryState* lib_create(int initial_size) {
    LibraryState* lib = (LibraryState*)malloc(sizeof(LibraryState));
    lib->num_elements = 0;
    pthread_mutex_init(&lib->mutex, NULL);
    pthread_cond_init(&lib->cond, NULL);
    lib->elements = (NFAPI_CRC_INDICATION_PDU_T**)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    return lib;
}

// Function to add an element to the library
void lib_add(LibraryState* lib, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&lib->mutex);
    lib->elements[lib->num_elements] = element;
    lib->num_elements++;
    pthread_cond_signal(&lib->cond);
    pthread_mutex_unlock(&lib->mutex);
}

// Function to get an element from the library
NFAPI_CRC_INDICATION_PDU_T* lib_get(LibraryState* lib, int index) {
    pthread_mutex_lock(&lib->mutex);
    if (index >= lib->num_elements) {
        pthread_mutex_unlock(&lib->mutex);
        return NULL;
