    this.concurrencyLevel = 5;
  }

  async log(level, message, contextualInfo) {
    if (this.config.levels.includes(level)) {
      for (const destination in this.config.destinations) {
        await this.writeToDestination(destination, level, message, contextualInfo);
      }
    }
  }

  async writeToDestination(destination, level, message, contextualInfo) {
    try {
      const formattedMessage = this.formatMessage(message, contextualInfo);
      if (this.config.destinations[destination].writeable) {
        await this.config.destinations[destination].write(formattedMessage);
      } else {
        await this.writeToBuffer(destination, formattedMessage);
      }
    } catch (error) {
      await this.writeError(destination, error);
    }
  }

  async writeToFile(fileDestination) {
    const fileWriter = new FileWriter(fileDestination);
    for await (const message of this.buffer) {
      await fileWriter.write(message);
    }
    await fileWriter.close();
