public class LoggingPipeline {
    public static void main(String[] args) throws Exception {
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setStreamTimezone("America/New_York");

        // Read logs from multiple namespaces and apply configurable filters
        DataStream<String> logStream = env.addSource(new LogReader())
                .flatMap(new MapFunction<String, String>() {
                    @Override
                    public void map(String log) throws Exception {
                        // Apply user-defined filtering criteria here
                        return log;
                    }
                });

