#include <iostream>
#include <queue>
#include <stack>
#include <unordered_map>
#include <mutex>
#include <condition_variable>

class DOMTraversal {
public:
    DOMTraversal(std::string cmsUrl, int maxDepth = 5) : 
        cmsUrl_(cmsUrl), maxDepth_(maxDepth) {}

    void traverse(const std::string& selector, const std::function<void(DOMNode&)>& callback);

private:
    struct DOMNode {
        std::string selector;
        std::stack<DOMNode> children;
    };

    std::string cmsUrl_;
    int maxDepth_;

    std::mutex mtx_;
    std::condition_variable cv_;
    std::queue<std::pair<DOMNode*, bool>> queue_; // pair of node and isLastLevel

    void enqueue(DOMNode* node) {
        std::unique_lock<std::mutex> lock(mtx_);
        queue_.push({node, false});
        cv_.notify_one();
    }

    DOMNode* dequeue() {
        std::unique_lock<std::mutex> lock(mtx_);
        while (queue_.empty()) cv_.wait(lock);
        auto [node, isLastLevel] = queue_.front();
        queue_.pop();
        return node;
    }
};

void DOMTraversal::traverse(const std::string& selector, const std::function<void(DOMNode&)>& callback) {
    // send API request to CMS
    // fetch web page and parse its DOM structure

    // traverse the DOM tree
    enqueue(new DOMNode{selector, {}});

    while (!queue_.empty()) {
        auto node = dequeue();
        if (node->children.empty() || !isLastLevel) callback(*node);

        // process node's children
        for (auto child : node->children) {
            enqueue(child);
        }
    }
}
