import os
import json
import boto3
import azure.mgmt.containerinstance
import googleapiclient.discovery

class CloudDeployer:
    def __init__(self):
        self.config = {}
        self.load_config()

    def load_config(self):
        try:
            with open('config.json', 'r') as f:
                self.config = json.load(f)
        except FileNotFoundError:
            pass

    def deploy_container(self, name, image, region):
        if self.config['cloud'] == 'aws':
            ec2 = boto3.client('ec2', region_name=region)
            response = ec2.create_container(name=name, image=image)
        elif self.config['cloud'] == 'azure':
            container_instance_client = azure.mgmt.containerinstance.ContainerInstanceClient(
                credentials=self.config['credentials'],
                subscription_id=self.config['subscription_id']
            )
            response = container_instance_client.container_instances.create_or_update(
                resource_group_name=self.config['resource_group_name'],
                container_name=name,
                image=image
            )
        elif self.config['cloud'] == 'gcp':
            container_client = googleapiclient.discovery.build('container', 'v1',
                                                              credentials=self.config['credentials'])
            response = container_client.cluster.create_cluster(
                parent=self.config['project_id'],
                cluster={'name': name, 'config': {'image': image}}
            )
        return response

    def list_containers(self):
        if self.config['cloud'] == 'aws':
            ec2 = boto3.client('ec2')
            containers = ec2.describe_container_instances()
        elif self.config['cloud'] == 'azure':
            container_instance_client = azure.mgmt.containerinstance.ContainerInstanceClient(
                credentials=self.config['credentials'],
                subscription_id=self.config['subscription_id']
            )
            containers = container_instance_client.container_instances.list()
        elif self.config['cloud'] == 'gcp':
            container_client = googleapiclient.discovery.build('container', 'v1',
                                                              credentials=self.config['credentials'])
            containers = container_client.cluster.list_clusters()
        return containers

    def main(self):
        if len(sys.argv) != 4:
            print("Usage: python deployer.py <name> <image> <region>")
            sys.exit(1)

        name, image, region = sys.argv[1:]
        response = self.deploy_container(name, image, region)
        print(json.dumps(response, indent=2))

if __name__ == '__main__':
    cloud_deployer = CloudDeployer()
    cloud_deployer.main()
```

This code provides a basic structure for the command-line tool. It uses Python's built-in `json` module to load configuration data from a file called "config.json". The `CloudDeployer` class has methods for deploying containers, listing existing containers, and handling command-line arguments.

The deployment method uses conditional logic to determine which cloud provider (AWS, Azure, or GCP) should be used based on the value of `self.config['cloud']`. It then uses the corresponding API client library to create a new container instance with the specified name, image, and region.']

