  }

  async authenticate(username: string, password: string) {
    try {
      const response = await axios.post('https://oauth2.example.com/token', { username, password }, {
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        validateStatus: false,
      });
      this.oAuth2Token = response.data.access_token;
    } catch (error) {
      throw error;
    }
  }

  async authorize() {
    try {
      const response = await axios.get('https://oauth2.example.com/authorize', {
        headers: { Authorization: `Bearer ${this.oAuth2Token}` },
      });
      return response.data;
    } catch (error) {
      throw error;
    }
  }
}

