  private retryDelay: number;

  constructor() {
    this.retryCount = 0;
    this.retryDelay = 1000; // initial delay in milliseconds
  }

  async handleAxiosError(error: any) {
    if (error.response.status === 429) {
      // Rate limit exceeded, retry after exponential backoff
      setTimeout(() => this.handleAxiosError(error), Math.pow(2, this.retryCount++) * this.retryDelay);
    } else {
      throw error;
    }
  }

