namespace hft {
    namespace data_processing {

        // Forward list of strings
        class RealTimeDataProcessor {
            public:
                RealTimeDataProcessor() : timestamps_(), max_latency_(0) {}

                void process(const std::vector<long long>& timestamps) {
                    auto it = timestamps_.begin();
                    for (const auto& timestamp : timestamps) {
                        *it++ = timestamp;
                    }
                    // Identify disjoint consecutive timestamp pairs
                    auto it2 = it;
                    while (it2 != timestamps_.end()) {
                        if (*it2 - *std::prev(it2) == 1) {
                            ++it2;
                        } else {
                            break;
                        }
                    }
                }

                void logAnomalies(const long long& threshold) {
                    for (auto it = timestamps_.begin(); it != --timestamps_.end();) {
                        if (*it - *std::prev(it) > threshold) {
                            std::cout << "Anomaly detected at timestamp: " << *it << std::endl;
                            break;
                        }
                    }
                }

            private:
                forward_list<long long> timestamps_;
                long long max_latency_;
        };

        // Function to insert a string after the first occurrence of another string
        void insertStringAfter(const forward_list<stdstring>& list, const string& target, const string& new_string) {
            auto it = list.begin();
            while (it != --list.end()) {
                if (*it == target) {
                    list.insert_after(it, new_string);
                    break;
                }
            }
        }

        // Function to bulk update strings after the first occurrence of another string
        void bulkUpdateStrings(const forward_list<string>& list, const string& target, const vector<string>& new_strings) {
            auto it = list.begin();
            while (it != --list.end()) {
                if (*it == target) {
                    for (const auto& new_string : new_strings) {
                        list.insert_after(it++, new_string);
                    }
                    break;
                }
            }
        }

