        {"client1", new ApiClient("endpoint1", "token1")},
        {"client2", new ApiClient("endpoint2", "token2")}
    });

    // Create threads to make requests concurrently
    vector<thread> threads;
    for (int i = 0; i < 5; i++) {
        threads.emplace_back([apiManager, &apiManager] {
            apiManager.makeRequests({});
        });
    }

    // Wait for all threads to complete
    for (auto &t : threads) {
        t.join();
    }

    return 0;
}

