async fn get_data_caching(id: i32) -> Result<String, reqwest::Error> {
    let cache = std::sync::Arc::new(std::collections::HashMap::new());

    if let Some(data) = cache.get(&id.to_string()) {
        return Ok(data.clone());
    }

    let client = Client::new();

    // dynamic endpoint version
    let url = format!("https://api.example.com/v{}", id % 3);

    let resp = client.get(&url)
        .send()
        .await?;

    if let Some(data) = resp.text().await {
        cache.insert(id.to_string(), data.clone());
        return Ok(data);
    }

    Err(reqwest::Error::new(reqwest::ErrorKind::Timeout))
}

async fn get_data_with_quota_management(id: i32) -> Result<String, reqwest::Error> {
    let quota_client = Client::new();

    // Get the quota
    let quota = quota_client.get("https://api.quota.example.com/quota")
        .send()
        .await?
        .json::<serde_json::Value>()
        .await?;

    if quota["remaining"] < 10 {
        return Err(reqwest::Error::new(reqwest::ErrorKind::Timeout));
    }

    let data_client = Client::new();

    // dynamic endpoint version
    let url = format!("https://api.example.com/v{}", id % 3);

    let resp = data_client.get(&url)
        .send()
        .await?;

    Ok(resp.text().await?)
}

async fn get_data_with_transient_outage_handling(id: i32) -> Result<String, reqwest::Error> {
    let client = Client::new();

    loop {
        match client.get("https://api.example.com/data")
            .send()
            .await {
                Ok(r) => return Ok(r.text().await?),
                Err(err) if err.kind() == reqwest::ErrorKind::Timeout => {
                    // transient outage handling
                    task::sleep(std::time::Duration::from_millis(1000)).await;
                }
                Err(_) => return Err(reqwest::Error::new(reqwest::ErrorKind::Timeout)),
            }
    }
}
