// Config
type Config struct {
	ListenIP   string `json:"listen_ip"`
	ListenPort int    `json:"listen_port"`

	CRMSystemURL  string `json:"crm_system_url"`
	PaymentGatewayURL string `json:"payment_gateway_url"`

	DatabaseURL  string `json:"database_url"`
	MaxConnections int    `json:"max_connections"`

	TLS   bool `json:"tls"`
	CertFile  string `json:"cert_file"`
	KeyFile  string `json:"key_file"`

	ThreadPoolSize int    `json:"thread_pool_size"`
}

// Server
type Server struct {
	*chi.Server

	Config *Config

	db *sql.DB

	ThreadPool *sync.Pool

	mu sync.RWMutex

	users map[string]*User
}

// User
type User struct {
	ID   string
	Name string
}

// NewServer
func NewServer(config *Config) (*Server, error) {
	srv := &Server{
		Config: config,
	}

	if err := srv.InitDatabase(); err != nil {
		return nil, err
	}

	if err := srv.InitThreadPool(); err != nil {
		return nil, err
	}

	srv.mu.Lock()
	defer srv.mu.Unlock()

	srv.users = make(map[string]*User)

	return srv, nil
}

// Run
func (s *Server) Run() error {
	http.HandleFunc("/messages", s.handleMessages)
	http.HandleFunc("/users", s.handleUsers)

	if s.Config.TLS {
		log.Println("Starting TLS server on port", s.Config.ListenPort)
	} else {
		log.Println("Starting non-TLS server on port", s.Config.ListenPort)
	}

	return http.ListenAndServe(fmt.Sprintf("%s:%d", s.Config.ListenIP, s.Config.ListenPort), nil)
}

// handleMessages
func (s *Server) handleMessages(w http.ResponseWriter, r *http.Request) {
	// Handle messages
}

// handleUsers
func (s *Server) handleUsers(w http.ResponseWriter, r *http.Request) {
	// Handle users
}

// InitDatabase
func (s *Server) InitDatabase() error {
	dbURL := s.Config.DatabaseURL
	maxConnections := s.Config.MaxConnections

	s.db, err = sqlx.Open("postgres", dbURL)
	if err != nil {
		return err
	}

	s.db.SetMaxOpenConns(maxConnections)

	return nil
}

// InitThreadPool
func (s *Server) InitThreadPool() error {
	threadPoolSize := s.Config.ThreadPoolSize

	s.ThreadPool = &sync.Pool{
	-New: func() interface{} {
			return &threadPool{}
		},
	}

	for i := 0; i < threadPoolSize; i++ {
		s.ThreadPool.Put(s.ThreadPool.New().(threadPool))
	}

	return nil
}
