#include "rmgr.h"

void* processStringAdvanced(void* rmgr, const char* inputStr, int sizeLimit) {
    onError NULL;
    int resultSize = 0;

    if (!validateRMGR(rmgr)) {
        onError(NULL);
        return NULL;
    }

    if (inputStr == NULL || *inputStr == '\0') {
        return NULL;
    }

    int len = getLengthFromRMGR(rmgr, inputStr);

    if (len < sizeLimit) {
        char* result = allocateBufferFromRMGR(rmgr, len + 1);
        strcpy(result, inputStr);
        result[len] = '/';
        return result;
    } else {
        if (!checkResourcesAvailable(rmgr)) {
            onError(NULL);
            return NULL;
        }

        int newSize = sizeLimit + 2;
        char* result = allocateBufferFromRMGR(rmgr, newSize);
        strcpy(result, inputStr);
        result[newSize - 1] = '/';
        return result;
    }
}

