using System;
using System.Threading.Tasks;
using StackExchange.Redis;

namespace HostnameProcessor
{
    public class HostnameProcessorService
    {
        private readonly IRedisConnection _redisConnection;
        private readonly IRecommendationEngine _recommendationEngine;
        private readonly IMetadataService _metadataService;
        private readonly IGeolocationService _geolocationService;

        public HostnameProcessorService(IRedisConnection redisConnection, 
            IRecommendationEngine recommendationEngine, 
            IMetadataService metadataService, 
            IGeolocationService geolocationService)
        {
            _redisConnection = redisConnection;
            _recommendationEngine = recommendationEngine;
            _metadataService = metadataService;
            _geolocationService = geolocationService;
        }

        public async Task ProcessHostnamesAsync(string[] hostnames)
        {
            foreach (var hostname in hostnames)
            {
                // Cache lookup
                var cachedResult = await GetCachedResult(hostname);
                if (cachedResult != null)
                {
                    // Use cached result and skip recommendation engine call
                    Console.WriteLine($"Using cached result for {hostname}");
                    continue;
                }

                // Fetch metadata and geolocation data
                var metadata = await _metadataService.GetMetadataAsync(hostname);
                var geolocationData = await _geolocationService.GetGeolocationAsync(hostname);

                // Process hostname with recommendation engine
                var recommendations = await _recommendationEngine.ProcessAsync(hostname, metadata, geolocationData);

                // Cache result for future lookups
                await SetCachedResult(hostname, recommendations);

                Console.WriteLine($"Processed {hostname} with recommendations: {string.Join(", ", recommendations)}");
            }
        }

        private async Task<string> GetCachedResult(string hostname)
        {
            var cachedResult = await _redisConnection.GetAsync("cached_results", hostname);
            return cachedResult?.ToString();
        }

        private async Task SetCachedResult(string hostname, string[] recommendations)
        {
            await _redisConnection.SetAsync("cached_results", hostname, recommendations);
        }
    }
}
