// File Validation Functionality
function validateFile(file) {
  const errors = [];

  if (!file.type.includes('image')) {
    errors.push({ code: 'invalid_file_type', message: 'Invalid file type' });
  }

  if (file.size > config.maxFileSize) {
    errors.push({ code: 'large_file_size', message: 'File size exceeds maximum allowed size' });
  }

  return errors;
}

// File Transformation Functionality
