  console.log(`Received message from Kafka topic: ${message.value}`);
  // Process the message and store it in MongoDB
  mongoose.model('mycollection').create(message.value, (err) => {
    if (err) {
      console.error(err);
    } else {
      console.log('Message successfully stored in MongoDB');
    }
  });
});

