        { value: 'This is a test message' }
      ]
    })
  ]);

  // Process and aggregate the data
  const aggregatedData = [];
  for (const item of data) {
    if (item.data && Array.isArray(item.data)) {
      aggregatedData.push(...item.data);
    }
  }

