    int total_packets[PACKET_COUNTS];
    int total_bytes[BYTE_COUNTS];
    time_t total_timestamps[TIMESTAMPED_METRICS];
} global_stats;

// Initialize the NIC and global statistics
void init_nic_and_global_stats(int num_interfaces) {
    // Initialize the interface information structure
    for (int i = 0; i < num_interfaces; i++) {
        // ... initialize interface_info structure ...
    }

    // Initialize the global statistics
    for (int i = 0; i < PACKET_COUNTS; i++) {
        global_stats.total_packets[i] = 0;
    }
    for (int i = 0; i < BYTE_COUNTS; i++) {
        global_stats.total_bytes[i] = 0;
    }
    for (int i = 0; i < TIMESTAMPED_METRICS; i++) {
        global_stats.total_timestamps[i] = time(NULL);
    }
}

// Update the NIC and global statistics
void update_nic_and_global_stats(interface_info *interface, int packet_count, int byte_count, time_t timestamp) {
    // ... update interface information structure ...
    for (int i = 0; i < PACKET_COUNTS; i++) {
        global_stats.total_packets[i] += packet_count;
    }
    for (int i = 0; i < BYTE_COUNTS; i++) {
        global_stats.total_bytes[i] += byte_count;
    }
    for (int i = 0; i < TIMESTAMPED_METRICS; i++) {
        if (timestamp > global_stats.total_timestamps[i]) {
            for (int j = i; j >= 0; j--) {
                global_stats.total_timestamps[j] = timestamp;
            }
        }
    }
}

