using namespace std;

class TradingStrategy {
public:
    virtual void executeTrade() = 0;
};

class StrategyAlpha : public TradingStrategy {
private:
    bool cooldownActive = true;
    chrono::time_point<chrono::system_clock> lastExecutionTime;

public:
    void executeTrade() override {
        if (cooldownActive) {
            auto now = chrono::system_clock::now();
            auto cooldownDuration = chrono::duration_cast<chrono::seconds>(10);
            if ((now - lastExecutionTime).count < cooldownDuration.count) {
                cout << "Strategy Alpha on cooldown. Waiting for 10 seconds." << endl;
                this_thread::sleep_for(cooldownDuration);
                return;
            }
        }

        // execute trade logic here
    }
};

