#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 10000000
#define BUFFER_SIZE 1024
#define API_ENDPOINT "https://api.example.com/convert"

typedef struct {
    char date[20];
    char time[20];
    int transaction_id;
    double amount;
    char category[50];
    char currency[3];
} Transaction;

Transaction *transactions[MAX_TRANSACTIONS];
int num_transactions = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
double prev_avg_amount = 0.0;

void *process_transaction(void *data) {
    Transaction *transaction = (Transaction *) data;

    // Check for invalid data formats and missing fields
    if (!strlen(transaction->date) || !strlen(transaction->time) || transaction->amount < 0) {
        return NULL;
    }

    pthread_mutex_lock(&lock);

    if (num_transactions >= 2 && prev_avg_amount > 0.0) {
        double avg_amount = (prev_avg_amount + transaction->amount) / 2.0;
        printf("Average transaction amount: %.2f\n", avg_amount);
        prev_avg_amount = avg_amount;
    }

    if (!strcmp(transaction->currency, "USD")) {
        // Make API call for currency conversion
        FILE *fp = popen(API_ENDPOINT, "w");
        fprintf(fp, "%s %s %.2f\n", transaction->date, transaction->time, transaction->amount);
        pclose(fp);
    }

    pthread_mutex_unlock(&lock);

    return NULL;
}

int main() {
    // Initialize memory pool
    void *pool = malloc(BUFFER_SIZE);

    FILE *fp = fopen("log_file.log", "r");

    if (fp) {
        char line[BUFFER_SIZE];
        while (fgets(line, BUFFER_SIZE, fp)) {
            Transaction *transaction = (Transaction *) pool;
            sscanf(line, "%s %s %d %.2f %s %s", transaction->date, transaction->time, &transaction->transaction_id, &transaction->amount, transaction->category, transaction->currency);

            // Process transactions in parallel
            pthread_t threads[MAX_TRANSACTIONS];
            for (int i = 0; i < num_transactions + 1; i++) {
                if (pthread_create(&threads[i], NULL, process_transaction, transaction) != 0) {
                    perror("Error creating thread");
                }
            }

            // Wait for all threads to finish
            for (int i = 0; i < num_transactions + 1; i++) {
                pthread_join(threads[i], NULL);
            }
        }

        fclose(fp);
    } else {
        perror("Error opening log file");
    }

    return 0;
}

```']

