    // Initialize the file operation context
    fileOperationContext* ctx = (fileOperationContext*)malloc(sizeof(fileOperationContext));
    if (!ctx) {
        return NULL;
    }

    // Load OpenSSL library at runtime
    SSL_library_init();
    SSL_load_error_strings();

    // Load the third-party file handling library
    FILE_MGMT_LIBRARY_LOAD_RESULT result = fileManagementLib_LoadLibrary();
    if (result != FILE_MGMT_LIBRARY_LOAD_SUCCESS) {
        free(ctx);
        return NULL;
    }

    // Initialize the file management context
    ctx->fileMgmtCtx = fileManagementLib_CreateContext(filePath, options);
    if (!ctx->fileMgmtCtx) {
        fileManagementLib_UnloadLibrary();
        free(ctx);
        return NULL;
    }

    // Execute the file operation based on the given command
    if (strcmp(operation, "encrypt") == 0) {
        ctx->result = encryptFile(ctx->fileMgmtCtx);
    } else if (strcmp(operation, "decrypt") == 0) {
        ctx->result = decryptFile(ctx->fileMgmtCtx);
    } else if (strcmp(operation, "integrityCheck") == 0) {
        ctx->result = integrityCheckFile(ctx->fileMgmtCtx);
    } else if (strcmp(operation, "extractMetadata") == 0) {
        ctx->result = extractMetadataFile(ctx->fileMGMT_CTX);
    } else {
        // Handle unknown operations
        free(ctx);
        return NULL;
    }

    // Free the file management context and library
