#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>

class SensorData {
public:
    int device_id;
    double value;
};

class DataProcessor {
private:
    std::queue<SensorData> data_queue;
    std::mutex queue_mutex;
    std::condition_variable queue_cond;
    bool is_processing = false;

public:
    void start_processing() {
        is_processing = true;
    }

    void stop_processing() {
        is_processing = false;
    }

    void process_data(SensorData data) {
        while (!is_processing) {
            std::unique_lock<std::mutex> lock(queue_mutex);
            queue_cond.wait(lock, [&] { return is_processing; });
        }

        // Process the sensor data
        std::cout << "Processed device_id: " << data.device_id << ", value: " << data.value << std::endl;
    }

    void add_data_to_queue(SensorData data) {
        std::unique_lock<std::mutex> lock(queue_mutex);
        data_queue.push(data);
        queue_cond.notify_one();
    }
};

class IoTSystem {
public:
    DataProcessor processor;

    void start_processing() {
        processor.start_processing();
    }

    void stop_processing() {
        processor.stop_processing();
    }

    void add_data_to_queue(SensorData data) {
        processor.add_data_to_queue(data);
    }
};

int main() {
    IoTSystem system;

    // Start processing
    system.start_processing();

    for (int i = 0; i < 20000; i++) {
        SensorData data;
        data.device_id = i;
        data.value = static_cast<double>(i) / 100.0;

        // Add sensor data to queue
        system.add_data_to_queue(data);

        // Process sensor data concurrently
        std::thread thread([&] {
            while (!system.processor.is_processing()) {}

            system.processor.process_data(data);
        });

        thread.join();
    }

    // Stop processing
    system.stop_processing();

    return 0;
}

