    api, err := http.NewTLSClient(&tls.Config{RootCASecrets: []byte("your-custom-ca-bundle")})
    if err != nil {
        return nil, err
    }

    return &AttackSelecter{
        ctx:  ctx,
        api:  api,
        cooldown: cooldown,
    }, nil
}

func (as *AttackSelecter) SelectAndExecuteAttack(env string, character string) error {
    // Fetch attack data from external API and store it in a local cache (if available)
    attacks, err := as.api.Get(as.ctx, as.APIEndpoint + "/attacks/" + env + "/" + character)
    if err != nil {
        return err
