    config := &Config{
        APIEndpoint: "https://api.example.com",
        Cooldown:   1 * time.Second,
        Environments: map[string]map[string]string{
            "local":     {"character": "your-local-character"},
            "staging":   {"character": "your-staging-character"},
            "production": {"character": "your-production-character"},
        },
    }

    attackSelecter, err := NewAttackSelecter(ctx, config.APIEndpoint, config.Cooldown)
    if err != nil {
        log.Fatal(err)
    }

    // Execute attacks for different environments
    for env, settings := range config.Environments {
        character, ok := settings["character"]
        if !ok {
            log.Printf("Environment %s missing character setting", env)
            continue
        }
        err = attackSelecter.SelectAndExecuteAttack(env, character)
