typedef struct {
    int packet_counts;
    long byte_counts;
    time_t timestamp;
} nic_stats;

// Define a struct to hold interface information
typedef struct {
    char *name;
    pthread_mutex_t lock;
    nic_stats stats;
} nic_info;

// Define the library's main structure
typedef struct {
    nic_info *interfaces[M];
    pthread_mutex_t global_lock;
    time_t last_update;
} nic_lib;

// Initialize the library
nic_lib *init_nic_lib() {
    nic_lib *lib = (nic_lib *)malloc(sizeof(nic_lib));
    lib->last_update = time(NULL);
    for (int i = 0; i < M; i++) {
        lib->interfaces[i] = (nic_info *)malloc(sizeof(nic_info));
        lib->interfaces[i]->name = (char *)malloc(strlen("interface") + strlen(std::to_string(i)) + 1);
        sprintf(lib->interfaces[i]->name, "interface_%d", i);
        pthread_mutex_init(&lib->interfaces[i]->lock, NULL);
    }
    return lib;
}

// Update NIC statistics
void update_nic_stats(nic_lib *lib, int interface_id) {
    pthread_mutex_lock(&lib->interfaces[interface_id]->lock);
    // Update the statistics here
    pthread_mutex_unlock(&lib->interfaces[interface_id]->lock);
}

// Get NIC statistics
nic_stats get_nic_stats(nic_lib *lib, int interface_id) {
    pthread_mutex_lock(&lib->interfaces[interface_id]->lock);
    nic_stats stats = lib->interfaces[interface_id]->stats;
    pthread_mutex_unlock(&lib->interfaces[interface_id]->lock);
    return stats;
}

// Integrate with monitoring API
void report_nic_stats(nic_lib *lib) {
    // Send the statistics to the API here
}

// Main function
int main() {
    nic_lib *lib = init_nic_lib();
    // Update NIC statistics
    update_nic_stats(lib, 0);
    // Get NIC statistics
    nic_stats stats = get_nic_stats(lib, 0);
    printf("Packet counts: %d\n", stats.packet_counts);
    printf("Byte counts: %ld\n", stats.byte_counts);
    return 0;
}
