#include <chrono>

// Define a struct to hold sensor data
struct SensorData {
    int id;
    float value;
};

class DataProcessor {
public:
    DataProcessor() : stopped(false) {}

    void startProcessing() {
        thread_ = std::thread([this]() { process(); });
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            stopped = true;
        }
        if (thread_.joinable()) {
            thread_.join();
        }
    }

private:
