#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <json-c/json.h>

#define MAX_RECORDS 1000000
#define BUFFER_SIZE 10000
#define NUM_THREADS 4

typedef struct {
    int start;
    int end;
} RecordRange;

void* process_records(void* arg) {
    RecordRange* range = (RecordRange*)arg;
    FILE* file = fopen("large_csv_file.csv", "r");
    if (!file) {
        printf("Error opening file.\n");
        return NULL;
    }

    fseek(file, range->start * BUFFER_SIZE, SEEK_SET);
    char buffer[BUFFER_SIZE];
    int processed = 0;

    while (fread(buffer, 1, BUFFER_SIZE, file) > 0) {
        // Process records in the buffer
        int i;
        for (i = 0; i < BUFFER_SIZE; i++) {
            if (buffer[i] == '\n') {
                // Validate and transform record
                json_object* config = json_object_from_file("config.json");
                json_object* result = validate_and_transform(buffer, i);
                json_object_put(result);

                // Store transformed data in database
                database_insert(config, result);

                processed++;
            }
        }
    }

    fclose(file);
    return NULL;
}

int main(int argc, char** argv) {
    pthread_t threads[NUM_THREADS];
    RecordRange ranges[NUM_THREADS];

    int chunk_size = MAX_RECORDS / NUM_THREADS;
    for (int i = 0; i < NUM_THREADS; i++) {
        ranges[i].start = i * chunk_size;
        if (i == NUM_THREADS - 1) {
            ranges[i].end = MAX_RECORDS;
        } else {
            ranges[i].end = (i + 1) * chunk_size - 1;
        }
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, process_records, &ranges[i]);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

