use regex::Regex;
use std::collections::HashSet;

fn parse_grammar(file_path: &str) -> String {
    let re = Regex::new(r"(\w+)\s*:\s*(\S+)").unwrap();
    let mut grammar = HashSet::new();

    std::fs::read_to_string(file_path).unwrap()
        .lines()
        .for_each(|line| {
            if let Some(caps) = re.captures(line) {
                let production_name = caps.get(1).map_or("", |m| m.as_str());
                let production_rule = caps.get(2).map_or("", |m| m.as_str());

                grammar.insert((production_name.to_string(), production_rule.to_string()));
            }
        });

    let mut ir_code = String::new();
    for (&name, &rule) in &grammar {
        ir_code.push_str(&format!("define {} = {{\n", name));
        ir_code.push_str(&format!("  code: {}\n", rule));
        ir_code.push_str("}};\n");
    }

    ir_code
}

fn main() {
    let file_path = "path/to/grammar/file";
    println!("{}", parse_grammar(file_path));
}
