using System;
using System.Xml.Linq;
using System.IO;

namespace GameConfigManager
{
    public class ConfigManager
    {
        private readonly XDocument _configXml;

        public ConfigManager(string configFilePath)
        {
            _configXml = XDocument.Load(configFilePath);
        }

        public void LoadMaps()
        {
            foreach (XElement mapElement in _configXml.Descendants("Map"))
            {
                string mapName = mapElement.Attribute("Name").Value;
                int mapWidth = Convert.ToInt32(mapElement.Element("Dimensions").Attribute("Width").Value);
                int mapHeight = Convert.ToInt32(mapElement.Element("Dimensions").Attribute("Height").Value);

                // Load tiles for the current map
                foreach (XElement tileElement in mapElement.Descendants("Tile"))
                {
                    string tileId = tileElement.Attribute("Id").Value;
                    int tileWidth = Convert.ToInt32(tileElement.Attribute("Width").Value);
                    int tileHeight = Convert.ToInt32(tileElement.Attribute("Height").Value);

                    // Add tile to the game engine
                    GameEngine.AddTile(mapName, tileId, tileWidth, tileHeight);
                }
            }
        }

        public void UpdateConfig()
        {
            Console.WriteLine("Enter new values for tile size:");
            int tileSize = Convert.ToInt32(Console.ReadLine());
            Console.WriteLine("Enter new map dimensions (width and height):");
            int mapWidth = Convert.ToInt32(Console.ReadLine());
            int mapHeight = Convert.ToInt32(Console.ReadLine());

            // Update config XML
            _configXml.Descendants("Map").First().Element("Dimensions").SetAttributeValue("Width", mapWidth.ToString());
            _configXml.Descendants("Map").First().Element("Dimensions").SetAttributeValue("Height", mapHeight.ToString());

            foreach (XElement tileElement in _configXml.Descendants("Tile"))
            {
                tileElement.SetAttributeValue("Width", tileSize.ToString());
                tileElement.SetAttributeValue("Height", tileSize.ToString());
            }

            // Save updated config XML
            _configXml.Save("updated_config.xml");
        }
    }
}
