    RequestType type;

    // Constructor for the request
    Request(File file, RequestType type) : file(file), type(type) {}
};

// Enum to represent different types of requests (read or write)
enum RequestType { READ, WRITE };

int main() {
    // Create a distributed file storage system with K files and P clients
    DistributedFileStorageSystem dfs(K, P);

    // Add some sample files to the system
    File file1 = {"file1.txt", {}, 1};
    File file2 = {"file2.txt", {}, 2};
    dfs.addFile(file1);
