#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>

class ImageProcessor {
public:
    ImageProcessor(size_t concurrency, size_t batchSize) 
        : concurrency_(concurrency), batchSize_(batchSize) {}

    void processBatch(const std::vector<Image>& images) {
        std::vector<std::thread> threads;
        std::queue<Image> imageQueue;

        // Enqueue images
        for (const auto& img : images) {
            imageQueue.push(img);
        }

        // Start processing threads
        for (size_t i = 0; i < concurrency_; ++i) {
            threads.emplace_back([this, &imageQueue]() {
                while (true) {
                    Image img;
                    if (imageQueue.try_pop(img)) {
                        // Process image here
                        std::cout << "Processing: " << img.filename << std::endl;
                    } else {
                        break; // No more images to process
                    }
                }
            });
        }

        // Wait for all threads to finish
        for (auto& thread : threads) {
            thread.join();
        }
    }

private:
    size_t concurrency_;
    size_t batchSize_;
};

int main() {
    ImageProcessor processor(4, 10); // Process up to 10 images in parallel

    std::vector<Image> images = ...; // Load your image files here
    processor.processBatch(images);

    return 0;
}
