    int packet_count;
    int byte_count;
    time_t timestamp;
} InterfaceStats;

// Structure to represent a cache entry
typedef struct {
    char key[16];
    InterfaceStats value;
} CacheEntry;

// Structure to represent the cache
typedef struct {
    CacheEntry* entries;
    int capacity;
    int size;
    pthread_mutex_t lock;
} Cache;

// Function to initialize the cache
void init_cache(Cache* cache, int capacity) {
    cache->entries = (CacheEntry*)malloc(capacity * sizeof(CacheEntry));
    cache->capacity = capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
}

// Function to get a cache entry
InterfaceStats* get_cache_entry(Cache* cache, char* key) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->entries[i].key, key) == 0) {
            pthread_mutex_unlock(&cache->lock);
            return &cache->entries[i].value;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

// Function to add a cache entry
void add_cache_entry(Cache* cache, char* key, InterfaceStats value) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->entries[i].key, key) == 0) {
            cache->entries[i].value = value;
            pthread_mutex_unlock(&cache->lock);
            return;
        }
    }
    // Add new entry
    if (cache->size >= cache->capacity) {
        // Handle cache overflow
    } else {
        cache->entries[cache->size].key = key;
        cache->entries[cache->size].value = value;
        cache->size++;
    }
    pthread_mutex_unlock(&cache->lock);
}

