            System.out.println("Message exceeds character limit. Skipping.");
            return;
        }
        try {
            message.parse();
            messages.add(message);
            messageIntegrity = true;
        } catch (Exception e) {
            messageIntegrity = false;
            System.out.println("Error processing message: " + e.getMessage());
