#include <iostream>
#include <vector>
#include <unordered_map>

// Union-Find data structure
class UnionFind {
public:
    UnionFind(int n) : parent_(n, -1), rank_(n, 0) {}

    int find(int x) {
        if (parent_[x] != -1)
            parent_[x] = find(parent_[x]);
        return parent_[x];
    }

    void unionSet(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY)
            return;

        if (rank_[rootX] < rank_[rootY])
            std::swap(rootX, rootY);

        parent_[rootY] = rootX;
        if (rank_[rootX] == rank_[rootY])
            rank_[rootX]++;
    }

private:
    std::vector<int> parent_;
    std::vector<int> rank_;
};

// Function to count disjoint pairs in an integer array
int countDisjointPairs(std::vector<int>& arr) {
    int n = arr.size();
    UnionFind uf(n);

    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (uf.find(i) != uf.find(j)) {
                int startTime = std::chrono::high_resolution_clock::now().time_since_epoch().count();
                uf.unionSet(i, j);
                int endTime = std::chrono::high_resolution_clock::now().time_since_epoch().count();
                std::cout << "Disjoint pair found in " << (endTime - startTime) / 1e6 << " milliseconds." << std::endl;
            }
        }
    }

    return uf.parent_.size() - 1; // Number of disjoint pairs
}

int main() {
    std::vector<int> arr = {1, 2, 3, 4, 5};
    int numDisjointPairs = countDisjointPairs(arr);
    std::cout << "Total number of disjoint pairs: " << numDisjointPairs << std::endl;
    return 0;
}
