#define MAX_CRCINDICATION 100000

typedef struct {
    int rnti;
    int crcflag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint32_t ue_id;
    RX_UE_INFORMATION_TAG rx_ue_info;
