NFAPI_CRC_INDICATION_PDU_T* populate_crc_indication(int start_ue_id, int end_ue_id) {
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = NULL;
    int num_crc_indications = 0;

    // Check for valid UE ID range
    if (start_ue_id > end_ue_id || start_ue_id < 1 || end_ue_id > MAX_UERANGE) {
        printf("Invalid UE ID range. Returning empty list.\n");
        return crc_indications;
    }

    // Initialize database connection
    MYSQL *conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "localhost", "username", "password", "database_name", 0, NULL, 0)) {
        printf("Error connecting to database. Returning empty list.\n");
        return crc_indications;
    }

    // Generate CRC indication structures
    for (int ue_id = start_ue_id; ue_id <= end_ue_id; ue_id++) {
        NFAPI_CRC_INDICATION_PDU_T* new_crc_indication = NULL;

        // Allocate memory for new CRC indication structure
        if (!(new_crc_indication = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)))) {
            printf("Memory allocation failed. Returning empty list.\n");
            mysql_close(conn);
            return crc_indications;
        }

        // Set UE ID and RX UE INFORMATION TAG
        new_crc_indication->ue_id = ue_id;
        new_crc_indication->rx_ue_info.rnti = rand() % 1000 + 1;
        new_crc_indication->rx_ue_info.crcflag = rand() % 2;

        // Set CRC indication REL8 tag
        for (int i = 0; i < 4; i++) {
            new_crc_indication->crc_indication_rel8_tag[i] = (uint8_t)rand() % 256;
        }

        // Insert new CRC indication into database
        if (!mysql_query(conn, "INSERT INTO crc_indications (ue_id, rnti, crcflag, crc_indication_rel8_tag) VALUES (?, ?, ?, ?)", MYSQL_TYPE_LONG_DATA, ue_id, &new_crc_indication->rx_ue_info.rnti, &new_crc_indication->rx_ue_info.crcflag, new_crc_indication->crc_indication_rel8_tag)) {
            printf("Error inserting CRC indication into database.\n");
            free(new_crc_indication);
            mysql_close(conn);
            return crc_indications;
        }

        // Update list of CRC indications
        if (num_crc_indications >= MAX_CRCINDICATION) {
            printf("Maximum number of CRC indications exceeded. Returning truncated list.\n");
            break;
        }

        crc_indications = realloc(crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (num_crc_indications + 1));
        crc_indications[num_crc_indications] = new_crc_indication;

        num_crc_indications++;

        // Commit database transaction
        if (!mysql_query(conn, "COMMIT")) {
            printf("Error committing database transaction.\n");
            mysql_rollback(conn);
            for (int i = 0; i < num_crc_indications; i++) {
                free(crc_indications[i]);
            }
            free(crc_indications);
            return NULL;
        }

        // Log generation process and capture any errors
        printf("Generated CRC indication for UE ID %d.\n", ue_id);

        // Release database connection
        mysql_close(conn);
    }

    // Return list of generated CRC indications
    return crc_indications;
}

int main() {
    int start_ue_id = 1;
    int end_ue_id = MAX_UERANGE;

    NFAPI_CRC_INDICATION_PDU_T* crc_indications = populate_crc_indication(start_ue_id, end_ue_id);

    // Free allocated memory and print list of CRC indications
    for (int i = 0; i < num_crc_indications; i++) {
        free(crc_indications[i]);
    }
    free(crc_indications);

    return 0;
}
