function asyncReduce(arr, callback) {
  return new Promise((resolve, reject) => {
    let result = 0;
    arr.forEach((num, index) => {
      setTimeout(() => {
        if (isNaN(num)) {
          reject(new Error("Invalid number in array"));
        } else {
          result += num;
        }
      }, index * 100);
    });
    setTimeout(() => {
      resolve(result);
    }, arr.length * 100);
  });
}
