import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class TelemetryMicroservice {
    private static final int MAX_DEVICES = 10000;
    private static final int MIN_WORKERS = 5;
    private static final int MAX_WORKERS = 20;

    private List<Device> devices = new ArrayList<>();
    private ExecutorService executor;
    private DistributedQueue queue;

    public TelemetryMicroservice() {
        queue = new DistributedQueue();
        executor = Executors.newCachedThreadPool(MIN_WORKERS, MAX_WORKERS);

        // Start devices
        for (int i = 0; i < MAX_DEVICES; i++) {
            Device device = new Device(i);
            devices.add(device);
            executor.submit(device::run);
        }
    }

    public void process(String data) {
        try {
            // Process data and put it in the queue
            Telemetry telemetry = new Telemetry(data);
            queue.put(telemetry);

            // Start a worker to consume from the queue
            executor.submit(() -> queue.take().process());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private class Device implements Runnable {
        private int id;

        public Device(int id) {
            this.id = id;
        }

        @Override
        public void run() {
            while (true) {
                // Read data from the device and send it to the microservice
                String data = readData();
                process(data);
            }
        }
    }

    private class DistributedQueue {
        private List<Telemetry> queue = new ArrayList<>();

        public synchronized void put(Telemetry telemetry) {
            while (queue.size() >= MAX_DEVICES) {
                try {
                    wait();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            queue.add(telemetry);
            notifyAll();
        }

        public synchronized Telemetry take() throws InterruptedException {
            while (queue.isEmpty()) {
                wait();
            }
            return queue.remove(0);
        }
    }
}
