// Define a struct for the cooldown management system
struct CooldownManager {
    std::unordered_map<std::string, unsigned int> cooldownTimes;
    std::mutex mutex;
    std::condition_variable condVar;

    void checkCooldown(std::string strategy) {
        if (cooldownTimes.count(strategy)) {
            auto now = std::chrono::high_resolution_clock::now().time_since_epoch().count();
            if (now < cooldownTimes.at(strategy)) {
                // Cooldown not yet complete, wait until it is
                std::unique_lock<std::mutex> lock(mutex);
                condVar.wait_for(std::chrono::seconds(cooldownTimes.at(strategy) - now));
                lock.unlock();
            }
        }
    }

    void setCooldownTime(std::string strategy, unsigned int cooldown) {
        cooldownTimes[strategy] = std::chrono::high_resolution_clock::now().time_since_epoch().count() + cooldown;
    }
};

