#include <condition_variable>
#include <chrono>

class LogProcessor {
public:
    LogProcessor(const std::string& filename) : filename_(filename), mmf_(nullptr), average_(0.0), count_(0) {}

    void process() {
        if (mmf_ == nullptr) {
            mmf_ = std::mem_map(filename_.c_str(), 1024 * 1024, PROT_READ | MAP_SHARED);
            if (!mmf_) {
                std::cerr << "Error: unable to map file " << filename_ << "\n";
                return;
            }
        }

        // Compute moving average
        double sum = 0.0;
        int count = 0;

        for (int i = 0; i < 10 && mmf_; ++i) {
            char* line = reinterpret_cast<char*>(mmf_) + i * sizeof(std::string);
            std::istringstream iss(line);

            if (!iss || !std::getline(iss, field_)) {
                // Invalid or empty line
                break;
            }

            double value;
            if (sscanf(field_.c_str(), "%lf", &value) != 1) {
                // Not a numerical field
                continue;
            }

            sum += value;
            ++count;

            average_ = sum / count;
        }

        for (int i = 0; mmf_; ++i) {
            char* line = reinterpret_cast<char*>(mmf_) + i * sizeof(std::string);

            // Compute and append moving average
            std::ostringstream oss;

            oss << field_;
            oss << " avg: " << average_ << " sd: " << 0.5; // Assume SD is 0.5

            // Output the modified log line
            std::cout << oss.str() << "\n";
        }

        // Release memory-mapped file
        if (mmf_) {
            ::munmap(mmf_, 1024 * 1024);
            mmf_ = nullptr;
        }
    }

private:
    std::string filename_;
    char* mmf_;
    double average_;
    int count_;

    std::string field_;
};

