        if level == 1:
            self.logger.info(message)
        elif level == 2:
            self.logger.warning(message)
        elif level == 3:
            self.logger.error(message)
        else:
            self.logger.critical(message)

    def setup_logger(self) -> None:
        logging.basicConfig(
            format="%(asctime)s - %(name)s - %(levelname)s - %(message)s",
            datefmt="%Y-%m-%d %H:%M:%S"
        )

    def get_log_level(self) -> int:
        return self.logger.getEffectiveLevel()

class LogAggregator:
    def __init__(self):
        self.log_buffer = []

    def add_log_entry(self, log_entry: str) -> None:
        self.log_buffer.append(log_entry)

    def flush_log_buffer(self) -> List[str]:
        temp_list = self.log_buffer
        self.log_buffer = []
        return temp_list

class LogRouter:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)
        self.routing_config: Dict[str, str] = {}

    def route_log_entry(self, log_entry: str) -> None:
        for route in self.routing_config:
            if log_entry.startswith(route):
                self.logger.info(f"Routed log entry to {route}")
                break
        else:
            self.logger.info("No matching route found. Log entry will be discarded")

    def set_routing_config(self, config: Dict[str, str]) -> None:
        self.routing_config = config

class MonitoringSystem:
    def __init__(self):
        self.alerts: List[Dict[str, str]] = []

    def send_alert(self, alert_type: str, message: str) -> None:
        if not any(alert['type'] == alert_type for alert in self.alerts):
            self.alerts.append({'type': alert_type, 'message': message})

    def get_active_alerts(self) -> List[Dict[str, str]]:
        return [alert for alert in self.alerts if alert['type'] != "cleared"]

class RealTimeMonitor:
    def __init__(self, monitoring_system: MonitoringSystem):
        self.monitoring_system = monitoring_system
        self.alert_rules: Dict[str, str] = {}

    def monitor_log_entries(self, log_entry: str) -> None:
        for rule in self.alert_rules:
            if log_entry.startswith(rule):
                self.monitoring_system.send_alert('error', f"Error occurred: {log_entry}")
                break

    def add_alert_rule(self, rule: str) -> None:
        self.alert_rules[rule] = True

# Usage
logger = Logger()
logger.setup_logger()

log_aggregator = LogAggregator()
log_router = LogRouter()
monitoring_system = MonitoringSystem()

real_time_monitor = RealTimeMonitor(monitoring_system)
real_time_monitor.add_alert_rule("Error: ")
real_time_monitor.monitor_log_entries("Error occurred: Something went wrong")

print(logger.get_log_level())
```']

