using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;

namespace SaaSPlatform.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class AuthenticationController : ControllerBase
    {
        private readonly UserManager<User> _userManager;

        public AuthenticationController(UserManager<User> userManager)
        {
            _userManager = userManager;
        }

        [HttpPost]
        public async Task<IActionResult> Login([FromBody] LoginModel loginModel)
        {
            var user = await _userManager.FindByNameAsync(loginModel.Username);

            if (user == null || !await _userManager.CheckPasswordAsync(user, loginModel.Password))
                return Unauthorized();

            var claims = new[] { new Claim(ClaimTypes.Name, user.UserName) };
            var jwtToken = await GenerateJwtToken(claims);

            return Ok(new LoginResponse { Token = jwtToken });
        }

        [HttpPost]
        public async Task<IActionResult> Register([FromBody] RegisterModel registerModel)
        {
            var user = new User { UserName = registerModel.Username, Email = registerModel.Email };

            await _userManager.CreateAsync(user, registerModel.Password);

            return Ok();
        }
    }
}
