    public static void main(String[] args) {
        SpringApplication.run(FinancialDataPlatformApplication.class, args);
    }

    @Bean
    public RouteBuilder route() {
        return new RouteBuilder() {
            @Override
            public void configure() throws Exception {
                from("wss://exchange1/ws")
                    .aggregate().correlationExpression().header("id")
                    .completionPredicate().justOne()
                    .to("kafka:topic1");

                from("wss://exchange2/ws")
                    .aggregate().correlationExpression().header("id")
                    .completionPredicate().justOne()
                    .to("kafka:topic2");

                // Risk assessment engine
                from("kafka:topic1")
                    .bean(RiskAssessmentEngine.class)
                    .to("kafka:risk_topic");

                from("kafka:risk_topic")
                    .infinite()
                    .aggregate().correlationExpression().header("id")
                    .completionPredicate().justOne()
                    .to("kafka:alerts_topic");

                // AI service integration
                from("kafka:alerts_topic")
                    .bean(AIService.class)
                    .to("kafka:predictive_model_topic");

                // Compliance monitoring module
                from("kafka:predictive_model_topic")
                    .bean(ComplianceMonitoringModule.class)
                    .to("kafka:compliance_reports_topic");

                // Regulatory sandbox environment
