```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <mutex>
#include <unordered_map>

class AttackSelector {
public:
    enum class Attack { A, B, C };

    AttackSelector(std::string apiEndpoint) : apiEndpoint_(apiEndpoint) {}

    void setCooldownPeriod(int seconds) {
        cooldownPeriod_ = std::max(1, seconds);
    }

    Attack selectAttack() {
        if (cooldownTimer_.expired()) {
            auto attack = getRandomAttack();
            cooldownTimer_ = std::chrono::steady_clock::now() + std::chrono::seconds(cooldownPeriod_);
            return attack;
        }
        return Attack::A; // or default to a neutral attack
    }

private:
    std::string apiEndpoint_;
    int cooldownPeriod_;
    std::chrono::steady_clock::time_point cooldownTimer_;
    std::mutex mutex_;
    std::random_device rd;
    std::mt19937 mt;
    std::uniform_int_distribution<int> getRandomAttack() {
        return std::uniform_int_distribution<int>(0, 2);
    }
};
```
