["Here is a sample code block for designing a highly available, scalable, and extensible C library to manage dynamic Network Interface Control (NIC) statistics:

```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define a struct to represent NIC statistics
typedef struct {
    int packet_count;
    long byte_count;
    time_t timestamp;
} nic_stats;

// Define a struct to represent interface configurations
typedef struct {
    char *name;
    int max_packet_rate;
    int max_byte_rate;
    pthread_mutex_t mutex;
} interface_config;

// Define a struct to represent the library's state
typedef struct {
    nic_stats *stats;
    int num_interfaces;
    int num_packets;
    long total_bytes;
    time_t last_update;
    pthread_mutex_t stats_lock;
} lib_state;

// Initialize the library's state
lib_state *init_lib(int num_interfaces) {
    lib_state *state = malloc(sizeof(lib_state));
    state->stats = calloc(num_interfaces, sizeof(nic_stats));
    state->num_interfaces = num_interfaces;
    state->num_packets = 0;
    state->total_bytes = 0;
    state->last_update = time(NULL);
    pthread_mutex_init(&state->stats_lock, NULL);
    return state;
}

// Update NIC statistics for a specific interface
void update_stats(lib_state *state, int interface_id, nic_stats stats) {
    pthread_mutex_lock(&state->stats_lock);
    state->stats[interface_id] = stats;
    state->num_packets += stats.packet_count;
    state->total_bytes += stats.byte_count;
    state->last_update = time(NULL);
    pthread_mutex_unlock(&state->stats_lock);
}

// Calculate NIC statistics for a specific interface
nic_stats get_stats(lib_state *state, int interface_id) {
    pthread_mutex_lock(&state->stats_lock);
    nic_stats stats = state->stats[interface_id];
    pthread_mutex_unlock(&state->stats_lock);
    return stats;
}
```

This code provides the basic structure for managing NIC statistics and defines the following:

*   A `nic_stats` struct to represent interface-level statistics (packet count, byte count, and timestamp).
*   An `interface_config` struct to represent individual interface configurations (name, packet rate, byte rate, and mutex).
*   A `lib_state` struct to represent the library's overall state (statistics array, number of interfaces, total packets, total bytes, last update time, and a mutex for locking statistics access).

The code also includes initializations for the library's state (`init_lib`) and functions for updating (`update_stats`) and retrieving NIC statistics (`get_stats`)."]

