    // create and start multiple log streams
    for (size_t i = 0; i < 4; ++i) {
        logManager.addLogStream(i, 100);
        std::thread(logStreamThread, &logManager, i).detach();
    }

    // process logs in a separate thread
    std::thread(logProcessingThread, &logManager).detach();

    return 0;
}

void logStreamThread(LogManager* logManager, size_t id) {
    for (size_t i = 0; i < 100; ++i) {
        logManager->getLogStream(id)->log("This is a log message", nullptr);
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
}

void logProcessingThread(LogManager* logManager) {
    while (true) {
        logManager->processLogs();
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }
}
