class SensorData {
public:
    int id;
    std::string type;
    std::string data;

    SensorData(int id, const std::string& type, const std::string& data) : 
        id(id), type(type), data(data) {}
};

class MiddlewareApplication {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::vector<std::thread> threads;
    std::deque<SensorData> sensorDataQueue;
    std::unordered_map<int, int> bufferSizes;

public:
    MiddlewareApplication() : 
        threads(5), 
        bufferSizes({}) {}

    void start() {
        for (int i = 0; i < 5; i++) {
            threads.emplace_back([this]() { this->processSensorData(); });
        }
    }

    void processSensorData() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !sensorDataQueue.empty(); });
            SensorData sensorData = sensorDataQueue.front();
            sensorDataQueue.pop_front();

            // Process sensor data here
            std::cout << "Processing sensor data: " << sensorData.type << std::endl;

            lock.unlock();
            cv.notify_all();
        }
    }

    void addSensorData(const SensorData& sensorData) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            sensorDataQueue.emplace_back(sensorData);
            cv.notify_one();
        }
    }

    int getBufferSizes(int id) const {
        return bufferSizes.find(id)->second;
    }

    void setBufferSizes(int id, int size) {
        bufferSizes[id] = size;
    }
};

int main() {
    MiddlewareApplication app;

    // Initialize sensor data and buffer sizes
    std::vector<SensorData> sensorData = {};
    for (int i = 0; i < 15; i++) {
        SensorData sensorDatum(i, "Sensor_" + std::to_string(i), "Sensor Data");
        sensorData.push_back(sensorDatum);
        app.setBufferSizes(i, 1024 * 10);
    }

    // Start processing sensor data
    app.start();

    // Add sensor data to the queue
    for (const auto& sensor : sensorData) {
        app.addSensorData(sensor);
    }

    return 0;
}
