typedef struct Node {
    FrameStatistics* data;
    struct Node* next;
} Node;

Node* head = NULL; // Initialize the head of the linked list

// Function to add a new FrameStatistics structure to the linked list
void addFrameStatistics(FrameStatistics* frame) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = frame;
    newNode->next = head;
    head = newNode;
}

// Function to find and remove a specific FrameStatistics structure from the linked list
void removeFrameStatistics(int frame_id) {
    Node* current = head;
    Node* previous = NULL;

    while (current != NULL && current->data->frame_id != frame_id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // Frame not found

    if (previous == NULL) {
        head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

