// Inventory item container
class Inventory {
public:
    Inventory() : items_({}) {}

    // Add an item to the inventory
    void addItem(const std::shared_ptr<Item>& item) {
        items_.insert(std::make_pair(item->getId(), item));
    }

    // Remove an item from the inventory
    bool removeItem(const std::string& itemId) {
        auto it = items_.find(itemId);
        if (it != items_.end()) {
            items_.erase(it);
            return true;
        }
        return false;
    }

    // Get an item from the inventory by ID
    const std::shared_ptr<Item>& getItem(const std::string& itemId) {
        auto it = items_.find(itemId);
        if (it != items_.end()) {
            return it->second;
        }
        return nullptr;
    }

private:
    std::unordered_map<std::string, std::shared_ptr<Item>> items_;
};

