```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// FrameStatistics structure
typedef struct {
    int frame_id;
    double timestamp;
    char* data;
} FrameStatistics;

// Dynamic collection of FrameStatistics structures
typedef struct {
    FrameStatistics** frames;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} FrameCollection;

// Initialize a new FrameCollection instance
FrameCollection* frame_collection_init(int initial_capacity) {
    FrameCollection* fc = (FrameCollection*)malloc(sizeof(FrameCollection));
    fc->frames = (FrameStatistics**)malloc(initial_capacity * sizeof(FrameStatistics*));
    fc->size = 0;
    fc->capacity = initial_capacity;
    pthread_mutex_init(&fc->mutex, NULL);
    return fc;
}

// Add a new FrameStatistics instance to the collection
void frame_collection_add(FrameCollection* fc, FrameStatistics* fs) {
    pthread_mutex_lock(&fc->mutex);
    if (fc->size >= fc->capacity) {
        // Increase capacity and reallocate frames array
        fc->capacity *= 2;
        fc->frames = (FrameStatistics**)realloc(fc->frames, fc->capacity * sizeof(FrameStatistics*));
    }
    fc->frames[fc->size++] = fs;
    pthread_mutex_unlock(&fc->mutex);
}

// Free the resources associated with a FrameCollection instance
void frame_collection_free(FrameCollection* fc) {
    pthread_mutex_lock(&fc->mutex);
    for (int i = 0; i < fc->size; i++) {
        free(fc->frames[i]->data);
        free(fc->frames[i]);
    }
