    void processCommands(std::vector<std::tuple<std::string, std::string, bool>> commands) {
        for (auto& command : commands) {
            auto target = std::get<0>(command);
            auto insertString = std::get<1>(command);
            auto position = std::get<2>(command);
            auto logError = std::get<3>(command);

            // Handle insertion command
            if (position == "before") {
                // Append or insert string before target
                appendOrInsertBefore(target, insertString, logError);
            } else if (position == "after") {
                // Append or insert string after target
                appendOrInsertAfter(target, insertString, logError);
            }

            // Log errors if required
            if (logError) {
                logErrorIfRequired();
            }
        }
    }

private:
    void appendOrInsertBefore(std::string target, std::string insertString, bool logError) {
        // Find the node responsible for the segment containing the target string
        auto node = getNodeForTarget(target);

        // Append or insert string before the target
        node->appendOrInsertBefore(target, insertString);

        // Update the forward list metadata
        updateMetadata(node);
    }

    void appendOrInsertAfter(std::string target, std::string insertString, bool logError) {
        // Find the node responsible for the segment containing the target string
        auto node = getNodeForTarget(target);

        // Append or insert string after the target
        node->appendOrInsertAfter(target, insertString);

        // Update the forward list metadata
        updateMetadata(node);
    }

    void logErrorIfRequired() {
        // Check if the log buffer is exceeded
        if (logBufferExceeded()) {
            // Batch and retry logging if required
            batchAndRetryLogging();
        } else {
            // Log the error without batching
            logError();
        }
    }

    bool logBufferExceeded() {
        // Check if the log buffer size exceeds the maximum allowed size
        return logBuffer().size() > 1024;
    }

    void batchAndRetryLogging() {
        // Batch errors and retry logging with exponential backoff
        for (int i = 0; i < 3; i++) {
            try {
                logError();
                break;
            } catch (...) {
                // Retry with exponential backoff
                std::this_thread::sleep_for(std::chrono::milliseconds(1 << i));
            }
        }
    }

