const rateLimiter = new (require('express-rate-limit'))({
    host: dnsApi,
    windowMs: 1000, // 1 second
    delayMs: 5000, // 5 seconds
});

// Define file processing function
async function processFile(file) {
    try {
        const jsonContent = JSON.parse(await fs.readFileSync(file.path));
        await validateJson(jsonContent);
    } catch (err) {
        console.error(`Error processing file ${file.name}: ${err}`);
    }
}

// Define validation function using JSON schema
function validateJson(data, schemaPath) {
    return new Promise((resolve, reject) => {
        const schema = jsonschema.compile(fs.readFileSync(schemaPath));
        try {
            schema.validate(data);
            resolve();
        } catch (err) {
            reject(err);
        }
    });
}

// Define worker function to handle file processing and validation
async function processWorker(file) {
    await rateLimiter.consume();
    try {
        await processFile(file);
    } catch (err) {
        console.error(`Error processing ${file.name}: ${err}`);
    }
}

// Define main application logic
async function resolveNetwork() {
    // Process files in parallel using the worker pool
    const files = await fs.readdirSync('.');
    for (const file of files) {
        if (file.endsWith('.txt')) {
            workerPool[files.indexOf(file)] = child_process.fork(`node processWorker.js ${path.join('.')}/${file}`);
        }
    }

    // Monitor and manage worker processes
    setImmediate(() => {
        Object.keys(workerPool).forEach((workerId) => {
            const worker = workerPool[workerId];
            if (worker) {
                worker.on('exit', () => {
                    console.log(`Worker ${workerId} exited`);
                    delete workerPool[workerId];
                });
                worker.on('error', (err) => {
                    console.error(`Error in worker ${workerId}: ${err}`);
                });
            }
        });
    });
}

// Start the application
resolveNetwork();

