    int current_state = 0;
    for (int i = 0; i < strlen(input); i++) {
        current_state = transition(fsa, input[i] - 'a'); // Adjust for ASCII encoding
        printf("Current state: %d\n", current_state);
    }

    if (is_accepting(fsa)) {
        printf("FSA accepts the input string!\n");
    } else {
        printf("FSA does not accept the input string.\n");
    }

    free_fsa(fsa);
