// Define a task queue with scheduled and ad-hoc task submission support
class TaskQueue {
  #tasks = [];
  #scheduledTasks = {};
  #lastTaskId = 0;

  addTask(task) {
    this.#tasks.push(task);
    if (task.scheduled) {
      this.#scheduledTasks[task.scheduledAt] = task;
    }
  }

  async executeTask() {
    const task = this.#tasks.shift();
    if (!task) return;

    try {
      await task.function();
    } catch (error) {
      // Handle task execution errors
      console.error(`Task ${task.id} failed: ${error.message}`);
    }

    this.#lastTaskId++;
  }

  async executeScheduledTasks() {
    const scheduledTasks = Object.keys(this.#scheduledTasks);
    scheduledTasks.forEach((timestamp) => {
      const task = this.#scheduledTasks[timestamp];
      if (Date.now() > task.scheduledAt) {
        delete this.#scheduledTasks[timestamp];
        await this.executeTask(task);
      }
    });
  }

  async submitScheduledTask(jobFunction, scheduledAt) {
    const task = TaskFactory.create(jobFunction);
    task.scheduled = true;
    task.scheduledAt = scheduledAt;
    this.#scheduledTasks[scheduledAt] = task;
    this.addTask(task);
  }

