        class ForwardListUtil {
        public:
            static void insertAfter(const std::forward_list<std::string>& list, const std::string& target, const std::string& newStr) {
                auto it = list.begin();
                while (it != list.end()) {
                    if (*it == target) {
                        list.insert_after(it++, newStr);
                        return;
                    }
                    ++it;
                }
                list.push_back(newStr);
            }

            static void bulkUpdate(const std::forward_list<std::string>& list, const std::vector<std::pair<std::string, std::string>>& updates) {
                for (const auto& update : updates) {
                    auto it = list.begin();
                    while (it != list.end()) {
                        if (*it == update.first) {
                            list.insert_after(it++, update.second);
                            return;
                        }
                        ++it;
                    }
                    list.push_back(update.second);
                }
            }
        };
