                    break;
                } else {
                    sleep(pow(2, $retries));
                }
            } catch (GuzzleHttp\Exception\RequestException $e) {
                if ($e->getCode() === 429 || $e->getCode() === 503) {
                    // Implement circuit breaker pattern
                    sleep(60);
                } elseif ($e->getCode() >= 400 && $e->getCode() < 500) {
                    // Handle client errors; retry with exponential backoff
                    sleep(pow(2, $retries));
                } else {
                    throw $e;
                }
            }
        }

        if ($retries === 3) {
            // Fallback mechanism: switch to alternative data source (e.g., local database)
            // ...
        }
    }

    private function getCacheValue(int $clinicId): array
    {
        return $this->cacheAdapter->getItem('clinic_' . $clinicId)->get();
    }

    private function updateCache(int $clinicId, string $newStatus): void
    {
        $item = $this->cacheAdapter->getItem('clinic_' . $clinicId);
        $item->set($newStatus);
        $item->expiresAfter(3600); // 1 hour cache expiration
