type Employee struct {
	ID          int    `json:"id"`
	Name        string `json:"name"`
	Department  string `json:"department"`
	Supervisor  int    `json:"supervisor"`
	HireDate     string `json:"hire_date"`
}

func (e *Employee) GetFromDB(db *sql.DB, supervisorID int) ([]*Employee, error) {
	stmt, err := db.Prepare("SELECT * FROM employees WHERE supervisor_id = ?")
	if err != nil {
		return nil, err
	}
	defer stmt.Close()

	rows, err := stmt.QueryRows(supervisorID)
	if err != nil {
		return nil, err
	}

	var employees []*Employee
	for rows.Next() {
		e := &Employee{}
		err := rows.Scan(&e.ID, &e.Name, &e.Department, &e.Supervisor, &e.HireDate)
		if err != nil {
			log.Println(err)
			continue
		}
		employees = append(employees, e)
	}

	return employees, nil
}

