use std::collections::{HashMap, HashSet};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

struct DisjointSetAnalyzer {
    sets: Arc<Mutex<HashMap<i32, i32>>>,
    parent_map: Arc<Mutex< HashMap<i32, Option<i32>>>>,
}

impl DisjointSetAnalyzer {
    fn new() -> Self {
        DisjointSetAnalyzer {
            sets: Arc::new(Mutex::new(HashMap::new())),
            parent_map: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn union(&self, x: i32, y: i32) {
        let sets = self.sets.lock().unwrap();
        let parent_map = self.parent_map.lock().unwrap();

        if let Some(parent) = *parent_map.get(&x) {
            if let Some(merge) = *parent_map.get(&y) {
                if parent == merge {
                    return;
                }
            }
        }

        if let Some(parent) = *parent_map.get(&x) {
            *parent_map.lock().unwrap().insert(y, Some(parent));
        } else if let Some(merge) = *parent_map.get(&y) {
            *parent_map.lock().unwrap().insert(x, Some(merge));
        } else {
            *sets.insert(x, y);
            *parent_map.lock().unwrap().insert(x, Some(y));
        }
    }

    pub fn find(&self, x: i32) -> Option<i32> {
        let parent_map = self.parent_map.lock().unwrap();
        if let Some(parent) = *parent_map.get(&x) {
            return self.find(*parent);
        } else {
            return Some(x);
        }
    }

    pub fn is_connected(&self, x: i32, y: i32) -> bool {
        let parent_map = self.parent_map.lock().unwrap();
        if let Some(parent_x) = *parent_map.get(&x) {
            if let Some(parent_y) = *parent_map.get(&y) {
                return parent_x == parent_y;
            }
        } else if let Some(merge) = *parent_map.get(&y) {
            return self.find(x) == Some(merge);
        }
        false
    }

    pub fn process_stream(mut stream: impl Iterator<Item = Vec<i32>>) {
        for array in stream {
            for x in array {
                // process the array here...
            }
        }
    }

    pub async fn run() {
        let mut analyzer = DisjointSetAnalyzer::new();

        // handle input arrays
