class StreamingDataProcessor {
public:
    void startProcessing() {
        // Initialize internal state and threads
        _internalState = "Initializing";
        _processingThread = std::thread(&StreamingDataProcessor::process, this);
    }

    void stopProcessing() {
        // Signal the processing thread to stop
        _stopProcessingFlag = true;
        // Wait for the thread to finish
        _processingThread.join();
    }

    void addData(const std::string& data) {
        // Add data to the input queue
        _inputQueue.push(data);
    }

private:
    void process() {
        while (_internalState != "Stopped") {
            if (!_inputQueue.empty()) {
                // Dequeue and process incoming data
                const auto& currentData = _inputQueue.front();
                _processData(currentData);
                _inputQueue.pop();
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

    void _processData(const std::string& data) {
        // Apply dynamic data rate handling
        if (_dataRate > 1.5f) {
            _applyAdaptiveBuffering(data);
        } else {
            _deliverDataToSink(data);
        }
    }

    void _applyAdaptiveBuffering(const std::string& data) {
        // Implement adaptive buffering and throttling mechanisms
        if (!_bufferedData.empty()) {
            const auto& oldestData = _bufferedData.front();
            _deliverDataToSink(oldestData);
            _bufferedData.pop();
        }
        _bufferedData.push(data);
