namespace DecryptionService
{
    public class DecryptionService
    {
        private readonly ILogger<DecryptionService> _logger;
        private readonly VaultService _vaultService;

        public DecryptionService(ILogger<DecryptionService> logger, VaultService vaultService)
        {
            _logger = logger;
            _vaultService = vaultService;
        }

        public string Decrypt(string ciphertext, int keySize)
        {
            using var aes = Aes.Create();
            aes.Key = _vaultService.GetKey(keySize);
            aes.IV = _vaultService.GetIv();

            ICryptoTransform encryptor = aes.CreateEncryptor(aes.Key, aes.IV);

            using var ms = new MemoryStream(Encoding.UTF8.GetBytes(ciphertext));
            using var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Read);
            byte[] decryptedBytes = new byte[cs.Length];
            cs.Read(decryptedBytes, 0, decryptedBytes.Length);

            string decryptedText = Encoding.UTF8.GetString(decryptedBytes);

            _logger.LogInformation("Decryption successful. Decrypted text: {text}", decryptedText);

            return decryptedText;
        }

        public void Verify(string decryptedText)
        {
            using var hmac = new HMACSHA256(_vaultService.GetKey(256));
            byte[] signature = Convert.FromBase64String(decryptedText.Split(' ')[1]);
            byte[] expectedSignature = hmac.ComputeHash(Encoding.UTF8.GetBytes(decryptedText.Split(' ')[0]));
            if (!Equals(signature, expectedSignature))
            {
                _logger.LogError("Decryption failure: Tampered or corrupted data detected.");
            }
        }

        public void LogError(string message)
        {
            _logger.LogError(message);
        }
    }
}

public class VaultService
{
