public class DataProcessor
{
    private readonly ILogger _logger;
    private readonly ITransformer[] _transformers;
    private readonly IDatabase _database;

    public DataProcessor(ILogger<DataProcessor> logger, ITransformer[] transformers, IDatabase database)
    {
        _logger = logger;
        _transformers = transformers;
        _database = database;
    }

    [Function("DataProcessor")]
    public async Task<HttpResponseMessage> Run(
        [HttpTrigger(AuthorizationLevel.Function, "POST", Route = null)]HttpRequestData req)
    {
        try
        {
            var file = await req.Body.ReadAsStreamAsync();
            var data = new DataTransformer(file);
            foreach (var transformer in _transformers)
            {
                data = await transformer.Transform(data);
            }
            await _database.InsertAsync(data);
            return new HttpResponseMessage { StatusCode = HttpStatusCode.OK };
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing data");
            return new HttpResponseMessage { StatusCode = HttpStatusCode.InternalServerError };
        }
    }
}

public interface ITransformer
{
    Task<Data> Transform(Data input);
}

public class DataTransformer : ITransformer
{
    private readonly ILogger _logger;
    private readonly IFileReader _fileReader;

    public DataTransformer(ILogger<DataTransformer> logger, IFileReader fileReader)
    {
        _logger = logger;
        _fileReader = fileReader;
    }

