use std::path::{Path, PathBuf};
use std::fs;
use std::env;
use std::sync::atomic::{AtomicBool, Ordering};
use log::{info, warn};

// Define a struct to store the persistent config directory and environment variable
pub struct AppConfig {
    pub path: PathBuf,
    pub env_var: String,
}

impl AppConfig {
    // Create the persistent config directory and set the environment variable
    pub fn create_config_dir(base_path: &str) -> Self {
        let mut app_config_dir = Path::new("app_config");
        let base_path = Path::new(base_path);

        if app_config_dir.exists() {
            warn!("Warning: The 'app_config' directory already exists at '{}'.", app_config_dir.display());
        }

        let config_dir = base_path.join(app_config_dir);
        fs::create_dir_all(&config_dir)
            .expect("Failed to create the 'app_config' directory");

        // Set the environment variable
        env_var_set(false);

        AppConfig {
            path: config_dir,
            env_var: format!("{}={}", "APP_CONFIG_PATH", &config_dir.display()),
        }
    }

    // Update the environment variable
    pub fn update_env_var(toggle: bool) -> Self {
        env_var_set(toggle);
        self
    }

    // Clear the environment variable and remove the directory if no longer needed
    pub fn cleanup() {
        env::remove("APP_CONFIG_PATH");
        fs::remove_dir(Path::new("app_config"));
    }
}

// Helper function to set the environment variable using atomic operations
fn env_var_set(toggle: bool) {
    let mut app_config_path = AtomicBool::new(true);
    if toggle {
        app_config_path.store(false, Ordering::Relaxed);
    }

    let current_value = app_config_path.load(Ordering::Acquire);
    if !current_value {
        env::set("APP_CONFIG_PATH", &format!("{}={}", "APP_CONFIG_PATH", Path::new("app_config").display()));
    }
}
