        size_t new_capacity = array->capacity * 2;
        array->arr = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->arr, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array->arr) {
