lib_module_t* lib_init(int max_packets) {
    lib_module_t *module = (lib_module_t*)malloc(sizeof(lib_module_t));
    pthread_mutex_init(&module->lock, NULL);
    module->max_packets = max_packets;
    module->current_packets = 0;
    module->packets = (packet_t*)malloc(max_packets * sizeof(packet_t));
    module->packet_priorities = (int*)malloc(max_packets * sizeof(int));
    module->retry_count = 0;
    return module;
}

// Function to process a packet
void lib_process_packet(lib_module_t* module, packet_t* packet) {
    pthread_mutex_lock(&module->lock);

    // Check if the packet has high priority and needs immediate processing
    if (packet->priority > module->packet_priorities[0]) {
        // Process the packet immediately
        process_high_priority_packet(packet);
    } else {
        // Add the packet to the list of packets for later processing
        int idx = 0;
        while (idx < module->current_packets && 
               module->packets[idx].priority >= packet->priority) {
            idx++;
        }
        if (idx < module->max_packets) {
            memcpy(&module->packets[idx], packet, sizeof(packet_t));
            module->packet_priorities[idx] = packet->priority;
            module->current_packets++;
