    pthread_mutex_lock(&da->mutex);
    free(da->arr);
    da->capacity = 0;
    da->size = 0;
    pthread_mutex_unlock(&da->mutex);
    free(da);
}

// Main function to demonstrate the use of the dynamic array library
int main() {
    DynamicArray* da = dynamic_array_init(10);

    // Add some elements to the array
    NFAPI_CRC_INDICATION_PDU_T elem1;
    // ... initialize elem1 ...
    dynamic_array_add(da, elem1);

    NFAPI_CRC_INDICATION_PDU_T elem2;
    // ... initialize elem2 ...
    dynamic_array_add(da, elem2);

    // Free the dynamic array
    dynamic_array_free(da);

    return 0;
}

