class LogHandler(web.Handler):
    def __init__(self):
        self.logger = create_rotating_file_logger('logs', level=logging.INFO)

    async def handle(self, request):
        try:
            # Handle the request here...
            if 200 <= request.status_code < 300:
                self.logger.info(f"GET {request.path} - {request.method}")
            elif 400 <= request.status_code < 500:
                self.logger.warning(f"Invalid request: {request.path} - {request.method}")
            else:
                self.logger.error(f"Error: {request.path} - {request.method}")
        except (ConnectionError, Timeout) as e:
            self.logger.error(f"Error connecting to API: {e}")

class AnalyticsHandler(web.Handler):
    async def handle(self, request):
        # Perform analytics tasks here...
        pass

class StatusUpdateHandler(web.RequestHandler):
    async def post(self, request):
        try:
            # Send the status update to the external APIs here...
            for api in ['api1', 'api2', 'api3']:
                response = await requests.post(f"{api}/status", json={'data': request.json()})
                if response.status_code == 200:
                    self.logger.info(f"Status updated successfully: {api}")
                else:
                    self.logger.error(f"Error updating status: {api} - {response.text}")
        except (ConnectionError, Timeout) as e:
            self.logger.error(f"Error connecting to API: {e}")

app = web.Application()
app.middlewares.append(LogHandler())
app.middlewares.append(AnalyticsHandler())
app.middlewares.append(StatusUpdateHandler())

if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    asyncio.run(app.run('0.0.0.0', port=8080))
