public class BatchProcessorWithErrorHandling {
    private static final int THREAD_POOL_SIZE = 10;
    private static final int MAX_INFLIGHT_REQUESTS_PER_WORKER = 5;

    public static void main(String[] args) throws Exception {
        // Initialize message broker
        KafkaConsumer<String, String> consumer = new KafkaConsumer<>("localhost:9092", "batch_processor_group");
        consumer.subscribe(Lists.newArrayList("jobs"));

        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);

        BlockingQueue<Runnable> taskQueue = new LinkedBlockingQueue<>();

        // Start processing jobs
        while (true) {
            String message = consumer.poll(100);
            if (message == null) {
                continue;
            }

            try {
                Job job = parseJob(message);

                for (Task task : job.getTasks()) {
                    TaskRunnable runnable = new TaskRunnable(task, executor, taskQueue);
                    executor.submit(runnable);
                }
            } catch (Exception e) {
                // Handle processing error
                handleProcessingError(job, e);
            }
        }
    }

    private static Job parseJob(String message) throws Exception {
