class Buffer {
public:
    Buffer(size_t capacity) : capacity_(capacity), buffer_() {}

    void put(const SensorData& data) {
        if (buffer_.size() >= capacity_) {
            // Handle overflow
            std::cout << "Buffer is full!" << std::endl;
            return;
        }
        buffer_.push(data);
    }

    SensorData get() {
        if (buffer_.empty()) {
