void add_interface(int RNTI) {
    pthread_mutex_lock(&mutex);
    if (num_interfaces >= MAX_INTERFACES) {
        printf("Maximum number of interfaces reached.\n");
        return;
    }
    records[num_records].info.RNTI = RNTI;
    pdus[num_records] = &NFAPI_CRC_INDICATION_PDU_T();
    num_interfaces++;
    num_records++;
    pthread_mutex_unlock(&mutex);
}

void update_record(int index, LTE_RRC_Capability_Info new_info) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < num_records) {
        records[index]->info = new_info;
    } else {
        printf("Invalid record index.\n");
    }
    pthread_mutex_unlock(&mutex);
}

