// WeatherService.js
const express = require('express');
const app = express();
const rateLimit = require('express-rate-limit');
const cache = require('memory-cache');
const weatherApi = 'YOUR_API_KEY';
const cities = ['New York', 'Los Angeles', 'Chicago', 'Houston'];
const apiConfig = {
  url: 'http://api.weather.com/city/{city}',
  timeout: 1000,
};

// Set up rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
});

app.use(limiter);

// Cache config
const cacheExpiration = 3600000; // 1 hour

// Set up caching
cache.clear();

// Define the weather service endpoint
app.get('/weather/:city', async (req, res) => {
  const city = req.params.city;
  if (!cities.includes(city)) {
    return res.status(404).send(`City ${city} not found`);
  }

  // Check cache first
  const cachedWeather = cache.get(`weather-${city}`);
  if (cachedWeather) {
    return res.json(cachedWeather);
  }

  try {
    // Fetch weather data from API
    const response = await fetch(`${apiConfig.url.replace('{city}', city)}`, {
      headers: { 'X-API-KEY': weatherApi },
      timeout: apiConfig.timeout,
    });
    const weatherData = await response.json();

    // Cache the result for 1 hour
    cache.set(`weather-${city}`, weatherData, cacheExpiration);

    return res.json(weatherData);
  } catch (error) {
    console.error(`Error fetching weather data for ${city}:`, error);
    return res.status(500).send('Failed to retrieve weather data');
  }
});

// Health check endpoint
app.get('/health', async (req, res) => {
  try {
    // Simulate a database query or API call
    await fetch('https://example.com/health-check');

    // If no errors occurred, return a healthy status
    return res.json({ status: 'healthy' });
  } catch (error) {
    // If an error occurs, return an unhealthy status
    console.error(`Error checking health:`, error);
    return res.status(500).json({ status: 'unhealthy' });
  }
});

// Start the service
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Weather service listening on port ${port}`);
});
```"]

