using namespace std;

class HTTP_RESPONSE_PDU_T {
public:
    int id;
    string data;
};

class CacheManager {
public:
    map<int, HTTP_RESPONSE_PDU_T> cache;
    mutex lock;

    void set(int id, const HTTP_RESPONSE_PDU_T& response) {
        unique_lock<mutex> ulock(lock);
        cache[id] = response;
    }

    HTTP_RESPONSE_PDU_T get(int id) {
        unique_lock<mutex> ulock(lock);
        if (cache.find(id) != cache.end()) {
            return cache.at(id);
        } else {
            throw runtime_error("Key not found");
        }
