// Function to update NIC statistics
void update_nic_stats(int interface_id, int packet_counts, int byte_counts) {
    pthread_mutex_lock(&nic_stats_mutex);
    nic_interfaces[interface_id].stats.packet_counts += packet_counts;
    nic_interfaces[interface_id].stats.byte_counts += byte_counts;
    nic_interfaces[interface_id].stats.timestamp = time(NULL);
    pthread_mutex_unlock(&nic_stats_mutex);
}

// Function to retrieve NIC statistics
NicStats get_nic_stats(int interface_id) {
    pthread_mutex_lock(&nic_stats_mutex);
    NicStats stats = nic_interfaces[interface_id].stats;
    pthread_mutex_unlock(&nic_stats_mutex);
    return stats;
}

