#include <iostream>
#include <vector>
#include <memory>

class SpatialIndex {
public:
    virtual ~SpatialIndex() {}
    virtual void insert(const double& x, const double& y) = 0;
    virtual bool query(const double& x, const double& y) = 0;
};

class Octree : public SpatialIndex {
private:
    struct Node {
        std::vector<Node*> children;
        int depth;
        double xMin, yMin, xMax, yMax;

        Node(int d, double minX, double minY, double maxX, double maxY)
            : depth(d), xMin(minX), yMin(minY), xMax(maxX), yMax(maxY) {}

        ~Node() {
            for (auto child : children) delete child;
        }
    };

public:
    Octree(double minX, double minY, double maxX, double maxY)
        : root_(std::make_shared<Node>(0, minX, minY, maxX, maxY)) {}

    void insert(const double& x, const double& y) {
        root_->insert(x, y);
    }

    bool query(const double& x, const double& y) {
        return root_->query(x, y);
    }

private:
    void Node::insert(double x, double y) {
        if (x < xMin || x > xMax || y < yMin || y > yMax)
            throw std::out_of_range("Point out of bounds");

        if (children.empty()) {
            int depth = ++depth;
            children.resize(8);

            for (int i = 0; i < 8; ++i) {
                double minX = xMin + (xMax - xMin) / 2.0 * (1 << (depth - 1));
                double minY = yMin + (yMax - yMin) / 2.0 * (1 << (depth - 1));
                double maxX = minX;
                double maxY = minY;

                if ((i & 1) == 0) {
                    maxX = minX + (xMax - xMin) / 2.0;
                    maxY = minY + (yMax - yMin) / 2.0;
                } else {
                    minX = maxX;
                    minY = maxY;
                    maxX += (xMax - xMin) / 2.0;
                    maxY += (yMax - yMin) / 2.0;
                }

                children[i] = std::make_shared<Node>(depth, minX, minY, maxX, maxY);
            }
        }

        for (int i = 0; i < 8; ++i) {
            if (children[i]->query(x, y)) {
                return children[i]->insert(x, y);
            }
        }
    }

    bool Node::query(double x, double y) const {
        if (x < xMin || x > xMax || y < yMin || y > yMax)
            return false;

        for (int i = 0; i < children.size(); ++i) {
            if (children[i]->query(x, y)) {
                return true;
            }
        }

        return true;
    }
};

std::unique_ptr<SpatialIndex> createSpatialIndex() {
    // Use spatial indexing library to create an index
    // For example:
    return std::make_unique<Octree>(0.0, 0.0, 10.0, 10.0);
}
