    { path: '/api/v2', target: lbConfig['on-premises'] },
    { path: '/v1/api', target: lbConfig['legacy'] }
  ],
  'intelligent-failover': [
    {
      path: '/api/v1',
      fallback: lbConfig['on-premises']
