// React Frontend Code
import React, { useState, useEffect } from 'react';
import axios from 'axios';

function ChatApp() {
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');

  useEffect(() => {
    // Make API request to the Node.js server for initial message list
    axios.get('/api/messages')
      .then((response) => {
        setMessages(response.data);
      })
      .catch((error) => {
        console.error(error);
      });
  }, []);

  const handleSendMessage = () => {
    // Make API request to the Node.js server to send a new message
    axios.post('/api/messages', { text: newMessage })
      .then(() => {
        setNewMessage('');
      })
      .catch((error) => {
        console.error(error);
      });
  };

  return (
    <div>
      <ul>
        {messages.map((message) => (
          <li key={message.id}>{message.text}</li>
        ))}
      </ul>
      <input
        type="text"
        value={newMessage}
        onChange={(event) => setNewMessage(event.target.value)}
      />
      <button onClick={handleSendMessage}>Send</button>
    </div>
  );
}

// Socket.IO Code for Real-time Messaging
io.on('connection', (socket) => {
  // Handle new message arrival from other users
  socket.on('new-message', (message) => {
    console.log(`Received new message: ${message.text}`);
    // Update the UI with the new message
    setMessages((prevMessages) => [...prevMessages, message]);
  });

  // Handle user disconnection
  socket.on('disconnect', () => {
    console.log('User disconnected');
  });
});

