<?php

class TokenGenerator {
    private $oauthClient;
    private $characterSet;
    private $length;

    public function __construct($oauthClient, $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', $length = 32) {
        $this->oauthClient = $oauthClient;
        $this->characterSet = $characterSet;
        $this->length = $length;
    }

    public function generateToken() {
        $token = '';
        for ($i = 0; $i < $this->length; $i++) {
            $token .= rand(1, strlen($this->characterSet) - 1) === 1 ? $this->characterSet[rand(0, strlen($this->characterSet) - 1)] : $this->characterSet[strrand(0, strlen($this->characterSet) - 1)];
        }
        return $token;
    }

    public function verifyToken($token) {
        try {
            $response = json_decode($this->oauthClient->verifyToken($token), true);
            if (isset($response['verified']) && $response['verified'] === true) {
                return true;
            } else {
                return false;
            }
        } catch (Exception $e) {
            // Handle exception
            return false;
        }
    }

    public function refreshToken($token) {
        try {
            $response = json_decode($this->oauthClient->refreshToken($token), true);
            if (isset($response['access_token']) && isset($response['expires_in'])) {
                return array('token' => $response['access_token'], 'expires_in' => $response['expires_in']);
            } else {
                return false;
            }
        } catch (Exception $e) {
            // Handle exception
            return false;
        }
    }

    public function getOAuthClient() {
        return $this->oauthClient;
    }

    public function setOAuthClient($oauthClient) {
        $this->oauthClient = $oauthClient;
    }
}

