        DeviceState new_device_state;
        sscanf(line, "%d %s", &new_device_state.id, new_device_state.state);
        device_state_list[count] = new_device_state;
        count++;
    }

    fclose(fp);

    // API endpoint logic integration
    char *response = "{\"device_states\": [";
    for (int i = 0; i < count - 1; i++) {
        response = strcat(response, "{\"id\": ");
        itoa(device_state_list[i].id, (char *)malloc(10), 10);
        response = strcat(response, "]");
        response = strcat(response, ",");
    }
    if (count > 0) {
        response = strcat(response, "{\"id\": ");
        itoa(device_state_list[count - 1].id, (char *)malloc(10), 10);
        response = strcat(response, "]");
    }
    response = strcat(response, "]}");

    printf("%s\n", response);

    // freeing dynamically allocated memory
    for (int i = 0; i < count; i++) {
        free((void *)device_state_list[i].state);
    }
}
