class AudioStream {
public:
    virtual void Start() = 0;
    virtual void Stop() = 0;
    virtual void SendData(const std::string& data) = 0;
};

class AudioSource {
public:
    virtual std::unique_ptr<AudioStream> CreateAudioStream() = 0;
};

class AudioProcessor {
public:
    AudioProcessor(AudioSource& source, int numStreams)
        : source_(source), numStreams_(numStreams) {}

    void Start() {
        for (int i = 0; i < numStreams_; ++i) {
            std::unique_ptr<AudioStream> stream = source_.CreateAudioStream();
            streams_.push_back(std::move(stream));
            stream->Start();
        }
    }

    void Stop() {
        for (auto& stream : streams_) {
            stream->Stop();
        }
    }

    void SendData(const std::string& data) {
        for (auto& stream : streams_) {
            stream->SendData(data);
        }
    }

private:
    AudioSource& source_;
    int numStreams_;
    std::vector<std::unique_ptr<AudioStream>> streams_;
};

