import json

def validate_oauth_token(token):
    required_fields = ['access_token', 'expires_in', 'token_type']
    optional_fields = ['refresh_token']

    if not isinstance(token, dict):
        return False

    if not all(field in token for field in required_fields):
        return False

    if 'token_type' not in token or token['token_type'] != 'Bearer':
        return False

    if 'expires_in' not in token or not isinstance(token['expires_in'], int) or token['expires_in'] <= 0:
        return False

    # Optional fields validation
    for field in optional_fields:
        if field in token and not isinstance(token[field], str):
            return False

    return True
