**Python function: validate_token**
```python
import json

def validate_token(token):
    try:
        token_data = json.loads(token)
        if 'access_token' not in token_data or 'expires_in' not in token_data or 'token_type' not in token_data:
            return False
        if token_data['token_type'] != 'Bearer':
            return False
        if not isinstance(token_data['expires_in'], int) or token_data['expires_in'] <= 0:
            return False
        if 'refresh_token' in token_data and not isinstance(token_data['refresh_token'], str):
            return False
        return True
    except json.JSONDecodeError:
        return False
```

