  async.waterfall([
    (callback) => {
      // Validate transaction data
      const transaction = req.body;
      if (!transaction.amount || !transaction.currency || !transaction.payment_gateway) {
        callback(new Error('Invalid transaction data'));
      } else {
        callback(null);
      }
    },
    (error, callback) => {
      if (error) {
        res.status(400).send({ error: 'Invalid transaction data' });
        return;
      }

      // Check for fraudulent transactions
      const isFraudulent = detectFraud(req.body);
      if (isFraudulent) {
        res.status(403).send({ error: 'Fraudulent transaction detected' });
        return;
      }

      // Process transaction through payment gateway
      const paymentGateway = paymentGateways[req.body.payment_gateway];
      axios.post(paymentGateway.endpoint, req.body)
        .then((response) => {
          callback(null);
        })
        .catch((error) => {
          callback(error);
        });
    },
