        std::lock_guard<std::mutex> lock(m_mutex);

        // Iterate through each session update in the batch
        for (const auto& update : updates) {
            // Get the session ID and data from the update
            int sessionId = update.sessionId;
            const char* data = update.data;

            // Check if the session ID exists in the cache
            if (!m_cache.count(sessionId)) {
                // Create a placeholder for the new session (or fail the request)
