class RingBuffer {
public:
    explicit RingBuffer(size_t initialCapacity) : capacity_(initialCapacity), size_(0),
        buffer_((std::vector<int>(capacity_, 0))) {}

    void append(int val) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (size_ >= capacity_) {
            // Handle buffer overflow
            buffer_.erase(buffer_.begin());
            size_ = capacity_;
        }
        buffer_[size_++] = val;
    }

    int dequeue() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (!hasData()) {
            // Handle empty buffer
            return -1; // or throw an exception, whichever fits your use case
        }
        --size_;
        return buffer_[0];
    }

    bool hasData() const {
        return size_ > 0;
    }

private:
    std::mutex mutex_;
    std::condition_variable cv_;
    std::atomic<size_t> capacity_;
    std::atomic<size_t> size_;
    std::vector<int> buffer_;
