        NetworkConfig* config = get_current_config();
        for (int i = 0; i < num_nodes; i++) {
            Node node = nodes[i];
            if (json_object_get_int(jobj, "x") != node.x) {
                // Update the node's x-coordinate
                node.x = json_object_get_int(jobj, "x");
            }
            if (json_object_get_int(jobj, "y") != node.y) {
                // Update the node's y-coordinate
                node.y = json_object_get_int(jobj, "y");
            }
        }

        // Save the updated configuration to disk
        save_config(config);
    } else {
        // If we didn't reach a consensus, log an error and exit
        printf("Error: unable to reach a consensus\n");
        exit(1);
    }

    return NULL;
}

int main() {
    // Initialize the json object
    json_object *jobj = json_object_new();

    if (!jobj) return -1;

    // Parse the JSON file and convert it to internal format
    NetworkConfig* config = parse_json("config.json");

    if (!config) return -2;

    // Validate the JSON structure and convert it to internal format
