Config* parse_config(char* filename) {
    // Read the JSON file
    FILE* file = fopen(filename, "r");
    if (!file) {
        return NULL;
    }

    // Parse the JSON object
    json_object* config = json_object_from_file(file);
    fclose(file);

    // Validate the configuration
    if (!config || !json_object_object_get_ex(config, "nodes", &config)) {
        return NULL;
    }

    // Get the nodes from the configuration
    int num_nodes = json_object_array_length(config);
    Node* nodes = malloc(num_nodes * sizeof(Node));
    for (int i = 0; i < num_nodes; i++) {
        Node node = (Node)json_object_get_array(config)[i];
        // Convert JSON object to Node struct
        node.id = strdup(json_object_get_string(node.config->id));
        node.capacity = json_object_get_int(node.config->capacity);
    }

    Config* result = malloc(sizeof(Config));
    result->config = config;
    result->nodes = nodes;
    result->num_nodes = num_nodes;
    return result;
}

