#include <unordered_map>

// Function to identify and process contiguous sensor readings
std::vector<int> processSensorReadings(const std::vector<int>& readings) {
    // Create a map to store the difference between consecutive readings
    std::unordered_map<int, int> diffMap;

    for (int i = 1; i < readings.size(); ++i) {
        if (readings[i] - readings[i-1] > 1) {
            // Flag irregular interval and skip it
            continue;
        }

        // Calculate the difference between consecutive readings
        int diff = readings[i] - readings[i-1];

        // Update the map with the difference
        if (!diffMap.count(diff)) {
            diffMap[diff] = 0;
        }
        ++diffMap[diff];
    }

    return readings;
}

// In-place batch processing function
void processBatch(std::vector<int>& data) {
    int sum = 0;

    // Process the batch in place
    for (auto& reading : data) {
        sum += reading;
    }

    // Normalize the data
    for (auto& reading : data) {
        reading = reading / sum;
    }
}

int main() {
    std::vector<int> readings = {1, 2, 3, 4, 5};

    processSensorReadings(readings);

    std::vector<int> batchData = {10, 20, 30};
    processBatch(batchData);

    return 0;
}

