// Real-Time Data Processing
bool findDisjointTimestampPairs(const std::vector<long>& timestamps, int threshold) {
    std::list<std::pair<long, long>> pairs;
    for (size_t i = 0; i < timestamps.size() - 1; ++i) {
        if (timestamps[i + 1] - timestamps[i] > 1) {
            // Anomalous interval detected
            if (abs(timestamps[i + 1] - timestamps[i]) > threshold) {
                std::cout << "Anomalous interval found: [" << timestamps[i] << ", " << timestamps[i + 1] << ")" << std::endl;
            }
        } else {
            pairs.push_back({timestamps[i], timestamps[i + 1]});
        }
    }
    return !pairs.empty();
}

// String Manipulation
void insertStringAfterTarget(const std::forward_list<std::string>& list, const std::string& target, const std::string& newStr) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == target) {
            list.insert_after(it, newStr);
            break;
        }
        ++it;
    }
    if (!list.empty() && *it != target) {
        list.insert_after(it, newStr);
    }
}

void bulkUpdateStrings(const std::forward_list<std::string>& list, const std::vector<std::pair<std::string, std::string>>& updates) {
    for (const auto& update : updates) {
        insertStringAfterTarget(list, update.first, update.second);
    }
}

