    if (!component->pdus) {
        free(component);
        return NULL;
    }

    component->size = initial_capacity;
    pthread_mutex_init(&component->lock, NULL);

    return component;
}

// Dynamically allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
NFAPICRCIndicationPDUComponent* realloc_nfapicrc_indication_pdu_component(NFAPICRCIndicationPDUComponent* component, size_t new_size) {
    if (component->size >= new_size) return component;

    // Allocate memory for the new array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPICRCIndicationPDUComponent* new_component = (NFAPICRCIndicationPDUComponent*)malloc(sizeof(NFAPICRCIndicationPDUComponent));
    if (!new_component) return NULL;

    // Copy existing data to the new component
    memcpy(new_component->pdus, component->pdus, component->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(component->pdus);

    new_component->pdus = (NFAPI_CRC_INDICATION_PDU_T*)realloc(new_component->pdus, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_component->pdus) {
        free(new_component);
        return NULL;
    }

    // Update the size and lock
    new_component->size = new_size;
    pthread_mutex_init(&new_component->lock, NULL);

    return new_component;
}

