// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int id;
    char data[1024];
} NFAPI_CRC_INDICATION_PDU_T;

// Array to store NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* puds = NULL;
int pdu_count = 0;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new PDU to the array
void add_pdu(int id, char* data) {
    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->id = id;
    strcpy(pdu->data, data);
    puds = realloc(puds, (pdu_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    puds[pdu_count] = pdu;
    pdu_count++;
    pthread_mutex_unlock(&mutex);
}

// Function to remove a PDU from the array
void remove_pdu(int id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < pdu_count; i++) {
        if (puds[i]->id == id) {
            free(puds[i]);
            memmove(&puds[i], &puds[i + 1], (pdu_count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            pdu_count--;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to print all PDUs
void print_puds() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < pdu_count; i++) {
        printf("PDU %d: ID=%d, Data=%s\n", i, puds[i]->id, puds[i]->data);
    }
    pthread_mutex_unlock(&mutex);
}

// Thread function to concurrently process PDUs
void* process_pdu(void* arg) {
    int tid = (int)arg;
    for (int i = 0; i < pdu_count; i++) {
        if (puds[i]->id % 10 == tid) { // Process only certain PDUs based on the thread ID
            printf("Thread %d processing PDU %d\n", tid, puds[i]->id);
            // Perform operations on the PDU here
        }
    }
    return NULL;
}

int main() {
    pthread_t threads[10];

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, process_pdu, (void*)i);
    }

    add_pdu(1, "PDU 1");
    add_pdu(2, "PDU 2");
    add_pdu(3, "PDU 3");

    print_puds();

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

