    // Method to identify disjoint consecutive timestamp pairs within an array
    std::vector<std::pair<long long, long long>> findDisjointConsecutivePairs(const std::vector<long long>& timestamps) {
        std::vector<std::pair<long long, long long>> result;
        for (size_t i = 0; i < timestamps.size() - 1; ++i) {
            if (timestamps[i + 1] - timestamps[i] == 1) {
                result.emplace_back(timestamps[i], timestamps[i + 1]);
            }
        }
        return result;
    }

