    SensorData(const std::string& id, const std::vector<float>& readings) : 
        deviceID(id), readings(readings) {}
};

class DataProcessor {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> running(true);

public:
    void process(SensorData data) {
        // processing logic here
    }

    void startProcessing() {
        while (running) {
            SensorData data;
            // retrieve data from queue
            if (!dataQueue.empty()) {
                data = dataQueue.front();
                dataQueue.pop();
                process(data);
            }
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !running || !dataQueue.empty(); });
        }
    }

private:
    std::queue<SensorData> dataQueue;
};

class DataIngestor {
