        while (running) {
            // receive and process incoming data
        }
    }

private:
    DataProcessor dataProcessor;
};

class DataAggregator {
public:
    void aggregate(const SensorData& data) {
        // aggregation logic here
    }

    void startAggregation() {
        while (running) {
            SensorData data;
            // retrieve data from queue
            if (!dataQueue.empty()) {
                data = dataQueue.front();
                dataQueue.pop();
                aggregate(data);
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

private:
    std::queue<SensorData> dataQueue;
};

int main() {
    DataIngestor ingester;
    DataProcessor processor;
    DataAggregator aggregator;

    // start ingestion and processing threads
    std::thread ingestThread(&DataIngestor::startIngestion, &ingester);
    std::thread processThread(&DataProcessor::startProcessing, &processor);

    // start aggregation thread
    std::thread aggThread(&DataAggregator::startAggregation, &aggregator);

    // wait for threads to finish
    ingestThread.join();
    processThread.join();
    aggThread.join();

    return 0;
}
