['```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to dynamically allocate and initialize the linked list
Node* createLinkedList(int numNodes) {
    Node* head = NULL;
    for (int i = 0; i < numNodes; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            printf("Memory allocation failed!\n");
            return NULL;
        }

        // Initialize node data with random CRCFLAG value
        srand(time(NULL));
        int crcFlag = rand() % 2;
        NFAPI_CRC_INDICATION_PDU_T data = {
            i,         // RX_UE_INFORMATION_TAG
            i + 1,     // RNTI
            i * 10,    // CRC_INDICATION_REL8_TAG
            crcFlag     // CRCFLAG
        };
        newNode->data = data;

        if (!head) {
            head = newNode;
        } else {
            Node* temp = head;
            while (temp->next) {
                temp = temp->next;
            }
            temp->next = newNode;
        }
    }
    return head;
}

// Function to update the linked list with new data
void updateLinkedList(Node** head, int numUpdates) {
    for (int i = 0; i < numUpdates; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            printf("Memory allocation failed!\n");
            return;
        }

        // Update node data with new values
        NFAPI_CRC_INDICATION_PDU_T data = {
            i + 1,         // RX_UE_INFORMATION_TAG
            i * 2 + 1,     // RNTI
            (i * 10) + 5,  // CRC_INDICATION_REL8_TAG
            rand() % 2      // CRCFLAG
        };
        newNode->data = data;

        if (!(*head)) {
            *head = newNode;
        } else {
            Node* temp = *head;
            while (temp->next) {
                temp = temp->next;
            }
            temp->next = newNode;
        }
    }
}

// Function to print the linked list
void printLinkedList(Node* head) {
    Node* temp = head;
    while (temp) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               temp->data.RX_UE_INFORMATION_TAG,
               temp->data.RNTI,
               temp->data.CRC_INDICATION_REL8_TAG,
               temp->data.CRCFLAG);
        temp = temp->next;
    }
}

int main() {
    Node* head = createLinkedList(1000);
    printLinkedList(head);

    updateLinkedList(&head, 500);
    printLinkedList(head);

    return 0;
}
