    logging_utilty->destinations[logging_utilty->num_destinations] = file_destination;
    logging_utilty->num_destinations++;

    // Start the logging utility
    pthread_create(&pthread_id, NULL, log_handler, (void *)logging_utility);

    return 0;
}

void log_message(LoggingUtility *logging_utility, int severity, const char *message) {
    // Check the log level and skip if it's not enabled
    if (severity > LOG_SEVERITY_INFO && !is_enabled()) return;

    // Get the current timestamp and process ID
    time_t timestamp = time(NULL);
    pid_t pid = getpid();

    // Format the log message with contextual information
    char buffer[1024];
    sprintf(buffer, "%ld-%d: %s", timestamp, pid, message);

    // Log the message to each destination
