// Define the structure for FrameMetadata
typedef struct {
    unsigned char* packet_data; // Pointer to raw packet data
    long timestamp; // Timestamp of the frame
    char PacketType; // Type of the packet (e.g., ARP, TCP, UDP)
    char SourceMAC[6]; // MAC address of the source device
    char DestinationMAC[6]; // MAC address of the destination device
} FrameMetadata;

// Define a linked list structure for managing FrameMetadata
typedef struct {
    FrameMetadata* data; // Pointer to FrameMetadata
    struct Node* next; // Next node in the linked list
} Node;

// Function to add a new frame to the linked list
void add_frame(FrameMetadata* frame, Node** head) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = frame;
    new_node->next = (*head);
    (*head) = new_node;
}

// Function to update an existing frame in the linked list based on SourceMAC or DestinationMAC
void update_frame(char* mac_address, Node** head) {
    Node* current = *head;
    while (current != NULL) {
        if (strcmp(current->data->SourceMAC, mac_address) == 0 || strcmp(current->data->DestinationMAC, mac_address) == 0) {
            // Update the frame's data here
            printf("Updated frame with MAC address %s\n", mac_address);
            return;
        }
        current = current->next;
    }
    printf("No frame found with MAC address %s\n", mac_address);
}

// Function to remove a frame from the linked list based on SourceMAC or DestinationMAC
void remove_frame(char* mac_address, Node** head) {
    Node* prev = NULL;
    Node* current = *head;
    while (current != NULL) {
        if (strcmp(current->data->SourceMAC, mac_address) == 0 || strcmp(current->data->DestinationMAC, mac_address) == 0) {
            if (prev == NULL) {
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
    printf("No frame found with MAC address %s\n", mac_address);
}

// Function to print the linked list of frames
void print_frames(Node* head) {
    while (head != NULL) {
        FrameMetadata* frame = head->data;
        printf("Packet data: %p, Timestamp: %ld, Packet type: %c, Source MAC: %s, Destination MAC: %s\n", frame->packet_data, frame->timestamp, frame->PacketType, frame->SourceMAC, frame->DestinationMAC);
        head = head->next;
    }
}

int main() {
    Node* head = NULL;

    // Add frames to the linked list
    FrameMetadata* frame1 = (FrameMetadata*)malloc(sizeof(FrameMetadata));
    frame1->packet_data = "raw packet data 1";
    frame1->timestamp = 1643723400;
    frame1->PacketType = 'A';
    strcpy(frame1->SourceMAC, "00:11:22:33:44:55");
    strcpy(frame1->DestinationMAC, "00:66:77:88:99:AA");
    add_frame(frame1, &head);

    FrameMetadata* frame2 = (FrameMetadata*)malloc(sizeof(FrameMetadata));
    frame2->packet_data = "raw packet data 2";
    frame2->timestamp = 1643723410;
    frame2->PacketType = 'B';
    strcpy(frame2->SourceMAC, "00:33:44:55:66:77");
    strcpy(frame2->DestinationMAC, "00:11:22:33:44:55");
    add_frame(frame2, &head);

    // Update and remove frames
    update_frame("00:11:22:33:44:55", &head);
    remove_frame("00:33:44:55:66:77", &head);

    // Print the linked list of frames
    print_frames(head);

    return 0;
}
