// FrameMetadata structure
typedef struct {
    void* packet_data;
    long timestamp;
    char PacketType;
    char SourceMAC[18];
    char DestinationMAC[18];
} FrameMetadata;

// Linked list node
typedef struct Node {
    FrameMetadata metadata;
    struct Node* next;
} Node;

// Dynamic linked list
typedef struct {
    Node* head;
    int size;
} LinkedList;

// Function prototypes
LinkedList* create_linked_list();
void add_frame(LinkedList*, FrameMetadata);
FrameMetadata* get_frame_by_mac(LinkedList*, char*, char*);
int remove_frame_by_mac(LinkedList*, char*, char*);
int filter_frames(LinkedList*, void (*)(FrameMetadata*));
Node* create_node(FrameMetadata);

// Create a new linked list
LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->size = 0;
    return list;
}

// Add a frame to the linked list
void add_frame(LinkedList* list, FrameMetadata metadata) {
    Node* new_node = create_node(metadata);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->size++;
}

// Get a frame by MAC address
FrameMetadata* get_frame_by_mac(LinkedList* list, char* source_mac, char* destination_mac) {
    Node* current = list->head;
    while (current != NULL) {
        if (!strcmp(current->metadata.SourceMAC, source_mac) && !strcmp(current->metadata.DestinationMAC, destination_mac)) {
            return &current->metadata;
        }
        current = current->next;
    }
    return NULL;
}

// Remove a frame by MAC address
int remove_frame_by_mac(LinkedList* list, char* source_mac, char* destination_mac) {
    Node* previous = NULL;
    Node* current = list->head;
    while (current != NULL) {
        if (!strcmp(current->metadata.SourceMAC, source_mac) && !strcmp(current->metadata.DestinationMAC, destination_mac)) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            list->size--;
            return 1;
        }
        previous = current;
        current = current->next;
    }
    return 0;
}

// Filter frames using a callback function
int filter_frames(LinkedList* list, void (*filter_callback)(FrameMetadata*)) {
    Node* current = list->head;
    while (current != NULL) {
        if (!(*filter_callback)(&current->metadata)) {
            remove_frame_by_mac(list, current->metadata.SourceMAC, current->metadata.DestinationMAC);
        }
        current = current->next;
    }
}

// Create a new linked list node
Node* create_node(FrameMetadata metadata) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->metadata = metadata;
    node->next = NULL;
    return node;
}
