// Define the structure for FrameMetadata
typedef struct {
    unsigned char *packet_data;
    int packet_length;
    long timestamp;
    enum PacketType packet_type;
    unsigned char source_mac[6];
    unsigned char destination_mac[6];
} FrameMetadata;

// Define the linked list node structure
typedef struct Node {
    FrameMetadata metadata;
    struct Node *next;
} Node;

// Define the dynamic linked list structure
typedef struct {
    Node *head;
    pthread_mutex_t lock;
} DynamicLinkedList;

// Function to create a new linked list node
Node* create_node(FrameMetadata metadata) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->metadata = metadata;
    new_node->next = NULL;
    return new_node;
}

// Function to add a new frame to the linked list
void add_frame(DynamicLinkedList *list, FrameMetadata metadata) {
    Node *new_node = create_node(metadata);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to remove the first frame from the linked list
void remove_frame(DynamicLinkedList *list) {
    if (list->head == NULL) return;
    Node *temp = list->head;
    list->head = temp->next;
    free(temp);
}

// Function to print the linked list
void print_list(DynamicLinkedList *list) {
    Node *current = list->head;
    while (current != NULL) {
        printf("Timestamp: %ld, Packet Type: %d, Source MAC: %02x:%02x:%02x:%02x:%02x:%02x, Destination MAC: %02x:%02x:%02x:%02x:%02x:%02x\n",
               current->metadata.timestamp,
               current->metadata.packet_type,
               current->metadata.source_mac[0],
               current->metadata.source_mac[1],
               current->metadata.source_mac[2],
               current->metadata.source_mac[3],
               current->metadata.source_mac[4],
               current->metadata.source_mac[5],

               current->metadata.destination_mac[0],
               current->metadata.destination_mac[1],
               current->metadata.destination_mac[2],
               current->metadata.destination_mac[3],
               current->metadata.destination_mac[4],
               current->metadata.destination_mac[5]);
        current = current->next;
    }
}

// Function to filter the linked list based on user-defined rules
void filter_list(DynamicLinkedList *list, enum PacketType packet_type) {
    Node *current = list->head;
    while (current != NULL) {
        if (current->metadata.packet_type == packet_type) {
            add_frame(list, current->metadata);
        }
        current = current->next;
    }
}

// Function to start a new thread for processing the linked list
void* process_list(void* arg) {
    DynamicLinkedList *list = (DynamicLinkedList *)arg;
    Node *current = list->head;
    while (current != NULL) {
        // Process the frame metadata
        current = current->next;
    }
    return NULL;
}

