    FrameMetadata metadata2 = {"packet_data2", 256, 1643723401, PT_IPV6, {0x00, 0x11, 0x22, 0x33, 0x44, 0x55}, {0x66, 0x77, 0x88, 0x99, 0xaa, 0xbb}};
    add_frame(&list, metadata1);
