// Semaphore Management System
class Semaphore {
public:
    Semaphore(int value) : value_(value), mutex_(), cv_() {}

    void wait() {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait([this] { return value_ > 0; });
        --value_;
    }

    void signal() {
        std::lock_guard<std::mutex> lock(mutex_);
        ++value_;
        cv_.notify_one();
    }

private:
