        this.vertx = vertx;
        cacheManager = new CacheManager();
        mapper = new ObjectMapper(new JsonSchemaModule());
    }

    public Router createRouter() {
        Router router = Router.router(vertx);
        router.route(HttpMethod.GET, "/config").handler(this::getConfig);
        return router;
    }

    private void getConfig(HttpServerRequest request, HttpServerResponse response) {
        String configId = request.queryParams().get("id");
        if (StringUtils.isEmpty(configId)) {
            response.setStatusCode(400).end("Invalid configuration ID");
            return;
        }
        try {
            JsonNode config = mapper.readTree(new File(cacheManager.getConfigFile()));
            response.putHeader("Content-Type", "application/json").end(config.toString());
        } catch (Exception e) {
            LOG.error("Error loading configuration: {}", e.getMessage(), e);
            response.setStatusCode(500).end("Failed to load configuration");
        }
    }

    public void start(int port) {
        vertx.createHttpServer().requestHandler(router -> router.route().handler(this::handleRequest)).listen(port, result -> {
            if (result.succeeded()) {
                LOG.info("Config service started on port {}", port);
            } else {
                LOG.error("Failed to start config service: {}", result.cause());
            }
        });
    }

    private void handleRequest(HttpServerRequest request) {
        request.handler(body -> {
            try {
                ConfigData data = mapper.readValue(body.asByteArray(), ConfigData.class);
                cacheManager.updateConfig(data);
            } catch (IOException e) {
                LOG.error("Error parsing configuration update: {}", e.getMessage(), e);
            }
        });
    }

    public static class CacheManager {
        private File cacheFile;

        public void setCacheFile(File file) {
            this.cacheFile = file;
        }

        public File getConfigFile() {
            return cacheFile;
        }

        public void updateConfig(ConfigData data) {
            try {
                Files.write(Files.readAllBytes(cacheFile.toPath()), mapper.writeValueAsBytes(data));
            } catch (IOException e) {
                LOG.error("Error updating configuration: {}", e.getMessage(), e);
            }
        }
    }

    public static class ConfigData {
