        $this->logger = new Logger('app');
        $this->logger->pushHandler(new RotatingFileHandler('app.log', 5 * 1024 * 1024, Logger::WARNING));
    }

    public function loadConfig(): void {
        $client = new Client(['base_uri' => 'https://api.configprovider.com/v1/']);
        try {
            $response = $client->get('settings', ['timeout' => 15]);
            if ($response->getStatusCode() == 200) {
                $this->config = json_decode($response->getBody(), true);
            } else {
                $this->logger->warning('Failed to load config from API');
                // Fallback to local cache
                $this->loadLocalConfig();
            }
        } catch (RequestException $e) {
            $this->logger->error('Error loading config: ' . $e->getMessage());
            // Fallback to local cache
            $this->loadLocalConfig();
        }
    }

    private function loadLocalConfig(): void {
        if (!file_exists('config.json')) {
            return;
        }
        $this->config = json_decode(file_get_contents('config.json'), true);
    }

    public function getConfig(): array {
        return $this->config;
    }

    public function setConfig(array $config): void {
        $this->config = $config;
    }

    public function getEnvironment(): string {
        if (!empty($_SERVER['HTTP_ENVIRONMENT'])) {
            return $_SERVER['HTTP_ENVIRONMENT'];
        }
        if (isset($argv[1]) && isset($argv[2])) {
            return $argv[1];
        }
        return 'dev';
    }

    public function log(string $message, int $level = Logger::WARNING): void {
        $this->logger->log($level, $message);
