                // Update config and restart application
                break;
            case 'check':
                // Show current environment settings
                break;
            default:
                echo "Invalid command\n";
                exit;
        }
    }

    public function setMaxOpenFiles(int $max): void {
        ini_set('open_files_limit', $max);
    }

    public function setMaxDbConnections(int $max): void {
        mysqli_max_connections($max);
    }
}

