from rq import Queue
from redis import Redis

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'postgresql://user:password@host:port/dbname'
db = SQLAlchemy(app)

cache = Cache(app, config={'CACHE_TYPE': 'Redis', 'CACHE_REDIS_URL': 'redis://localhost:6379/0'})

