@app.route('/employees', methods=['GET'])
def get_employees():
    employees = Employee.query.all()
    return jsonify([employee.to_dict() for employee in employees])

@app.route('/employees/<int:supervisor_id>', methods=['GET'])
def get_employees_by_supervisor(supervisor_id):
    employees = Employee.query.filter(Employee.supervisor_id == supervisor_id).all()
    return jsonify([employee.to_dict() for employee in employees])

@app.route('/employees', methods=['POST'])
def create_employee():
    data = request.get_json()
    employee = Employee(**data)
    db.session.add(employee)
    db.session.commit()
    return jsonify({'message': 'Employee created successfully'})

@app.route('/employees/<int:employee_id>', methods=['PUT'])
def update_employee(employee_id):
    employee = Employee.query.get(employee_id)
    data = request.get_json()
    for key, value in data.items():
        setattr(employee, key, value)
    db.session.commit()
    return jsonify({'message': 'Employee updated successfully'})

@app.route('/employees/<int:employee_id>', methods=['DELETE'])
def delete_employee(employee_id):
    employee = Employee.query.get(employee_id)
    if employee is not None:
        db.session.delete(employee)
        db.session.commit()
        return jsonify({'message': 'Employee deleted successfully'})
    else:
        return jsonify({'message': 'Employee not found'}), 404

@app.errorhandler(404)
