class MemoryPool:
    def __init__(self):
        self.memory_map = {}
        self.lock = asyncio.Lock()

    async def allocate(self, size: int) -> memoryview:
        with await self.lock:
            if size not in self.memory_map:
                self.memory_map[size] = []
            while True:
                mem_view = memoryview(bytearray(size))
                if mem_view not in self.memory_map[size]:
                    return mem_view
                await asyncio.sleep(0.1)

    async def free(self, mem_view: memoryview) -> None:
        with await self.lock:
            for size, views in self.memory_map.items():
                if mem_view in views:
                    views.remove(mem_view)
                    break
