public class LoggingFramework {

    public static enum LogLevel {
        DEBUG, INFO, WARN, ERROR, FATAL
    }

    private static class LoggerConfig {
        private String logLevel;
        private List<String> sinks;
        private boolean async;
        private int bufferTimeout;

        public LoggerConfig(String logLevel, List<String> sinks, boolean async, int bufferTimeout) {
            this.logLevel = logLevel;
            this.sinks = sinks;
            this.async = async;
            this.bufferTimeout = bufferTimeout;
        }
    }

    private static class LogBuffer {
        private final ExecutorService executor;
        private final Map<LogLevel, List<String>> buffer;

        public LogBuffer(int bufferSize) {
            this.executor = Executors.newCachedThreadPool();
            this.buffer = new HashMap<>();
            for (LogLevel level : LogLevel.values()) {
                buffer.put(level, new ArrayList<>(bufferSize));
            }
        }

        public void log(LogLevel level, String message) {
            buffer.get(level).add(message);
        }

