public class HttpRequestService {
    public HttpResponse executeRequest(HttpGet request, int maxRetries) throws IOException {
        int retries = 0;
        while (retries < maxRetries) {
            try {
                return request.execute();
            } catch (IOException e) {
                if (retries >= maxRetries - 1) { // Reached the maximum number of retries
                    throw e; // Re-throw the exception
                }
                // Retry with exponential backoff
                Thread.sleep(retries * 100);
            }
        }
    }

    public HttpResponse fallbackRequest(HttpGet request, int maxFailsafeRetries) throws IOException {
        int failsafeRetries = 0;
        while (failsafeRetries < maxFailsafeRetries) {
            try {
                return request.execute();
            } catch (IOException e) {
                if (failsafeRetries >= maxFailsafeRetries - 1) { // Reached the maximum number of failsafe retries
