using System;
using System.IO;
using System.Threading;
using System.Security.Cryptography;

namespace Sha256Library
{
    public class Sha256Hasher
    {
        private readonly FileStream _fileStream;
        private readonly HashAlgorithm _hashAlgorithm;

        public Sha256Hasher(string filePath)
        {
            _fileStream = File.OpenRead(filePath);
            _hashAlgorithm = SHA256.Create();
        }

        public string ComputeHash()
        {
            using (var hashStream = new MemoryStream())
            {
                var cryptoStream = new CryptoStream(hashStream, _hashAlgorithm);
                _fileStream.CopyTo(cryptoStream);
                cryptoStream.FlushFinalBlock();
                return Convert.ToBase64String(hashStream.ToArray());
            }
        }

        public void ValidateHash(string expectedHash)
        {
            string computedHash = ComputeHash();
            if (!computedHash.Equals(expectedHash, StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException("Checksum mismatch");
            }
        }
    }

    public class Sha256Service
    {
        private readonly Queue<Sha256Hasher> _hashers;

        public Sha256Service()
        {
            _hashers = new Queue<Sha256Hasher>();
        }

        public void ComputeHashes(string[] filePaths, Action<string> hashHandler)
        {
            foreach (string filePath in filePaths)
            {
                Sha256Hasher hasher = new Sha256Hasher(filePath);
                _hashers.Enqueue(hasher);

                ThreadPool.QueueUserWorkItem((state) =>
                {
                    string computedHash = hasher.ComputeHash();
                    hashHandler(computedHash);
                }, null);
            }
        }

        public void ValidateHashes(string[] filePaths, string[] expectedHashes)
        {
            foreach (string filePath in filePaths)
            {
                Sha256Hasher hasher = _hashers.Dequeue();
                try
                {
                    hasher.ValidateHash(expectedHashes[Array.IndexOf(filenames, filePath)]);
                }
                catch (InvalidOperationException e)
                {
                    Console.WriteLine("Checksum mismatch: " + e.Message);
                }
            }
        }
    }

    public class Sha256Program
    {
        public static void Main(string[] args)
        {
            Sha256Service service = new Sha256Service();

            string[] filePaths = { "file1.txt", "file2.txt", "file3.txt" };
            string[] expectedHashes = { "hash1", "hash2", "hash3" };

            service.ComputeHashes(filePaths, (computedHash) =>
            {
                Console.WriteLine("Computed hash: " + computedHash);
            });

            service.ValidateHashes(filePaths, expectedHashes);

            Console.ReadLine();
        }
    }
}
