    int *semaphore_values = (int *)malloc(max_semaphores * sizeof(int));
    for (int i = 0; i < max_semaphores; i++) {
        semaphore_values[i] = json_object_get_int(jobj, fmtstr("semaphore_%d", i));
    }

    // Initialize dynamic semaphore pool
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int *semaphore_count = (int *)malloc(max_semaphores * sizeof(int));
    for (int i = 0; i < max_semaphores; i++) {
        pthread_mutex_init(&mutex, NULL);
        pthread_cond_init(&cond, NULL);
        semaphore_count[i] = 0;
    }

    // Start threads
    pthread_t threads[max_semaphores];
    for (int i = 0; i < max_semaphores; i++) {
        pthread_create(&threads[i], NULL, thread_func, &semaphore_values[i]);
    }

    // Wait for threads to finish
    for (int i = 0; i < max_semaphores; i++) {
        pthread_join(threads[i], NULL);
    }

    free(semaphore_count);
    free(semaphore_values);
