```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/socket.h>
#include <arpa/inet.h>

// Forward declaration
void *thread_handler(void *);

// Global variables
int log_level = 1; // Default log level (1: error, 2: warning, 3: info, 4: debug)
int buffer_size = 10000;
int max_messages_per_second = 10;
pthread_mutex_t lock;
pthread_cond_t cond;

// Buffer for messages
struct message {
    char *data;
} **buffer;

// Number of messages in the buffer
int num_messages = 0;

// Initialize the logging utility
void init_logging(int log_level_) {
    log_level = log_level_;
}

// Set the buffer size and maximum messages per second
void set_buffer_size(int size) {
    buffer_size = size;
}
void set_max_messages_per_second(int rate) {
    max_messages_per_second = rate;
}

// Start a logging thread
void start_logging() {
    pthread_t tid;

    // Create a new thread
    if (pthread_create(&tid, NULL, thread_handler, NULL)) {
        perror("Thread creation failed");
        exit(1);
    }
}

// Handle the logging thread
void *thread_handler(void *) {
    while (1) {
        // Acquire the lock and wait for messages
        pthread_mutex_lock(&lock);
        while (!num_messages) {
            pthread_cond_wait(&cond, &lock);
        }

        // Process messages
        for (int i = 0; i < num_messages; i++) {
            struct message *msg = buffer[i];
            if (log_level >= msg->data[0]) {
                // Log the message
                printf("%s\n", msg->data);
            }
            free(msg->data);
            free(msg);
        }

        // Clear the messages
        num_messages = 0;
        pthread_mutex_unlock(&lock);
    }
}

// Enqueue a message
void enqueue_message(char *message) {
    // Check if the buffer is full
    if (num_messages >= buffer_size) {
        return; // Buffer overflow
    }

    // Allocate memory for the new message
    struct message *msg = malloc(sizeof(struct message));
    msg->data = strdup(message);

    // Enqueue the message
    buffer[num_messages] = msg;
    num_messages++;

    // Signal to the logging thread that a new message is available
    pthread_cond_signal(&cond);
}

// Main function
int main() {
    int sockfd, connfd;

    // Initialize the socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);

    if (sockfd < 0) {
        perror("Socket creation failed");
        exit(1);
    }

    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(9000);

    // Connect to the server
    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection failed");
        exit(1);
    }

    close(sockfd);

    return 0;
}
