        self.log_services.append({"name": service_name, "url": service_url, "protocol": protocol})

    def set_config(self, config: Dict[str, Any]):
        self.config = config

    async def send_logs(self, logs: List[Any]) -> None:
        for log in logs:
            await self.send_log(log)

    async def send_log(self, log: Any) -> None:
        # adaptive polling interval logic
        if self.config.get("polling_interval", 1000) > self.calculate_polling_interval():
            self.config["polling_interval"] = self.calculate_polling_interval()

        for service in self.log_services:
            try:
                response = await send_log_request(service, log)
                if response.status == 200:
                    return
                elif response.status == 500 and service.get("retry", False):
                    await retry_log_submission(service, log)
                else:
                    raise Exception(f"Error submitting log to {service['name']}: {response.text}")
            except NetworkError as e:
                # handle network partitioning scenario
                if self.config.get("persistent_queuing", True):
                    await enqueue_log(log, service["name"])
