    // Destructor to release any allocated memory
    ~Message();

    // Getter for the message type
    std::string getType() const;

    // Getter for the message data
    std::string getData() const;
};

// ISO 8583 transaction processing class
class Transaction {
public:
    // Constructor to initialize a new transaction with a message and a processing callback
    Transaction(Message* msg, void (*callback)(Message*));

    // Destructor to release any allocated memory
    ~Transaction();

    // Process the transaction by calling the callback function
    void process() const;
};

// Library for dynamic loading of message types via plugins
class MessageLibrary {
public:
    // Register a new message type with its processing plugin
    static void registerMessage(std::string type, void (*plugin)(Message*));

    // Load and process an ISO 8583 transaction message
    static void processTransaction(Message* msg);
};

// Plugin for processing debit transactions
class DebitPlugin {
public:
    void operator()(Message* msg) const;
};

// Plugin for processing credit transactions
class CreditPlugin {
public:
    void operator()(Message* msg) const;
};

// ISO 8583 transaction message queue class
class MessageQueue {
public:
    // Constructor to initialize the message queue with a name and a thread count
    MessageQueue(std::string name, int threads);

    // Destructor to release any allocated memory
    ~MessageQueue();

    // Enqueue a new message for processing
    void enqueue(Message* msg);

    // Dequeue and process the next available message
    void dequeue() const;
};

// ISO 8583 transaction message processor class
class MessageProcessor {
public:
    // Constructor to initialize the message processor with a thread count and a message queue
    MessageProcessor(int threads, MessageQueue* queue);

    // Destructor to release any allocated memory
    ~MessageProcessor();

    // Start processing messages in separate threads
    void start() const;
};

// ISO 8583 transaction application class
class TransactionApp {
public:
    // Constructor to initialize the transaction app with a message library and a message processor
    TransactionApp(MessageLibrary* lib, MessageProcessor* proc);

    // Destructor to release any allocated memory
    ~TransactionApp();

    // Start processing transactions from external payment gateways and banking APIs
    void startProcessing() const;
};

