    // Initialize the transaction app with a message library and a message processor
    TransactionApp app(&MessageLibrary::getInstance(), &MessageProcessor::getInstance());

    // Start processing transactions from external payment gateways and banking APIs
    app.startProcessing();

    return 0;
}

