        : deviceId(deviceId), readings(readings) {}
};

class DataIngestionPipeline {
private:
    std::queue<SensorData> sensorQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondition;

public:
    void enqueue(const SensorData& data) {
        std::unique_lock<std::mutex> lock(queueMutex);
        sensorQueue.push(data);
        lock.unlock();
        queueCondition.notify_one();
    }

    void dequeue() {
        std::unique_lock<std::mutex> lock(queueMutex);
        while (sensorQueue.empty()) {
            queueCondition.wait(lock);
        }
        SensorData data = sensorQueue.front();
        sensorQueue.pop();
        lock.unlock();
    }
};

class DataProcessor {
private:
    DataIngestionPipeline pipeline;
    std::vector<std::thread> processingThreads;

