// Data structure for sensor readings
struct SensorReading {
    int deviceId;
    std::string sensorType;
    double value;
};

// Thread-safe queue for storing sensor readings
class SensorQueue {
public:
    void push(const SensorReading& reading) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(reading);
    }

    bool tryPop(SensorReading& reading) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (queue_.empty()) return false;
        reading = queue_.front();
        queue_.pop();
        return true;
    }

private:
    std::mutex mutex_;
    std::queue<SensorReading> queue_;
};

// Data structure for storing sensor data streams
class SensorStream {
public:
    int deviceId;
    SensorQueue readings;

    SensorStream(int deviceId) : deviceId(deviceId), readings() {}
};

// Thread-safe map for storing sensor streams
class SensorStreams {
public:
    void insert(int deviceId, SensorStream& stream) {
        std::unique_lock<std::mutex> lock(mutex_);
        streams_[deviceId] = stream;
    }

    bool tryGet(int deviceId, SensorStream& stream) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (streams_.find(deviceId) == streams_.end()) return false;
        stream = streams_[deviceId];
        return true;
    }

private:
