#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define constants for NIC statistics management
#define M 100 // Maximum number of interfaces
#define N 10 // Maximum number of concurrent threads

// Structure to represent a single interface's statistics
typedef struct {
    int rx_packets;
    int tx_packets;
    int rx_bytes;
    int tx_bytes;
} nic_stats_t;

// Global array to store NIC statistics
nic_stats_t stats[M];

// Mutex for concurrent access to global array
pthread_mutex_t stats_mutex = PTHREAD_MUTEX_INITIALIZER;

// Semaphore for limiting concurrent updates to the global array
sem_t stats_sem;

// Function to update interface statistics
void update_stats(int ifindex, int packets, int bytes) {
    pthread_mutex_lock(&stats_mutex);
    sem_wait(&stats_sem);

    // Update statistics for the given interface
    stats[ifindex].rx_packets += packets;
    stats[ifindex].tx_packets += packets;
    stats[ifindex].rx_bytes += bytes;
    stats[ifindex].tx_bytes += bytes;

    sem_post(&stats_sem);
    pthread_mutex_unlock(&stats_mutex);
}

// Function to get interface statistics
void get_stats(int ifindex, nic_stats_t* stats) {
    pthread_mutex_lock(&stats_mutex);
    sem_wait(&stats_sem);

    // Copy statistics for the given interface
    *stats = stats[ifindex];

    sem_post(&stats_sem);
    pthread_mutex_unlock(&stats_mutex);
}

// Function to initialize the NIC statistics management library
void nic_stats_init() {
    int i;
    for (i = 0; i < M; i++) {
        stats[i].rx_packets = 0;
        stats[i].tx_packets = 0;
        stats[i].rx_bytes = 0;
        stats[i].tx_bytes = 0;
    }
}

// Function to deinitialize the NIC statistics management library
void nic_stats_deinit() {
    // Release resources and free memory
}
