    int timestamp;
    int source_id;
    int destination_id;
    char* payload;
} DataPacket;

// Define the modular C library for managing dynamic arrays of DataPackets
void init_data_packet_array(DataPacket** array, size_t capacity) {
    *array = (DataPacket*)malloc(sizeof(DataPacket) * capacity);
}

void add_data_packet(DataPacket** array, size_t* capacity, size_t index, DataPacket packet) {
    if (index >= *capacity) {
        // Handle reallocation and resizing
        size_t new_capacity = (*capacity) * 2;
        *array = (DataPacket*)realloc(*array, sizeof(DataPacket) * new_capacity);
        *capacity = new_capacity;
    }
    memcpy(&((*array)[index]), &packet, sizeof(DataPacket));
}

void delete_data_packet(DataPacket** array, size_t capacity, size_t index) {
    // Handle shifting packets upon deletion
    for (size_t i = index; i < capacity - 1; i++) {
        memcpy(&((*array)[i]), &((*array)[i + 1]), sizeof(DataPacket));
    }
    // Free the deleted packet's memory
    free(((DataPacket*)array)[capacity-1].payload);
}

void serialize_data_packets(DataPacket** array, size_t capacity, FILE* file) {
    for (size_t i = 0; i < capacity; i++) {
        fwrite(&((*array)[i]), sizeof(DataPacket), 1, file);
    }
}

// Integrate with an external logging system
