// Define a DataPacket structure
struct DataPacket {
    int id;
    std::string data;
};

// C library for managing dynamic array of DataPackets
class DataPacketManager {
public:
    // Initialize the manager with initial capacity
    DataPacketManager(int capacity) : capacity_(capacity), size_(0), packets_(new DataPacket[capacity]) {}

    // Add a new packet to the array
    void addPacket(const DataPacket& packet) {
        if (size_ == capacity_) {
            std::cout << "Array full. Resizing...\n";
            resize();
        }
        packets_[size_++] = packet;
    }

    // Remove a packet from the array
    void removePacket(int id) {
        for (int i = 0; i < size_; ++i) {
            if (packets_[i].id == id) {
                std::memmove(&packets_[i], &packets_[i + 1], sizeof(DataPacket) * (size_ - i - 1));
                --size_;
                return;
            }
        }
    }

    // Serialize the array to a string
    std::string serialize() const {
        std::stringstream ss;
        for (int i = 0; i < size_; ++i) {
            ss << "Packet " << packets_[i].id << ": " << packets_[i].data << "\n";
        }
        return ss.str();
    }

private:
    // Resize the array if it's full
    void resize() {
        int newCapacity = capacity_ * 2;
        DataPacket* newPackets = new DataPacket[newCapacity];
        std::copy(packets_, packets_ + size_, newPackets);
        delete[] packets_;
        packets_ = newPackets;
        capacity_ = newCapacity;
    }

    int capacity_;
    int size_;
    DataPacket* packets_;
};

// External logging system
class Logger {
public:
    void log(const std::string& message) const {
        // Implement logging mechanism here
    }
};

// Third-party data compression library
