// Initialize the NIC statistics manager
nic_statistics_manager* init_nic_statistics_manager(int max_num_interfaces) {
    nic_statistics_manager* manager = (nic_statistics_manager*)malloc(sizeof(nic_statistics_manager));
    manager->num_interfaces = 0;
    manager->records = (nic_stats_record*)calloc(max_num_interfaces, sizeof(nic_stats_record));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Update NIC statistics records
void update_nic_statistics_manager(nic_statistics_manager* manager, int interface_id, nic_stats_record record) {
    pthread_mutex_lock(&manager->lock);
    if (manager->num_interfaces < MAX_INTERFACES) {
        manager->records[interface_id] = record;
        manager->num_interfaces++;
    }
    pthread_mutex_unlock(&manager->lock);
}

