class GeolocationCache {
public:
    GeolocationCache(int K) : regions_(K), update_queue_() {}

    void updateRegion(int regionId, double latitude, double longitude, int population, std::vector<std::pair<int, double>> temperatureHumidity) {
        std::lock_guard<std::mutex> lock(mutex_);
        regions_[regionId] = {latitude, longitude, population, temperatureHumidity};
        update_queue_.push(regionId);
    }

    void queryRegion(int regionId, bool& found, int& population, std::vector<int>& temperatures, std::vector<double>& humidities) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = regions_.find(regionId);
        if (it != regions_.end()) {
            found = true;
            population = it->second.population;
            temperatures = it->second.temperatureHumidity | [](const auto& v) { return {v.first}; };
            humidities = it->second.temperatureHumidity | [](const auto& v) { return {v.second}; };
        }
    }

    void fetchUpdates() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            update_queue_.wait(lock, [this] { return !update_queue_.empty(); });
            int regionId = update_queue_.front();
            update_queue_.pop();

            // Simulate fetching updates from weather API
            double latitude = 37.7749;
            double longitude = -122.4194;
            int population = 8000000;
            std::vector<std::pair<int, double>> temperatureHumidity = {{1, 20}, {2, 25}};

            // Update cache and notify waiting threads
            lock.unlock();
            updateRegion(regionId, latitude, longitude, population, temperatureHumidity);
            cv_.notify_all();
        }
    }

private:
    std::unordered_map<int, GeolocationRecord> regions_;
    std::queue<int> update_queue_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
};

struct GeolocationRecord {
    double latitude;
    double longitude;
    int population;
    std::vector<std::pair<int, double>> temperatureHumidity;
};
