import java.util.*;
import java.io.*;

public class MessageBroker {

    // In-memory queue for storing messages
    private Map<String, Queue<Message>> messageQueue = new HashMap<>();

    // Persistent storage for data durability
    private FileStore fileStore;

    // Authentication mechanism
    private Authenticator authenticator;

    // API endpoint for managing topics and subscriptions
    private RestAPI restAPI;

    public MessageBroker() {
        this.fileStore = new FileStore();
        this.authenticator = new BasicAuthenticator();
        this.restAPI = new RestAPI(this);
    }

    public void start() {
        // Start file storage service
        fileStore.start();

        // Start authentication mechanism
        authenticator.start();

        // Start REST API endpoint
        restAPI.start();
    }

    public void stop() {
        // Stop file storage service
        fileStore.stop();

        // Stop authentication mechanism
        authenticator.stop();

        // Stop REST API endpoint
        restAPI.stop();
    }

    public void publish(Message message) {
        // Get the queue for the topic
        Queue<Message> queue = messageQueue.computeIfAbsent(message.getTopic(), k -> new LinkedBlockingQueue<>());

        // Add the message to the queue
        queue.add(message);
    }

    public void subscribe(String topic, String consumerId) {
        // Create a subscription for the topic and consumer ID
        Subscription subscription = new Subscription(topic, consumerId);

        // Add the subscription to the list of subscriptions
        List<Subscription> subscriptions = messageQueue.getOrDefault(subscription.getTopic(), new ArrayList<>());
        subscriptions.add(subscription);
    }

    public void acknowledge(String topic, String consumerId) {
        // Find the subscription for the topic and consumer ID
        Subscription subscription = getSubscription(topic, consumerId);

        // Acknowledge the messages in the subscription's queue
        Queue<Message> queue = messageQueue.getOrDefault(subscription.getTopic(), new ArrayList<>());
        while (!queue.isEmpty()) {
            Message message = queue.poll();
            if (message != null) {
                // Send acknowledgement to the consumer
                sendAck(subscription, message);
            }
        }
    }

    private Subscription getSubscription(String topic, String consumerId) {
        // Search for the subscription in the list of subscriptions
        List<Subscription> subscriptions = messageQueue.getOrDefault(topic, new ArrayList<>());
        for (Subscription subscription : subscriptions) {
            if (subscription.getConsumerId().equals(consumerId)) {
                return subscription;
            }
        }
        return null;
    }

    private void sendAck(Subscription subscription, Message message) {
