package com.example.financialtransactions;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.stream.Collectors;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.clients.producer.ProducerRecord;

public class FinancialTransactionProcessor {
    private static final int NUMBER_OF_THREADS = 100;
    private static final int NUMBER_OF_SCHEDULED_TASKS = 10;
    private static final String KAFKA_BOOTSTRAP_SERVERS = "localhost:9092";
    private static final String TOPIC_NAME = "financial_transactions";

    public FinancialTransactionProcessor() {
        ExecutorService executorService = Executors.newFixedThreadPool(NUMBER_OF_THREADS);
        ScheduledExecutorService scheduledExecutorService = Executors.newScheduledThreadPool(NUMBER_OF_SCHEDULED_TASKS);

        KafkaProducer<String, String> kafkaProducer = new KafkaProducer<>();
        kafkaProducer.configure(ProducerConfig.createProperties()
                .put("bootstrap.servers", KAFKA_BOOTSTRAP_SERVERS)
                .put("acks", "all")
                .put("retries", 0));

        // Start processing transactions
        startProcessingTransactions(executorService, scheduledExecutorService, kafkaProducer);
    }

    private void startProcessingTransactions(ExecutorService executorService, ScheduledExecutorService scheduledExecutorService, KafkaProducer<String, String> kafkaProducer) {
        // Process transactions concurrently using a thread pool
        executorService.submit(() -> processTransactions(kafkaProducer));

        // Periodically check for and handle payment gateway outages
        scheduledExecutorService.scheduleAtFixedRate(() -> handleGatewayOutages(), 1, 60 * 1000, TimeUnit.MILLISECONDS);

        // Start consuming messages from Kafka topic
        kafkaProducer.send(new ProducerRecord<>(TOPIC_NAME, "transaction", "{\"amount\": 10.00}"));
    }

    private void processTransactions(KafkaProducer<String, String> kafkaProducer) {
        // Process transactions concurrently using a thread pool
        executorService.submit(() -> {
            while (true) {
                KafkaConsumer<String, String> consumer = new KafkaConsumer<>();
                ConsumerRecords<String, String> records = consumer.poll(100);
                for (ConsumerRecord<String, String> record : records) {
                    try {
                        // Validate and process transaction data
                        String transactionData = record.value();
                        if (isValidTransaction(transactionData)) {
                            // Process transaction successfully
                        } else {
                            // Handle invalid transaction
                        }
                    } catch (Exception e) {
                        // Handle error
                    }
                }
                consumer.commitSync();
            }
        });
    }

    private boolean isValidTransaction(String transactionData) {
        // Validate transaction data based on your requirements
        return true;
    }

    private void handleGatewayOutages() {
        // Periodically check for payment gateway outages and retry failed transactions
        kafkaProducer.send(new ProducerRecord<>(TOPIC_NAME, "transaction", "{\"amount\": 10.00}"));
    }
}
