    uint64_t byte_count;
    time_t timestamp;
} nic_stats;

// Function to initialize the library
void init_library() {
    // Initialize the cache with a default eviction policy (time-based)
    set_cache_eviction_policy(CACHE_TIME_BASED);
}

// Function to get the current NIC statistics record for an interface
nic_stats* get_nic_stats(int interface) {
    // Retrieve the cached record or fetch from the monitoring API if not available
    nic_stats* stats = cache_get(interface);
    if (!stats) {
        // Fetch the record from the monitoring API
        stats = fetch_nic_stats_from_api(interface);
        cache_set(stats, interface);
    }
    return stats;
}

// Function to update an NIC statistics record with new values
void update_nic_stats(int interface, uint32_t packet_count, uint64_t byte_count) {
    // Update the cached record or fetch from the monitoring API if not available
    nic_stats* stats = cache_get(interface);
    if (stats) {
        stats->packet_count += packet_count;
        stats->byte_count += byte_count;
        stats->timestamp = time(NULL);
        cache_set(stats, interface);
    } else {
        // Fetch the record from the monitoring API and update it
        nic_stats* new_stats = fetch_nic_stats_from_api(interface);
        if (new_stats) {
            new_stats->packet_count += packet_count;
            new_stats->byte_count += byte_count;
            new_stats->timestamp = time(NULL);
            cache_set(new_stats, interface);
        }
    }
}

// Function to trigger an event based on a custom alert condition
void trigger_alert(int interface, uint32_t threshold) {
    // Evaluate the alert condition (e.g., packet count exceeds threshold)
    nic_stats* stats = get_nic_stats(interface);
    if (stats->packet_count > threshold) {
        // Trigger the event and send notifications to configured recipients
        send_alert_notification(interface, "Packet count exceeded");
    }
}

// Function to integrate with a third-party monitoring API for real-time data reporting
void report_data_to_api(int interface) {
    // Fetch the current NIC statistics record and send it to the API
    nic_stats* stats = get_nic_stats(interface);
    if (stats) {
        // Send the data to the API using TLS encryption and secure connection
        send_data_to_api(stats->packet_count, stats->byte_count, stats->timestamp);
    }
}

// Function to configure the library through environment variables and a YAML-based configuration file
void config_library() {
    // Parse the YAML configuration file for interface-specific parameters
    yaml_config_file();
    // Set environment variables for polling intervals and thresholds
    set_environment_variables();
