namespace OrderProcessingPipeline
{
    public class OrderProcessingPipeline
    {
        private readonly ILogger<OrderProcessingPipeline> _logger;
        private readonly DbContextOptions<DatabaseContext> _options;
        private readonly DatabaseContext _db;
        private readonly NoSqlStore _nsql;
        private readonly ApiTokenManager _apiTokenManager;

        public OrderProcessingPipeline(ILogger<OrderProcessingPipeline> logger, 
            DbContextOptions<DatabaseContext> options, DatabaseContext db, 
            NoSqlStore nsql, ApiTokenManager apiTokenManager)
        {
            _logger = logger;
            _options = options;
            _db = db;
            _nsql = nsql;
            _apiTokenManager = apiTokenManager;
        }

        public async Task ProcessOrderAsync(Order order)
        {
            // Validate order data
            if (!ValidateOrder(order))
                throw new ArgumentException("Invalid order data");

            try
            {
                // Start transaction
                using var transaction = await _db.Database.BeginTransactionAsync();

                try
                {
                    // Validate and process order in relational database
                    await ProcessOrderInDbAsync(order);

                    // Update NoSQL store with order status
                    await _nsql.UpdateOrderStatusAsync(order.Id, order.Status);

                    // Renew API tokens (if necessary)
                    await _apiTokenManager.RenewTokensAsync();

                    // Commit transaction
                    await transaction.CommitAsync();
                }
                catch (Exception ex) when (ShouldRetry(ex))
                {
                    // Rollback transaction on retry failure
                    await transaction.RollbackAsync();

                    // Wait for circuit breaker to open before retrying
                    await Policy.WaitAndRetry()
                        .WaitAsync(() => ProcessOrderAsync(order));
                }
            }
            finally
            {
                // Log critical events
                _logger.LogInformation("Order processed");
            }
        }

        private async Task ProcessOrderInDbAsync(Order order)
        {
            // Use parameterized query for performance and security
            using var command = _db.Database.GetDbConnection().CreateCommand();
            await command.ExecuteNonQueryAsync("INSERT INTO orders (id, status) VALUES (@id, @status)", 
                new { id = order.Id, status = order.Status });

            // Cache frequently accessed data
