class DataTransferUtility {
  constructor(apiUrl) {
    this.apiUrl = apiUrl;
    this.bufferPool = [];
    this.concurrentRequests = 0;
    this.requestQueue = [];
  }

  async copyRange(byteRange, callback) {
    const { start, end } = byteRange;

    if (start > end || start < 0 || end >= Buffer.byteLength(buffer)) {
      throw new Error('Invalid byte range');
    }

    if (end - start + 1 > Buffer.byteLength(buffer)) {
      // Handle cases where requested byte count exceeds total available data
      const maxBytes = Buffer.byteLength(buffer) - start;
      callback({ bytes: buffer.slice(start, start + maxBytes) });
    } else {
      // Manage scenarios where data chunks originate from different sources with varying data rates and sizes
      await new Promise((resolve) => {
        this.requestQueue.push({
          byteRange,
          callback,
          resolve,
        });

        if (this.concurrentRequests++ > 0) {
          return;
        }

        this.processRequestQueue();
      });
    }
  }

  async processRequestQueue() {
    const request = this.requestQueue.shift();

    try {
      const response = await fetch(`${this.apiUrl}/${request.byteRange.start}`);
      const bufferChunk = await response.arrayBuffer();
      request.callback({ bytes: bufferChunk });

      if (this.requestQueue.length > 0) {
        this.processRequestQueue();
      } else {
        this.concurrentRequests--;
      }
    } catch (error) {
      // Handle edge cases, such as empty buffers, invalid byte ranges, or failed API calls
      request.callback({ error });
      this.concurrentRequests--;

      if (this.requestQueue.length > 0) {
        this.processRequestQueue();
      }
    }
  }

  async close() {
    await Promise.all(this.bufferPool.map((buffer) => buffer.destroy()));
  }
}

