class NetworkMonitorRecord {
public:
    std::string sourceIp;
    std::string destinationIp;
    int byteCount;
    long long time_stamp;
    int flowId;
    int protocolType;

    NetworkMonitorRecord(std::string sourceIp, std::string destinationIp, int byteCount, long long time_stamp, int flowId, int protocolType)
        : sourceIp(sourceIp), destinationIp(destinationIp), byteCount(byteCount), time_stamp(time_stamp), flowId(flowId), protocolType(protocolType) {}
};

class NetworkMonitor {
public:
    using RecordPool = std::vector<NetworkMonitorRecord*, std::allocator<NetworkMonitorRecord*>>;

    NetworkMonitor(size_t initialCapacity) : recordPool_(initialCapacity) {}

    void addRecord(NetworkMonitorRecord* record) {
        if (recordPool_.size() >= capacity_) {
            // Resize the pool when it's full
            resizePool();
        }
        recordPool_.push_back(record);
    }

    NetworkMonitorRecord* getRecord(int index) const {
        return recordPool_[index];
    }

private:
    void resizePool() {
        size_t newCapacity = 2 * capacity_ + 1;
        RecordPool newPool(newCapacity);
        for (NetworkMonitorRecord* record : recordPool_) {
            newPool.push_back(record);
        }
        recordPool_.swap(newPool);
        capacity_ = newCapacity;
    }

    RecordPool recordPool_;
    size_t capacity_{0};
};

int main() {
    NetworkMonitor networkMonitor(10);

    for (int i = 0; i < 100; ++i) {
        // Create a new NetworkMonitorRecord instance
        NetworkMonitorRecord* record = new NetworkMonitorRecord("192.168.1.1", "8.8.8.8", i, i * 1000000LL, i % 2, i % 4);

        networkMonitor.addRecord(record);
    }

    // Print out the records
    for (int i = 0; i < networkMonitor.recordPool_.size(); ++i) {
        NetworkMonitorRecord* record = networkMonitor.getRecord(i);
        std::cout << "Source IP: " << record->sourceIp << ", Destination IP: " << record->destinationIp << ", Byte Count: " << record->byteCount
                  << ", Time Stamp: " << record->time_stamp << ", Flow ID: " << record->flowId << ", Protocol Type: " << record->protocolType << std::endl;
    }

    return 0;
}
```

