    private void processIoTDeviceEvent(Event event) {
        // Real-Time Performance Optimization
        if (isPeakHour()) {
            // Optimize for peak hours
            processEventInParallel(event);
        } else {
            // Optimize for off-peak hours
            processEventSequentially(event);
        }
    }

    private boolean isPeakHour() {
        // Scalability and Cost Management
        return System.currentTimeMillis() % 3600000 < 1800000;
    }

    private void processEventInParallel(Event event) {
